window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["1CO"]={"book":"1CO","editions":{"dan-1819":[[1,1,"Paulus, kaldet til Jesu Christi Apostel ved Guds Villie, og Broderen Sosthenes,","Paulus, kaldet til Jesu Christi Apostel ved Guds Villie, og Broderen Sosthenes,"],[1,2,"til Guds Menighed, som er i Corinth, de Helligede i Christus Jesus, de kaldte Hellige, med alle dem, som paa ethvert Sted paakalde vor Herres Jesu Christi, deres og vor Herres, Navn:","til Guds Menighed, som er i Corinth, de Helligede i Christus Jesus, de kaldte Hellige, med alle dem, som paa ethvert Sted paakalde vor Herres Jesu Christi, deres og vor Herres, Navn:"],[1,3,"Naade være med Eder og Fred fra Gud vor Fader og den Herre Jesus Christus!","Naade være med Eder og Fred fra Gud vor Fader og den Herre Jesus Christus!"],[1,4,"Jeg takker min Gud altid for Eder, for den Guds Naade, som er given Eder i Christus Jesus,","Jeg takker min Gud altid for Eder, for den Guds Naade, som er given Eder i Christus Jesus,"],[1,5,"at I ved ham ere gjort rige i Alt, i al Lære og al Kundskab,","at I ved ham ere gjort rige i Alt, i al Lære og al Kundskab,"],[1,6,"ligesom og det Vidnesbyrd om Christus er bleven befæstet hos Eder,","ligesom og det Vidnesbyrd om Christus er bleven befæstet hos Eder,"],[1,7,"saa at Eder ikke fattes paa nogen Naadegave, idet I forvente vor Herres Jesu Christi Aabenbarelse,","saa at Eder ikke fattes paa nogen Naadegave, idet I forvente vor Herres Jesu Christi Aabenbarelse,"],[1,8,"som og skal stadfæste Eder indtil Enden, ustraffelige paa vor Herres Jesu Christi Dag.","som og skal stadfæste Eder indtil Enden, ustraffelige paa vor Herres Jesu Christi Dag."],[1,9,"Gud er trofast, ved hvem I ere kaldte til hans Søns, Jesu Christi, vor Herres Samfund.","Gud er trofast, ved hvem I ere kaldte til hans Søns, Jesu Christi, vor Herres Samfund."],[1,10,"Men jeg formaner Eder, Brødre! ved vor Herres Jesu Christi Navn, at I alle føre den samme Tale, og at der ikke maa findes Splidagtigheder iblandt Eder, men at I skulle være forenede i det samme Sind og i den samme Mening.","Men jeg formaner Eder, Brødre! ved vor Herres Jesu Christi Navn, at I alle føre den samme Tale, og at der ikke maa findes Splidagtigheder iblandt Eder, men at I skulle være forenede i det samme Sind og i den samme Mening."],[1,11,"Thi mig er tilkjendegivet om Eder, mine Brødre! af Chloes Huusfolk, at der ere Trætter iblandt Eder.","Thi mig er tilkjendegivet om Eder, mine Brødre! af Chloes Huusfolk, at der ere Trætter iblandt Eder."],[1,12,"Jeg mener nemlig, at enhver af Eder siger: jeg er Paulus’, eller: jeg er Apollos’, eller: jeg er Kephas’, eller jeg er Christi.","Jeg mener nemlig, at enhver af Eder siger: jeg er Paulus’, eller: jeg er Apollos’, eller: jeg er Kephas’, eller jeg er Christi."],[1,13,"Er da Christus deelt? mon Paulus være korsfæstet for Eder? eller ere I døbte til Paulus’ Navn?","Er da Christus deelt? mon Paulus være korsfæstet for Eder? eller ere I døbte til Paulus’ Navn?"],[1,14,"Jeg takker Gud, at jeg ingen af Eder haver døbt, uden Crispus og Cajus,","Jeg takker Gud, at jeg ingen af Eder haver døbt, uden Crispus og Cajus,"],[1,15,"paa det ikke Nogen skal sige, at jeg haver døbt til mit Navn.","paa det ikke Nogen skal sige, at jeg haver døbt til mit Navn."],[1,16,"Dog døbte jeg ogsaa Stephanas’ Huusfolk; ellers veed jeg ikke, at jeg haver døbt nogen Anden.","Dog døbte jeg ogsaa Stephanas’ Huusfolk; ellers veed jeg ikke, at jeg haver døbt nogen Anden."],[1,17,"Thi Christus sendte mig ikke for at døbe, men for at prædike Evangelium, ikke med vise Ord, at Christi Kors ikke skulde tabe sin Kraft.","Thi Christus sendte mig ikke for at døbe, men for at prædike Evangelium, ikke med vise Ord, at Christi Kors ikke skulde tabe sin Kraft."],[1,18,"Thi det Korsens Ord er vel dem en Daarlighed, som blive fortabte, men os, som blive salige, er det en Guds Kraft.","Thi det Korsens Ord er vel dem en Daarlighed, som blive fortabte, men os, som blive salige, er det en Guds Kraft."],[1,19,"Thi der er skrevet: jeg vil forkaste de Vises Viisdom og tilintetgjøre de Forstandiges Forstand.","Thi der er skrevet: jeg vil forkaste de Vises Viisdom og tilintetgjøre de Forstandiges Forstand."],[1,20,"Hvor ere de Vise? hvor de Skriftkloge? hvor denne Verdens Grandskere? haver Gud ikke gjort denne Verdens Viisdom til Daarlighed?","Hvor ere de Vise? hvor de Skriftkloge? hvor denne Verdens Grandskere? haver Gud ikke gjort denne Verdens Viisdom til Daarlighed?"],[1,21,"Thi efterdi Verden for idel Viisdom ikke erkjendte Gud i hans Viisdom, da behagede det Gud formedelst denne Prædikens Daarlighed at gjøre dem salige, som troe.","Thi efterdi Verden for idel Viisdom ikke erkjendte Gud i hans Viisdom, da behagede det Gud formedelst denne Prædikens Daarlighed at gjøre dem salige, som troe."],[1,22,"Saasom baade Jøderne æske Tegn, og Grækerne søge Viisdom;","Saasom baade Jøderne æske Tegn, og Grækerne søge Viisdom;"],[1,23,"men vi prædike den korsfæstede Christus, som er Jøderne en Forargelse og Grækerne en Daarlighed;","men vi prædike den korsfæstede Christus, som er Jøderne en Forargelse og Grækerne en Daarlighed;"],[1,24,"men de, som ere kaldte, baade Jøder og Græker, prædike vi Christus, Guds Kraft og Guds Viisdom.","men de, som ere kaldte, baade Jøder og Græker, prædike vi Christus, Guds Kraft og Guds Viisdom."],[1,25,"Thi det Daarlige fra Gud er visere end Menneskenes Viisdom, og det Skrøbelige fra Gud er stærkere end Menneskenes Styrke.","Thi det Daarlige fra Gud er visere end Menneskenes Viisdom, og det Skrøbelige fra Gud er stærkere end Menneskenes Styrke."],[1,26,"Betragter, Brødre! hvo I ere, som bleve kaldte: ikke mange Vise efter Kjødet, ikke mange Mægtige, ikke mange fornemme;","Betragter, Brødre! hvo I ere, som bleve kaldte: ikke mange Vise efter Kjødet, ikke mange Mægtige, ikke mange fornemme;"],[1,27,"men det for Verden Daarlige udvalgte Gud, for at beskæmme de Vise, og det for Verden Skrøbelige udvalgte Gud, for at beskæmme det Stærke;","men det for Verden Daarlige udvalgte Gud, for at beskæmme de Vise, og det for Verden Skrøbelige udvalgte Gud, for at beskæmme det Stærke;"],[1,28,"og det for Verden Uædle og det Ringeagtede udvalgte Gud, og det, som Intet var, for at tilintetgjøre det, som var Noget;","og det for Verden Uædle og det Ringeagtede udvalgte Gud, og det, som Intet var, for at tilintetgjøre det, som var Noget;"],[1,29,"paa det intet Kjød skal rose sig for ham.","paa det intet Kjød skal rose sig for ham."],[1,30,"Men ved ham ere I udi Christus Jesus, hvilken er bleven os Viisdom fra Gud, og Retfærdighed, og Helliggjørelse, og Forløsning;","Men ved ham ere I udi Christus Jesus, hvilken er bleven os Viisdom fra Gud, og Retfærdighed, og Helliggjørelse, og Forløsning;"],[1,31,"saa at, som skrevet er: hvo sig roser, rose sig i Herren.","saa at, som skrevet er: hvo sig roser, rose sig i Herren."],[2,1,"Og, jeg Brødre! der jeg kom til Eder, kom jeg ikke med prægtige Ord eller Viisdom, at forkynde Eder det Guds Vidnesbyrd;","Og, jeg Brødre! der jeg kom til Eder, kom jeg ikke med prægtige Ord eller Viisdom, at forkynde Eder det Guds Vidnesbyrd;"],[2,2,"thi jeg agtede mig ikke at vide Noget iblandt Eder, uden Jesus Christus, og ham korsfæstet;","thi jeg agtede mig ikke at vide Noget iblandt Eder, uden Jesus Christus, og ham korsfæstet;"],[2,3,"og jeg var hos Eder med Ydmyghed og med Frygt og med megen Bæven,","og jeg var hos Eder med Ydmyghed og med Frygt og med megen Bæven,"],[2,4,"og mit Ord og min Prædiken var ikke i menneskelig Viisdoms overtalende Ord, men i Aands og Kraftes Beviisning,","og mit Ord og min Prædiken var ikke i menneskelig Viisdoms overtalende Ord, men i Aands og Kraftes Beviisning,"],[2,5,"at Eders Tro ikke skulde være i Menneskens Viisdom, men i Guds Kraft.","at Eders Tro ikke skulde være i Menneskens Viisdom, men i Guds Kraft."],[2,6,"Men Viisdom tale vi iblandt de Fuldkomne, dog ikke denne Verdens Viisdom, ikke heller denne Verdens Øversters, hvilke skulle beskæmmes;","Men Viisdom tale vi iblandt de Fuldkomne, dog ikke denne Verdens Viisdom, ikke heller denne Verdens Øversters, hvilke skulle beskæmmes;"],[2,7,"men vi tale Guds Viisdom, den hemmelighedsfulde, den, som var skjult, hvilken Gud haver forud beskikket før Verdens Begyndelse, til vor Herlighed,","men vi tale Guds Viisdom, den hemmelighedsfulde, den, som var skjult, hvilken Gud haver forud beskikket før Verdens Begyndelse, til vor Herlighed,"],[2,8,"hvilken ingen af denne Verdens Øverster kjendte; thi havde de kjendt den, havde de ikke korsfæstet Herlighedens Herre;","hvilken ingen af denne Verdens Øverster kjendte; thi havde de kjendt den, havde de ikke korsfæstet Herlighedens Herre;"],[2,9,"men, som skrevet er: hvad intet Øie har seet, og intet Øre har hørt, og ikke er opkommet i noget Menneskes Hjerte, hvad Gud haver beredt dem, som han elske.","men, som skrevet er: hvad intet Øie har seet, og intet Øre har hørt, og ikke er opkommet i noget Menneskes Hjerte, hvad Gud haver beredt dem, som han elske."],[2,10,"Men os aabenbarede Gud det formedelst sin Aand; thi Aanden ransager alle Ting, ogsaa Guds Dybheder.","Men os aabenbarede Gud det formedelst sin Aand; thi Aanden ransager alle Ting, ogsaa Guds Dybheder."],[2,11,"Hvilket Menneske veed det, som er i Mennesket, uden Menneskets Aand, som er i ham? Saa veed og Ingen det, som er i Gud, uden Guds Aand.","Hvilket Menneske veed det, som er i Mennesket, uden Menneskets Aand, som er i ham? Saa veed og Ingen det, som er i Gud, uden Guds Aand."],[2,12,"Og vi have ikke annammet Verdens Aand, men den Aand, som er af Gud, paa det vi kunne kjende, hvad der er os skjenket af Gud;","Og vi have ikke annammet Verdens Aand, men den Aand, som er af Gud, paa det vi kunne kjende, hvad der er os skjenket af Gud;"],[2,13,"hvilket vi og tale, ikke med Ord, som menneskelig Viisdom lærer, men med Ord, som den Hellig Aand lærer, idet vi tolke aandelige Ting med aandelige Ord.","hvilket vi og tale, ikke med Ord, som menneskelig Viisdom lærer, men med Ord, som den Hellig Aand lærer, idet vi tolke aandelige Ting med aandelige Ord."],[2,14,"Men det sanselige Menneske fatter ikke de Ting, som høre Guds Aand til; thi de ere ham en Daarlighed, og han kan ikke kjende dem, thi de dømmes aandeligen.","Men det sanselige Menneske fatter ikke de Ting, som høre Guds Aand til; thi de ere ham en Daarlighed, og han kan ikke kjende dem, thi de dømmes aandeligen."],[2,15,"Men den Aandelige dømmer vel alle Ting, selv derimod dømmes han af Ingen.","Men den Aandelige dømmer vel alle Ting, selv derimod dømmes han af Ingen."],[2,16,"Thi hvo haver kjendt Herrens Sind, at han kunde undervise ham? Men vi have Christi Sind.","Thi hvo haver kjendt Herrens Sind, at han kunde undervise ham? Men vi have Christi Sind."],[3,1,"Og jeg, Brødre! kunde ikke tale med Eder, som med Aandelige, men som med Kjødelige, som med Børn i Christus.","Og jeg, Brødre! kunde ikke tale med Eder, som med Aandelige, men som med Kjødelige, som med Børn i Christus."],[3,2,"Jeg gav Eder Mælk at drikke, og ikke haard Mad; thi da kunde I end ikke taale den, ja, I kunne endnu ikke;","Jeg gav Eder Mælk at drikke, og ikke haard Mad; thi da kunde I end ikke taale den, ja, I kunne endnu ikke;"],[3,3,"thi I ere endnu kjødelige. Efterdi der er Nid og Kiv og Tvedragt iblandt Eder, ere I da ikke kjødelige, og omgaaes efter menneskelig Viis?","thi I ere endnu kjødelige. Efterdi der er Nid og Kiv og Tvedragt iblandt Eder, ere I da ikke kjødelige, og omgaaes efter menneskelig Viis?"],[3,4,"Naar En siger: jeg er Paulus’, men en anden: jeg er Apollos’, ere I da ikke kjødelige?","Naar En siger: jeg er Paulus’, men en anden: jeg er Apollos’, ere I da ikke kjødelige?"],[3,5,"Hvo er da Paulus? og hvo er Apollos? uden Tjenere, ved hvilke I bleve Troende, og det, eftersom Herren haver givet enhver.","Hvo er da Paulus? og hvo er Apollos? uden Tjenere, ved hvilke I bleve Troende, og det, eftersom Herren haver givet enhver."],[3,6,"Jeg plantede, Apollos vandede, men Gud gav Væxt.","Jeg plantede, Apollos vandede, men Gud gav Væxt."],[3,7,"Saa er nu hverken den Noget, som planter, ikke heller den, som vander, men Gud, som giver Væxt.","Saa er nu hverken den Noget, som planter, ikke heller den, som vander, men Gud, som giver Væxt."],[3,8,"Den, som planter, og den, som vander, ere eet; men hver skal faae sin egen Løn efter sit eget Arbeide.","Den, som planter, og den, som vander, ere eet; men hver skal faae sin egen Løn efter sit eget Arbeide."],[3,9,"Thi vi ere Guds Medarbeidere; I ere Guds Ager, Guds Bygning.","Thi vi ere Guds Medarbeidere; I ere Guds Ager, Guds Bygning."],[3,10,"Jeg lagde Grundvolden som en viis Bygmester, efter den Guds Naade, som mig er given, men en Anden bygger derpaa; hver see til, hvorledes han bygger.","Jeg lagde Grundvolden som en viis Bygmester, efter den Guds Naade, som mig er given, men en Anden bygger derpaa; hver see til, hvorledes han bygger."],[3,11,"Thi ingen kan lægge anden Grundvold end den, som lagt er, hvilken er Jesus Christus;","Thi ingen kan lægge anden Grundvold end den, som lagt er, hvilken er Jesus Christus;"],[3,12,"men dersom Nogen bygger paa denne Grundvold Guld, Sølv, dyrebare Stene, Træ, Hø, Straa,","men dersom Nogen bygger paa denne Grundvold Guld, Sølv, dyrebare Stene, Træ, Hø, Straa,"],[3,13,"da skal hvers Gjerning blive aabenbar; thi Dagen skal gjøre det klart, ved Ild skal det aabenbares, og Ilden skal prøve, hvordan hvers Gjerning er.","da skal hvers Gjerning blive aabenbar; thi Dagen skal gjøre det klart, ved Ild skal det aabenbares, og Ilden skal prøve, hvordan hvers Gjerning er."],[3,14,"Dersom Nogens Gjerning, som han byggede derpaa, bliver fast, da skal han faae Løn;","Dersom Nogens Gjerning, som han byggede derpaa, bliver fast, da skal han faae Løn;"],[3,15,"dersom Nogens Gjerning bliver opbrændt, da skal han lide Skade; men han selv skal blive frelst, dog som igjennem Ild.","dersom Nogens Gjerning bliver opbrændt, da skal han lide Skade; men han selv skal blive frelst, dog som igjennem Ild."],[3,16,"Vide I ikke, at I ere Guds Tempel, og Guds Aand boer i Eder?","Vide I ikke, at I ere Guds Tempel, og Guds Aand boer i Eder?"],[3,17,"Dersom Nogen fordærver Guds Tempel, ham skal Gud fordærve; thi Guds Tempel er helligt, hvilket I ere.","Dersom Nogen fordærver Guds Tempel, ham skal Gud fordærve; thi Guds Tempel er helligt, hvilket I ere."],[3,18,"Ingen bedrage sig selv! dersom Nogen lader sig tykkes at være viis iblandt Eder i denne Verden, han vorde en Daare, at han kan vorde viis.","Ingen bedrage sig selv! dersom Nogen lader sig tykkes at være viis iblandt Eder i denne Verden, han vorde en Daare, at han kan vorde viis."],[3,19,"Thi denne Verdens Viisdom er Daarlighed hos Gud, som skrevet staar: han er den, som griber de Vise i deres Trædskhed;","Thi denne Verdens Viisdom er Daarlighed hos Gud, som skrevet staar: han er den, som griber de Vise i deres Trædskhed;"],[3,20,"og atter: Herren kjende de Vises Tanker, at de ere forfængelige.","og atter: Herren kjende de Vises Tanker, at de ere forfængelige."],[3,21,"Derfor rose Ingen sig af Mennesker, thi alle Ting ere Eders;","Derfor rose Ingen sig af Mennesker, thi alle Ting ere Eders;"],[3,22,"være sig Paulus, eller Apollos, eller Kephas, eller Verden, eller Liv, eller Død, eller det Nærværende, eller det Tilkommende: alle Ting ere Eders;","være sig Paulus, eller Apollos, eller Kephas, eller Verden, eller Liv, eller Død, eller det Nærværende, eller det Tilkommende: alle Ting ere Eders;"],[3,23,"men I ere Christi, men Christus Guds.","men I ere Christi, men Christus Guds."],[4,1,"Saaledes agte hvert Menneske os, som Christi Tjenere og Huusholdere over Guds Hemmeligheder.","Saaledes agte hvert Menneske os, som Christi Tjenere og Huusholdere over Guds Hemmeligheder."],[4,2,"Iøvrigt udkræves af Huusholdere, at de maae findes troe.","Iøvrigt udkræves af Huusholdere, at de maae findes troe."],[4,3,"Men mig er det saare lidet, at dømmes af Eder eller af en menneskelig Ret; ja, jeg dømmer mig end ikke selv.","Men mig er det saare lidet, at dømmes af Eder eller af en menneskelig Ret; ja, jeg dømmer mig end ikke selv."],[4,4,"Vel veed jeg Intet med mig selv, dog er jeg dermed ikke retfærdiggjort; men Herren er den, som mig dømmer.","Vel veed jeg Intet med mig selv, dog er jeg dermed ikke retfærdiggjort; men Herren er den, som mig dømmer."],[4,5,"Derfor dømmer ikke Noget for Tiden, indtil Herren kommer, som og skal føre til Lyset det, som er skjult i Mørket, og aabenbare Hjerternes Raad; da skal hver vederfares sin Lov af Gud.","Derfor dømmer ikke Noget for Tiden, indtil Herren kommer, som og skal føre til Lyset det, som er skjult i Mørket, og aabenbare Hjerternes Raad; da skal hver vederfares sin Lov af Gud."],[4,6,"Men dette, Brødre! haver jeg hentydet paa mig selv og Apollos for Eders Skyld, at I kunne lære af os, ikke at tænke høiere, end skrevet er, at ikke Nogen for Eens Skyld skal opblæse sig mod den Anden.","Men dette, Brødre! haver jeg hentydet paa mig selv og Apollos for Eders Skyld, at I kunne lære af os, ikke at tænke høiere, end skrevet er, at ikke Nogen for Eens Skyld skal opblæse sig mod den Anden."],[4,7,"Thi hvo giver dig Fortrin? og hvad haver du, som du ikke haver annammet? men dersom du og haver annammet det, hvi roser du dig, som du havde ikke annammet det?","Thi hvo giver dig Fortrin? og hvad haver du, som du ikke haver annammet? men dersom du og haver annammet det, hvi roser du dig, som du havde ikke annammet det?"],[4,8,"I ere allerede blevne mætte, I ere allerede blevne rige, I ere blevne Herrer foruden os, og gid I bare blevne Herrer, paa det og vi kunde blive det med Eder!","I ere allerede blevne mætte, I ere allerede blevne rige, I ere blevne Herrer foruden os, og gid I bare blevne Herrer, paa det og vi kunde blive det med Eder!"],[4,9,"Thi mig synes, at Gud haver fremstillet os Apostler som de Ringeste, som henantvordede til Døden; thi vi ere blevne et Skuespil for Verden, baade for Engle og Mennesker.","Thi mig synes, at Gud haver fremstillet os Apostler som de Ringeste, som henantvordede til Døden; thi vi ere blevne et Skuespil for Verden, baade for Engle og Mennesker."],[4,10,"Vi ere Daarer for Christi Skyld, men I ere kloge i Christus; vi skrøbelige, men I stærke; I herlige, men vi foragtede.","Vi ere Daarer for Christi Skyld, men I ere kloge i Christus; vi skrøbelige, men I stærke; I herlige, men vi foragtede."],[4,11,"Indtil denne Time lide vi baade Hunger og Tørst og ere nøgne og faae Mundslag og have intet vist Sted,","Indtil denne Time lide vi baade Hunger og Tørst og ere nøgne og faae Mundslag og have intet vist Sted,"],[4,12,"og arbeide møisommeligen med vore egne Hænder. Overskjeldede velsigne vi, forfulgte taale vi,","og arbeide møisommeligen med vore egne Hænder. Overskjeldede velsigne vi, forfulgte taale vi,"],[4,13,"bespottede formane vi, vi ere blevne som Udskud i Verden, Alles Skovisk indtil nu.","bespottede formane vi, vi ere blevne som Udskud i Verden, Alles Skovisk indtil nu."],[4,14,"Dette skriver jeg ikke for at beskæmme Eder; men jeg paaminder Eder som mine elskelige Børn.","Dette skriver jeg ikke for at beskæmme Eder; men jeg paaminder Eder som mine elskelige Børn."],[4,15,"Thi om I end havde ti tusinde Tugtemestere i Christus, have I dog ikke mange Fædre; men jeg avlede Eder i Christus Jesus ved Evangelium,","Thi om I end havde ti tusinde Tugtemestere i Christus, have I dog ikke mange Fædre; men jeg avlede Eder i Christus Jesus ved Evangelium,"],[4,16,"Jeg formaner Eder derfor, vorder mine Efterfølgere!","Jeg formaner Eder derfor, vorder mine Efterfølgere!"],[4,17,"Desaarsag sendte jeg Timotheus til Eder, som er min elskelige og trofaste Søn i Herren, at han skal paaminde Eder om mine Veie i Christus, saaledes som jeg lærer allevegne i hver Menighed.","Desaarsag sendte jeg Timotheus til Eder, som er min elskelige og trofaste Søn i Herren, at han skal paaminde Eder om mine Veie i Christus, saaledes som jeg lærer allevegne i hver Menighed."],[4,18,"Nogle ere blevne opblæste, som om jeg ikke skulde komme til Eder;","Nogle ere blevne opblæste, som om jeg ikke skulde komme til Eder;"],[4,19,"men jeg vil snart komme til Eder, om Herren vil, og forfare, ikke de Opblæstes Ord, men deres Kraft.","men jeg vil snart komme til Eder, om Herren vil, og forfare, ikke de Opblæstes Ord, men deres Kraft."],[4,20,"Thi Guds Rige bestaaer ikke i Ord, men i Kraft.","Thi Guds Rige bestaaer ikke i Ord, men i Kraft."],[4,21,"Hvad ville I? skal jeg komme til Eder med Riis, eller med Kjærlighed og Sagtmodigheds Aand?","Hvad ville I? skal jeg komme til Eder med Riis, eller med Kjærlighed og Sagtmodigheds Aand?"],[5,1,"Ydermere høres der Horeri iblandt Eder, og saadant Horeri, som ikke end nævnes iblandt Hedningerne, at En lever med sin Faders Hustru.","Ydermere høres der Horeri iblandt Eder, og saadant Horeri, som ikke end nævnes iblandt Hedningerne, at En lever med sin Faders Hustru."],[5,2,"Og I ere opblæste, og ere ikke meget mere sørgmodige, saa at den, som haver gjort denne Gjerning, maatte udstødes fra Eder?","Og I ere opblæste, og ere ikke meget mere sørgmodige, saa at den, som haver gjort denne Gjerning, maatte udstødes fra Eder?"],[5,3,"Jeg for min Deel, skjøndt fraværende med Legemet, men nærværende med Aanden haver allerede dømt, som om jeg var nærværende, den, som dette haver saaledes bedrevet,","Jeg for min Deel, skjøndt fraværende med Legemet, men nærværende med Aanden haver allerede dømt, som om jeg var nærværende, den, som dette haver saaledes bedrevet,"],[5,4,"i vor Herres Jesu Christi Navn, naar I ere forsamlede, og min Aand hos Eder, med vor Herres Jesu Christus Kraft,","i vor Herres Jesu Christi Navn, naar I ere forsamlede, og min Aand hos Eder, med vor Herres Jesu Christus Kraft,"],[5,5,"at overantvorde Satan en Saadan til Kjødets Fordærvelse, at Aanden maa frelses paa den Herres Jesu Christi Dag.","at overantvorde Satan en Saadan til Kjødets Fordærvelse, at Aanden maa frelses paa den Herres Jesu Christi Dag."],[5,6,"Kun slet er Eders Roes! Vide I ikke, at en liden Suurdeig syrer den hele Deig?","Kun slet er Eders Roes! Vide I ikke, at en liden Suurdeig syrer den hele Deig?"],[5,7,"Derfor udrenser den gamle Suurdeig, at I kunne være en ny Deig, ligesom I ere usyrede; thi ogsaa for os er vort Paaskelam slagtet, Christus.","Derfor udrenser den gamle Suurdeig, at I kunne være en ny Deig, ligesom I ere usyrede; thi ogsaa for os er vort Paaskelam slagtet, Christus."],[5,8,"Derfor lader os holde Høitid, ikke med den gamle Suurdeig, ei heller med Ondskabs og Skalkheds Suurdeig, men med Reenheds og Sandheds usyrede Brød.","Derfor lader os holde Høitid, ikke med den gamle Suurdeig, ei heller med Ondskabs og Skalkheds Suurdeig, men med Reenheds og Sandheds usyrede Brød."],[5,9,"Jeg haver skrevet Eder til i Brevet, at I skulle Intet have at skaffe med Skjørlevnere.","Jeg haver skrevet Eder til i Brevet, at I skulle Intet have at skaffe med Skjørlevnere."],[5,10,"Dermed mener jeg ingenlunde Skjørlevnere i denne Verden eller Gjerrige eller Røvere eller Afgudsdyrkere; ellers maatte I gaae ud af Verden.","Dermed mener jeg ingenlunde Skjørlevnere i denne Verden eller Gjerrige eller Røvere eller Afgudsdyrkere; ellers maatte I gaae ud af Verden."],[5,11,"Men nu haver jeg skrevet Eder, at I skulle Intet have at skaffe, dersom Nogen, der kaldes en Broder, er en Skjørlevner eller Gjerrig eller en Afgudsdyrker eller en Skjendegjest eller en Dranker eller en Røver, at I skulle end ikke æde med den Saadan.","Men nu haver jeg skrevet Eder, at I skulle Intet have at skaffe, dersom Nogen, der kaldes en Broder, er en Skjørlevner eller Gjerrig eller en Afgudsdyrker eller en Skjendegjest eller en Dranker eller en Røver, at I skulle end ikke æde med den Saadan."],[5,12,"Thi hvad kommer det mig ved ogsaa at dømme dem, som ere udenfor? Nei, dømmer I dem, som ere iblandt Eder:","Thi hvad kommer det mig ved ogsaa at dømme dem, som ere udenfor? Nei, dømmer I dem, som ere iblandt Eder:"],[5,13,"dem udenfor skal Gud dømme. Bortskaffer I den Onde fra Eder!","dem udenfor skal Gud dømme. Bortskaffer I den Onde fra Eder!"],[6,1,"Kan dog Nogen af Eder, naar han haver Sag med en Anden, føre det over sit Sind at søge Dom hos de Vanhellige, og ikke hos de Hellige?","Kan dog Nogen af Eder, naar han haver Sag med en Anden, føre det over sit Sind at søge Dom hos de Vanhellige, og ikke hos de Hellige?"],[6,2,"Vide I ikke, at de Hellige skulle dømme Verden? og dersom Verden dømmes ved Eder, ere I da uværdige til at dømme i de ringeste Sager?","Vide I ikke, at de Hellige skulle dømme Verden? og dersom Verden dømmes ved Eder, ere I da uværdige til at dømme i de ringeste Sager?"],[6,3,"Vide I ikke, at vi skulle dømme Englene? end sige timelige Ting!","Vide I ikke, at vi skulle dømme Englene? end sige timelige Ting!"],[6,4,"Naar I da have Sager om det Timelige, da sætte I dem til Dommere, som ere intet agtede i Menigheden.","Naar I da have Sager om det Timelige, da sætte I dem til Dommere, som ere intet agtede i Menigheden."],[6,5,"Jeg siger det Eder til Blusel: saa er der da ingen Viis iblandt Eder, end ikke een, som kunde dømme imellem sine Brødre?","Jeg siger det Eder til Blusel: saa er der da ingen Viis iblandt Eder, end ikke een, som kunde dømme imellem sine Brødre?"],[6,6,"Men Broder gaaer i Rette med Broder, og det er for de Vantroe!","Men Broder gaaer i Rette med Broder, og det er for de Vantroe!"],[6,7,"Overalt er det jo allerede en Feil iblandt Eder, at I have Sager med hverandre. Hvi lide I ikke hellere Uret? hvi lade I Eder ikke hellere besvige?","Overalt er det jo allerede en Feil iblandt Eder, at I have Sager med hverandre. Hvi lide I ikke hellere Uret? hvi lade I Eder ikke hellere besvige?"],[6,8,"Men I gjøre Uret og besvige, og det Brødrene!","Men I gjøre Uret og besvige, og det Brødrene!"],[6,9,"Eller vide I ikke, at de Uretfærdige skulle ikke arve Guds Rige? Farer ikke vild! Hverken Skjørlevnere, ei heller Afgudsdyrkere, ei heller Hoerkarle, ei heller Blødagtige, ei heller de, som synde imod Naturen,","Eller vide I ikke, at de Uretfærdige skulle ikke arve Guds Rige? Farer ikke vild! Hverken Skjørlevnere, ei heller Afgudsdyrkere, ei heller Hoerkarle, ei heller Blødagtige, ei heller de, som synde imod Naturen,"],[6,10,"ei heller Tyve, ei heller Gjerrige, ei heller Drankere, ei Skjendegjeste, ei Røvere skulle arve Guds Rige.","ei heller Tyve, ei heller Gjerrige, ei heller Drankere, ei Skjendegjeste, ei Røvere skulle arve Guds Rige."],[6,11,"Og saadanne vare I tildeels; men I ere aftvættede, men I ere helliggjorte, men I ere retfærdiggjorte, ved den Herres Jesu Navn og ved vor Guds Aand.","Og saadanne vare I tildeels; men I ere aftvættede, men I ere helliggjorte, men I ere retfærdiggjorte, ved den Herres Jesu Navn og ved vor Guds Aand."],[6,12,"Jeg haver Lov til Alt, men Alt er ikke nyttigt; jeg haver Lov til Alt, men jeg vil ikke lade mig beherske af Noget.","Jeg haver Lov til Alt, men Alt er ikke nyttigt; jeg haver Lov til Alt, men jeg vil ikke lade mig beherske af Noget."],[6,13,"Maden er for Bugen, og Bugen for Maden; men Gud skal tilintetgjøre baade denne og den; Legemet derimod er ikke for Skjørlevnet, men for Herren, og Herren for Legemet;","Maden er for Bugen, og Bugen for Maden; men Gud skal tilintetgjøre baade denne og den; Legemet derimod er ikke for Skjørlevnet, men for Herren, og Herren for Legemet;"],[6,14,"og Gud haver baade opreist Herren, og skal opreise os formedelst sin Kraft.","og Gud haver baade opreist Herren, og skal opreise os formedelst sin Kraft."],[6,15,"Vide I ikke, at Eders Legemer ere Christi Lemmer og gjøre dem til Skjøgens Lemmer? Det være langt fra!","Vide I ikke, at Eders Legemer ere Christi Lemmer og gjøre dem til Skjøgens Lemmer? Det være langt fra!"],[6,16,"Eller vide I ikke, at hvo som hænger ved Skjøgen, er eet Legeme med hende? Thi de To, hedder det, skulle blive til eet Kjød.","Eller vide I ikke, at hvo som hænger ved Skjøgen, er eet Legeme med hende? Thi de To, hedder det, skulle blive til eet Kjød."],[6,17,"Men hvo som hænger ved Herren, er een Aand med ham.","Men hvo som hænger ved Herren, er een Aand med ham."],[6,18,"Flyer Skjørlevnet! Enhver Synd som Mennesket gjør, er udenfor Legemet; men hvo som bedriver Skjørlevnet, synder imod sit eget Legeme.","Flyer Skjørlevnet! Enhver Synd som Mennesket gjør, er udenfor Legemet; men hvo som bedriver Skjørlevnet, synder imod sit eget Legeme."],[6,19,"Eller vide I ikke, at Eders Legeme er den Hellig Aands Tempel, som er i Eder, hvilken I have af Gud, og at I ikke ere Eders Egne?","Eller vide I ikke, at Eders Legeme er den Hellig Aands Tempel, som er i Eder, hvilken I have af Gud, og at I ikke ere Eders Egne?"],[6,20,"Thi I ere dyrekjøbte; ærer derfor Gud i Eders Legeme og i Eders Aand, hvilke høre Gud til.","Thi I ere dyrekjøbte; ærer derfor Gud i Eders Legeme og i Eders Aand, hvilke høre Gud til."],[7,1,"Betræffende det, som I skreve mig til om, da er det et Menneske godt, at han ikke rører en Kvinde;","Betræffende det, som I skreve mig til om, da er det et Menneske godt, at han ikke rører en Kvinde;"],[7,2,"men for Skjørlevnets Skyld have hver Mand sin egen Hustru, og hver Hustru have sin egen Mand.","men for Skjørlevnets Skyld have hver Mand sin egen Hustru, og hver Hustru have sin egen Mand."],[7,3,"Manden bevise Hustruen den skyldige Velvillighed; desligeste ogsaa Hustruen Manden.","Manden bevise Hustruen den skyldige Velvillighed; desligeste ogsaa Hustruen Manden."],[7,4,"Hustruen er ikke mægtig over sit eget Legeme, men Manden; desligeste er ogsaa Manden ikke mægtig over sit eget Legeme, men Hustruen.","Hustruen er ikke mægtig over sit eget Legeme, men Manden; desligeste er ogsaa Manden ikke mægtig over sit eget Legeme, men Hustruen."],[7,5,"Holder Eder ikke fra hverandre, uden det skeer med fælles Samtykke, til en Tid, at I kunne overlade Eder til Faste og Bøn; og kommer atter tilsammen, at Satan ikke skal friste Eder formedelst Eders Uafholdenhed.","Holder Eder ikke fra hverandre, uden det skeer med fælles Samtykke, til en Tid, at I kunne overlade Eder til Faste og Bøn; og kommer atter tilsammen, at Satan ikke skal friste Eder formedelst Eders Uafholdenhed."],[7,6,"Men dette siger jeg som Raad, ikke som Befaling.","Men dette siger jeg som Raad, ikke som Befaling."],[7,7,"Thi jeg vilde, at alle Mennesker vare, som jeg selv er; men hver haver sin egen Naadegave af Gud, den Ene saa, den anden saa.","Thi jeg vilde, at alle Mennesker vare, som jeg selv er; men hver haver sin egen Naadegave af Gud, den Ene saa, den anden saa."],[7,8,"Thi de Ugifte og til Enker siger jeg, at det er dem godt, om de blive, som jeg er.","Thi de Ugifte og til Enker siger jeg, at det er dem godt, om de blive, som jeg er."],[7,9,"Men kunne de ikke afholde sig, da gifte de sig; thi det er bedre at gifte sig, end at lide Brynde.","Men kunne de ikke afholde sig, da gifte de sig; thi det er bedre at gifte sig, end at lide Brynde."],[7,10,"Men de Gifte byder ikke jeg, men Herren, at Hustruen ikke skal skilles fra Manden;","Men de Gifte byder ikke jeg, men Herren, at Hustruen ikke skal skilles fra Manden;"],[7,11,"(men skilles hun og fra ham, da blive hun ugift, eller forlige sig med Manden); og at en Mand ikke skal forlade sin Hustru.","(men skilles hun og fra ham, da blive hun ugift, eller forlige sig med Manden); og at en Mand ikke skal forlade sin Hustru."],[7,12,"Men de Andre siger jeg, ikke Herren: dersom nogen Broder haver en vantro Hustru, og det behager hende, at boe hos ham, han forlade hende ikke.","Men de Andre siger jeg, ikke Herren: dersom nogen Broder haver en vantro Hustru, og det behager hende, at boe hos ham, han forlade hende ikke."],[7,13,"Og dersom en Kvinde haver en vantro Mand, og det behager ham at boe hos hende, hun forlade ham ikke.","Og dersom en Kvinde haver en vantro Mand, og det behager ham at boe hos hende, hun forlade ham ikke."],[7,14,"Thi den vantroe Mand er helliget formedelst Hustruen, og den vantroe Hustru er helliget formedelst Manden; thi ellers vare jo Eders Børn urene, men nu ere de hellige.","Thi den vantroe Mand er helliget formedelst Hustruen, og den vantroe Hustru er helliget formedelst Manden; thi ellers vare jo Eders Børn urene, men nu ere de hellige."],[7,15,"Men vil den Vantroe fraskille sig, da fraskille han sig; ingen Broder eller Søster er bunden i saadanne Ting; men Gud haver kaldet os til Fred.","Men vil den Vantroe fraskille sig, da fraskille han sig; ingen Broder eller Søster er bunden i saadanne Ting; men Gud haver kaldet os til Fred."],[7,16,"Thi hvad veed du, Hustru! om du ikke kan frelse Manden? eller hvad veed du, Mand! om du ikke kan frelse Hustruen?","Thi hvad veed du, Hustru! om du ikke kan frelse Manden? eller hvad veed du, Mand! om du ikke kan frelse Hustruen?"],[7,17,"Som Gud haver tildeelt enhver, som Herren haver kaldet enhver, saaledes vandre han; og saaledes beskikker jeg i alle Menigheder.","Som Gud haver tildeelt enhver, som Herren haver kaldet enhver, saaledes vandre han; og saaledes beskikker jeg i alle Menigheder."],[7,18,"Er Nogen kaldet omskaaren, han lade ikke Forhuden drage over; er Nogen kaldet i Forhuden, han lade sig ikke omskære.","Er Nogen kaldet omskaaren, han lade ikke Forhuden drage over; er Nogen kaldet i Forhuden, han lade sig ikke omskære."],[7,19,"Omskærelsen er Intet, og Forhuden er Intet, men at bevare Guds Bud.","Omskærelsen er Intet, og Forhuden er Intet, men at bevare Guds Bud."],[7,20,"Hver blive i den Stand, som han er kaldet udi.","Hver blive i den Stand, som han er kaldet udi."],[7,21,"Er du kaldet som Træl, det bekymre dig ikke; men kan du blive Fri, da vælg hellere dette.","Er du kaldet som Træl, det bekymre dig ikke; men kan du blive Fri, da vælg hellere dette."],[7,22,"Thi hvo som er kaldet i Herren som Træl, han er Herrens Frigivne; desligeste og hvo som er kaldet som Fri, han er Christi Træl.","Thi hvo som er kaldet i Herren som Træl, han er Herrens Frigivne; desligeste og hvo som er kaldet som Fri, han er Christi Træl."],[7,23,"I ere dyrekjøbte, vorder ikke Menneskers Trælle!","I ere dyrekjøbte, vorder ikke Menneskers Trælle!"],[7,24,"Som enhver, Brødre! er kaldet, saaledes blive han for Gud.","Som enhver, Brødre! er kaldet, saaledes blive han for Gud."],[7,25,"Om Jomfruer haver jeg ikke Herrens Befaling, men giver min Mening tilkjende, som den, hvem Herren barmhjertig har forundt at være tro.","Om Jomfruer haver jeg ikke Herrens Befaling, men giver min Mening tilkjende, som den, hvem Herren barmhjertig har forundt at være tro."],[7,26,"Jeg mener altsaa, at dette er godt formedelst den nærværende Nød, at det er godt for et Menneske at være saaledes.","Jeg mener altsaa, at dette er godt formedelst den nærværende Nød, at det er godt for et Menneske at være saaledes."],[7,27,"Er du bunden til en Hustru? søg ikke at blive løst; er du løst fra en Hustru? søg ikke en Hustru.","Er du bunden til en Hustru? søg ikke at blive løst; er du løst fra en Hustru? søg ikke en Hustru."],[7,28,"Men dersom du og giftede dig, syndede du ikke; og dersom en Jomfru giftede sig, syndede hun ikke; dog skulle saadanne have Trængsel i Kjødet. Men jeg skaaner Eder.","Men dersom du og giftede dig, syndede du ikke; og dersom en Jomfru giftede sig, syndede hun ikke; dog skulle saadanne have Trængsel i Kjødet. Men jeg skaaner Eder."],[7,29,"Saa meget siger jeg, Brødre! at Tiden herefter er trang, saa at baade de, der have Hustruer, skulle være som de, der ikke have,","Saa meget siger jeg, Brødre! at Tiden herefter er trang, saa at baade de, der have Hustruer, skulle være som de, der ikke have,"],[7,30,"og de, der græde, som de, der ikke græde, og de, sig glæde, som de, der ikke glæde sig, og de der kjøbe, som de, der ikke beholde,","og de, der græde, som de, der ikke græde, og de, sig glæde, som de, der ikke glæde sig, og de der kjøbe, som de, der ikke beholde,"],[7,31,"og de, der bruge denne Verden, som de, der ikke nyde den; thi denne Verdens Skikkelse forgaaer.","og de, der bruge denne Verden, som de, der ikke nyde den; thi denne Verdens Skikkelse forgaaer."],[7,32,"Men jeg vilde, at I skulde være uden Bekymring. Den Ugifte haver Omhyggelighed for de Ting, som høre Herren til, hvorledes han kan behage Herren;","Men jeg vilde, at I skulde være uden Bekymring. Den Ugifte haver Omhyggelighed for de Ting, som høre Herren til, hvorledes han kan behage Herren;"],[7,33,"men den Gifte haver Omhyggelighed for de Ting, som høre Verden til, hvorledes han kan behage Hustruen.","men den Gifte haver Omhyggelighed for de Ting, som høre Verden til, hvorledes han kan behage Hustruen."],[7,34,"Der er ogsaa Forskjel imellem Hustruen og Jomfruen. Den Ugifte haver Omhyggelighed for de Ting, som høre Herren til, at hun kan være hellig baade paa Legeme og i Aand; men den Gifte haver Omhyggelighed for det, som hører Verden til, hvorledes hun kan behage Manden.","Der er ogsaa Forskjel imellem Hustruen og Jomfruen. Den Ugifte haver Omhyggelighed for de Ting, som høre Herren til, at hun kan være hellig baade paa Legeme og i Aand; men den Gifte haver Omhyggelighed for det, som hører Verden til, hvorledes hun kan behage Manden."],[7,35,"Det siger jeg til Eders egen Nytte ikke for at kaste en Snare om Eder, men for at bevare Anstændighed og urokkelig Vedholdenhed ved Herren.","Det siger jeg til Eders egen Nytte ikke for at kaste en Snare om Eder, men for at bevare Anstændighed og urokkelig Vedholdenhed ved Herren."],[7,36,"Men dersom Nogen mener, at det er uanstændigt for hans Jomfru, dersom hun sidder for længe hen, og det maa saa være, han gjøre, hvad han vil, han synder ikke; lader Saadanne gifte sig.","Men dersom Nogen mener, at det er uanstændigt for hans Jomfru, dersom hun sidder for længe hen, og det maa saa være, han gjøre, hvad han vil, han synder ikke; lader Saadanne gifte sig."],[7,37,"Men den, som haver sat sig stadig for i Hjertet, som er ikke tvungen, men haver Magt over sin egen Villie, og haver besluttet det i sit Hjerte, at bevare sin Jomfru, han gjør vel.","Men den, som haver sat sig stadig for i Hjertet, som er ikke tvungen, men haver Magt over sin egen Villie, og haver besluttet det i sit Hjerte, at bevare sin Jomfru, han gjør vel."],[7,38,"Saa at baade den, som bortgifter, gjør vel, og den, som ikke bortgifter, gjør bedre.","Saa at baade den, som bortgifter, gjør vel, og den, som ikke bortgifter, gjør bedre."],[7,39,"En Hustru er bunden ved Loven, saa længe hendes Mand lever; men er hendes Mand hensovet, er hun fri, at giftes med hvem hun vil, alene at det skeer i Herren.","En Hustru er bunden ved Loven, saa længe hendes Mand lever; men er hendes Mand hensovet, er hun fri, at giftes med hvem hun vil, alene at det skeer i Herren."],[7,40,"Men hun er lyksaligere, om hun bliver saaledes, som hun er, efter min Mening; men jeg mener og at have Guds Aand.","Men hun er lyksaligere, om hun bliver saaledes, som hun er, efter min Mening; men jeg mener og at have Guds Aand."],[8,1,"Hvad Afguds-Offer angaaer, da vide vi, thi vi have alle Kundskab; (Kundskaben opblæser, men Kjærligheden opbygger.","Hvad Afguds-Offer angaaer, da vide vi, thi vi have alle Kundskab; (Kundskaben opblæser, men Kjærligheden opbygger."],[8,2,"Dersom Nogen tykkes at vide Noget, han haver endnu aldrig vidst Noget saaledes, som det bør sig at vide.","Dersom Nogen tykkes at vide Noget, han haver endnu aldrig vidst Noget saaledes, som det bør sig at vide."],[8,3,"Men dersom Nogen elsker Gud, han haver faaet Kundskab af ham).","Men dersom Nogen elsker Gud, han haver faaet Kundskab af ham)."],[8,4,"Hvad altsaa Spiisning af Afguds-Offer angaaer, da vide vi, at en Afgud er intet i Verden, og at der er ingen anden Gud, uden een.","Hvad altsaa Spiisning af Afguds-Offer angaaer, da vide vi, at en Afgud er intet i Verden, og at der er ingen anden Gud, uden een."],[8,5,"Thi omendskjøndt der er saakaldte Guder, være sig i Himmelen eller paa Jorden, (som det da hedder: der ere mange Guder og mange Herrer),","Thi omendskjøndt der er saakaldte Guder, være sig i Himmelen eller paa Jorden, (som det da hedder: der ere mange Guder og mange Herrer),"],[8,6,"saa have vi dog kun een Gud, Faderen, at hvem alle Ting ere, og vi i ham, og een Herre, Jesus Christus, ved hvem alle Ting ere, og vi ved ham.","saa have vi dog kun een Gud, Faderen, at hvem alle Ting ere, og vi i ham, og een Herre, Jesus Christus, ved hvem alle Ting ere, og vi ved ham."],[8,7,"Men Alle have ikke den Kundskab. Nogle gjøre sig endnu Samvittighed over Afguder, og æde det som Afguds-Offer, og deres Samvittighed, som er skrøbelig, besmittes.","Men Alle have ikke den Kundskab. Nogle gjøre sig endnu Samvittighed over Afguder, og æde det som Afguds-Offer, og deres Samvittighed, som er skrøbelig, besmittes."],[8,8,"Men Mad gjør os ikke behagelige for Gud; thi hverken blive vi bedre, om vi æde, eller ringere, om vi ikke æde.","Men Mad gjør os ikke behagelige for Gud; thi hverken blive vi bedre, om vi æde, eller ringere, om vi ikke æde."],[8,9,"Men seer til, at denne Eders Frihed ikke bliver de Skrøbelige til noget Anstød.","Men seer til, at denne Eders Frihed ikke bliver de Skrøbelige til noget Anstød."],[8,10,"Thi dersom Nogen seer dig, som haver Kundskab, sidde tilbords i Afgudens Huus, bestyrkes da ikke hans Samvittighed, som er skrøbelig, derved til at æde Afguds-Offer?","Thi dersom Nogen seer dig, som haver Kundskab, sidde tilbords i Afgudens Huus, bestyrkes da ikke hans Samvittighed, som er skrøbelig, derved til at æde Afguds-Offer?"],[8,11,"Og saaledes vil, formedelst din Kundskab den skrøbelige Broder fortabes, for hvem Christus er død.","Og saaledes vil, formedelst din Kundskab den skrøbelige Broder fortabes, for hvem Christus er død."],[8,12,"Men naar I saaledes synde mod Brødrene, og saare deres skrøbelige Samvittighed, synde I mod Christus.","Men naar I saaledes synde mod Brødrene, og saare deres skrøbelige Samvittighed, synde I mod Christus."],[8,13,"Derfor, om mad forarger min Broder, vil jeg aldrig æde Kjød, at jeg ikke skal forarge min Broder.","Derfor, om mad forarger min Broder, vil jeg aldrig æde Kjød, at jeg ikke skal forarge min Broder."],[9,1,"Er jeg ikke en Apostel? er jeg ikke fri? haver jeg ikke seet vor Herre Jesus Christus? ere I ikke min Gjerning i Herren?","Er jeg ikke en Apostel? er jeg ikke fri? haver jeg ikke seet vor Herre Jesus Christus? ere I ikke min Gjerning i Herren?"],[9,2,"Er jeg end ikke Andre en Apostel, Eder er jeg det dog; thi I ere mit Apostel-Embedes Besegling i Herren.","Er jeg end ikke Andre en Apostel, Eder er jeg det dog; thi I ere mit Apostel-Embedes Besegling i Herren."],[9,3,"Dette er mit Forsvar mod den, som mig bedømme.","Dette er mit Forsvar mod den, som mig bedømme."],[9,4,"Have vi ikke Ret at æde og drikke?","Have vi ikke Ret at æde og drikke?"],[9,5,"Have vi ikke Ret at føre en Søster som Hustru omkring, som og de andre Apostler og Herrens Brødre og Kephas?","Have vi ikke Ret at føre en Søster som Hustru omkring, som og de andre Apostler og Herrens Brødre og Kephas?"],[9,6,"Eller have alene jeg og Barnabas ikke Ret til ikke at arbeide?","Eller have alene jeg og Barnabas ikke Ret til ikke at arbeide?"],[9,7,"Hvo tjener vel i Krig paa sin egen Sold? hvo planter en Viingaard, og æder ikke af dens Frugt? eller hvo føder en Hjord, og æder ikke af Hjordens Mælk?","Hvo tjener vel i Krig paa sin egen Sold? hvo planter en Viingaard, og æder ikke af dens Frugt? eller hvo føder en Hjord, og æder ikke af Hjordens Mælk?"],[9,8,"Mon jeg tale dette blot efter menneskelig Viis? eller siger ikke ogsaa Loven dette?","Mon jeg tale dette blot efter menneskelig Viis? eller siger ikke ogsaa Loven dette?"],[9,9,"Thi der er skrevet i Mose Lov: du skal ikke tilbinde Munden paa den Oxe, som tærsker. Er det Øxnene, Gud sørger for?","Thi der er skrevet i Mose Lov: du skal ikke tilbinde Munden paa den Oxe, som tærsker. Er det Øxnene, Gud sørger for?"],[9,10,"Sikkert siger han det for vor Skyld. Thi for vor Skyld er der skrevet, at den, som pløier, bør pløie i Haab, og den, som tærsker, bør tærske for at blive deelagtig i sit Haab.","Sikkert siger han det for vor Skyld. Thi for vor Skyld er der skrevet, at den, som pløier, bør pløie i Haab, og den, som tærsker, bør tærske for at blive deelagtig i sit Haab."],[9,11,"Dersom vi have saaet Eder de aandelige Ting, er det da nogen stort, om vi høste Eders timelige?","Dersom vi have saaet Eder de aandelige Ting, er det da nogen stort, om vi høste Eders timelige?"],[9,12,"Dersom Andre nyde saadan Ret over Eder, kunde vi da ikke meget mere? Dog brugte vi ikke denne Ret; men vi taale Alt, for ikke at gjøre Christi Evangelium nogen Forhindring.","Dersom Andre nyde saadan Ret over Eder, kunde vi da ikke meget mere? Dog brugte vi ikke denne Ret; men vi taale Alt, for ikke at gjøre Christi Evangelium nogen Forhindring."],[9,13,"Vide I ikke, at de, som tjene ved Helligdommen, æde af det Hellige? de, som vare paa Alteret, dele med Alteret?","Vide I ikke, at de, som tjene ved Helligdommen, æde af det Hellige? de, som vare paa Alteret, dele med Alteret?"],[9,14,"Saaledes haver og Herren forordnet for dem, som forkynde Evangelium, at de skulle leve af Evangelium.","Saaledes haver og Herren forordnet for dem, som forkynde Evangelium, at de skulle leve af Evangelium."],[9,15,"Men jeg haver Intet brugt af dette; ei heller haver jeg skrevet dette, for at det saaledes skulde skee med mig; thi det var mig bedre at døe, end at Nogen skulde gjøre min Roes til Intet.","Men jeg haver Intet brugt af dette; ei heller haver jeg skrevet dette, for at det saaledes skulde skee med mig; thi det var mig bedre at døe, end at Nogen skulde gjøre min Roes til Intet."],[9,16,"Thi om jeg prædiker Evangelium er det mig ingen Roes; der paaligger mig en Nødvendighed, og vee mig, dersom jeg ikke prædiker!","Thi om jeg prædiker Evangelium er det mig ingen Roes; der paaligger mig en Nødvendighed, og vee mig, dersom jeg ikke prædiker!"],[9,17,"Gjør jeg det da gjerne, har jeg Løn; gjør jeg det ugjerne, er dog en Huusholdning mig betroet.","Gjør jeg det da gjerne, har jeg Løn; gjør jeg det ugjerne, er dog en Huusholdning mig betroet."],[9,18,"Hvad er da min Løn? At jeg, idet jeg prædiker, kan fremsætte Christi Evangelium uden Bekostning, paa det jeg ikke skal misbruge min Ret i Evangelium.","Hvad er da min Løn? At jeg, idet jeg prædiker, kan fremsætte Christi Evangelium uden Bekostning, paa det jeg ikke skal misbruge min Ret i Evangelium."],[9,19,"Thi omendskjøndt jeg er fri fra Alle, haver jeg dog gjort mig til en Tjener for Alle, paa det jeg kunde vinde des Flere.","Thi omendskjøndt jeg er fri fra Alle, haver jeg dog gjort mig til en Tjener for Alle, paa det jeg kunde vinde des Flere."],[9,20,"Og jeg er bleven Jøderne som en Jøde, at jeg kunde vinde Jøder; dem under Loven som den, der var under Loven, at jeg kunde vinde dem, som ere under Loven;","Og jeg er bleven Jøderne som en Jøde, at jeg kunde vinde Jøder; dem under Loven som den, der var under Loven, at jeg kunde vinde dem, som ere under Loven;"],[9,21,"dem uden Loven som den, der var uden Loven, (enddog jeg er ikke uden Loven for Gud, men under Loven for Christus), at jeg kunde vinde dem, som ere uden Loven.","dem uden Loven som den, der var uden Loven, (enddog jeg er ikke uden Loven for Gud, men under Loven for Christus), at jeg kunde vinde dem, som ere uden Loven."],[9,22,"Jeg er bleven de Skrøbelige som en Skrøbelig, at jeg kunde vinde de Skrøbelige; jeg er bleven Alt for Alle, at jeg dog for Alting kunde frelse Nogle.","Jeg er bleven de Skrøbelige som en Skrøbelig, at jeg kunde vinde de Skrøbelige; jeg er bleven Alt for Alle, at jeg dog for Alting kunde frelse Nogle."],[9,23,"Men dette gjør jeg for Evangeliums Skyld, at jeg kan blive meddeelagtig derudi.","Men dette gjør jeg for Evangeliums Skyld, at jeg kan blive meddeelagtig derudi."],[9,24,"Vide I ikke, at de, som løbe paa Banen, løbe vel alle, men ikkun Een faar Klenodiet? Løber saaledes, at I kunne erholde det.","Vide I ikke, at de, som løbe paa Banen, løbe vel alle, men ikkun Een faar Klenodiet? Løber saaledes, at I kunne erholde det."],[9,25,"Hver den, som kæmper, er afholdende i Alt; hine vel, for at annamme en forkrænkelig Krone, men vi en uforkrænkelig.","Hver den, som kæmper, er afholdende i Alt; hine vel, for at annamme en forkrænkelig Krone, men vi en uforkrænkelig."],[9,26,"Derfor løber jeg ikke som paa det Uvisse; jeg fægter som den, der ikke slaaer i Veiret.","Derfor løber jeg ikke som paa det Uvisse; jeg fægter som den, der ikke slaaer i Veiret."],[9,27,"Men jeg spæger mit Legeme og holder det I Trældom, at ikke jeg, som prædiker for Andre, skal selv blive forskudt.","Men jeg spæger mit Legeme og holder det I Trældom, at ikke jeg, som prædiker for Andre, skal selv blive forskudt."],[10,1,"Jeg vil, I skulle mindes, Brødre! at vore Fædre vare alle under Skyen, og de gik alle igjennem Havet,\nVorder mine Efterfølgere, ligesom og jeg er Christi!","Jeg vil, I skulle mindes, Brødre! at vore Fædre vare alle under Skyen, og de gik alle igjennem Havet,\nVorder mine Efterfølgere, ligesom og jeg er Christi!"],[10,2,"og de ere alle døbte til Moses i Skyen og i Havet.","og de ere alle døbte til Moses i Skyen og i Havet."],[10,3,"Og de aade alle den samme aandelige Mad,","Og de aade alle den samme aandelige Mad,"],[10,4,"og de drak alle den samme aandelige Drik; thi de drak af den aandelige Klippe, som fulgte dem; men Klippen var Christus.","og de drak alle den samme aandelige Drik; thi de drak af den aandelige Klippe, som fulgte dem; men Klippen var Christus."],[10,5,"Men Gud havde ikke Behag i de Fleste af dem; thi de bleve nedslagne i Ørken.","Men Gud havde ikke Behag i de Fleste af dem; thi de bleve nedslagne i Ørken."],[10,6,"Men disse Ting ere blevne Forbilleder for os, at vi ikke skulle have Lyst til det Onde, som de havde Lyst dertil.","Men disse Ting ere blevne Forbilleder for os, at vi ikke skulle have Lyst til det Onde, som de havde Lyst dertil."],[10,7,"Bliver ei heller Afgudsdyrkere, som nogle af dem, ligesom skrevet er: Folket satte sig ned at æde og at drikke, og stod op at lege.","Bliver ei heller Afgudsdyrkere, som nogle af dem, ligesom skrevet er: Folket satte sig ned at æde og at drikke, og stod op at lege."],[10,8,"Lader os ei heller bedrive Hoer, som nogle af dem bedreve Hoer, og faldt paa een Dag tre og tyve tusinde.","Lader os ei heller bedrive Hoer, som nogle af dem bedreve Hoer, og faldt paa een Dag tre og tyve tusinde."],[10,9,"Lader os ei heller friste Christus, som og nogle af dem fristede ham, og bleve ødelagte af Slanger.","Lader os ei heller friste Christus, som og nogle af dem fristede ham, og bleve ødelagte af Slanger."],[10,10,"Knurrer ei heller, som og nogle af dem knurrede, og bleve ødelagte af Fordærveren.","Knurrer ei heller, som og nogle af dem knurrede, og bleve ødelagte af Fordærveren."],[10,11,"Alt dette skete dem til Exempel, men det er skrevet os til Advarsel, til hvilke de sidste Tider ere komne.","Alt dette skete dem til Exempel, men det er skrevet os til Advarsel, til hvilke de sidste Tider ere komne."],[10,12,"Derfor, hvo som tykkes at staae, see til, at han ikke falder.","Derfor, hvo som tykkes at staae, see til, at han ikke falder."],[10,13,"Eder er ingen Fristelse paakommen uden menneskelig; men Gud er trofast, som ikke skal lade Eder fristes over Eders Formue, men skal gjøre baade Fristelsen og dens Udgang saaledes, at I det kunne taale.","Eder er ingen Fristelse paakommen uden menneskelig; men Gud er trofast, som ikke skal lade Eder fristes over Eders Formue, men skal gjøre baade Fristelsen og dens Udgang saaledes, at I det kunne taale."],[10,14,"Derfor, mine Elskelige, flyer fra Afgudsdyrkelsen.","Derfor, mine Elskelige, flyer fra Afgudsdyrkelsen."],[10,15,"Jeg taler som til Forstandige; dømmer I det, jeg siger.","Jeg taler som til Forstandige; dømmer I det, jeg siger."],[10,16,"Velsignelsens Kalk, som vi velsigne, er den ikke Christi Blods Samfund? det Brød, som vi bryde, er det ikke Christi Legemes Samfund?","Velsignelsens Kalk, som vi velsigne, er den ikke Christi Blods Samfund? det Brød, som vi bryde, er det ikke Christi Legemes Samfund?"],[10,17,"Eet Brød, eet Legeme ere vi mange; thi vi ere alle deelagtige i det ene Brød.","Eet Brød, eet Legeme ere vi mange; thi vi ere alle deelagtige i det ene Brød."],[10,18,"Seer til Israel efter Kjødet; de, som æde Offrene, ere de ikke deelagtige i Alteret?","Seer til Israel efter Kjødet; de, som æde Offrene, ere de ikke deelagtige i Alteret?"],[10,19,"Hvad siger jeg da? at en Afgud er Noget? eller at Afguds-Offer er Noget?","Hvad siger jeg da? at en Afgud er Noget? eller at Afguds-Offer er Noget?"],[10,20,"Nei! men hvad Hedningerne offre, offre de Djævelene, og ikke Gud; men jeg vil ikke, at I skulle have Samfund med Djævlene.","Nei! men hvad Hedningerne offre, offre de Djævelene, og ikke Gud; men jeg vil ikke, at I skulle have Samfund med Djævlene."],[10,21,"I kunne ikke drikke Herrens Kalk og Djævlenes Kalk; I kunne ikke være deelagtige i Herrens Bord og Djævlenes Bord.","I kunne ikke drikke Herrens Kalk og Djævlenes Kalk; I kunne ikke være deelagtige i Herrens Bord og Djævlenes Bord."],[10,22,"Eller ville vi opvække Herren til Nidkjærhed? monne vi være stærkere end han?","Eller ville vi opvække Herren til Nidkjærhed? monne vi være stærkere end han?"],[10,23,"Alt er mig tilladt, men ikke Alt er nyttigt; Alt er mig tilladt, men ikke Alt opbygger.","Alt er mig tilladt, men ikke Alt er nyttigt; Alt er mig tilladt, men ikke Alt opbygger."],[10,24,"Ingen see paa sit Eget, men enhver paa Næstens.","Ingen see paa sit Eget, men enhver paa Næstens."],[10,25,"Alt hvad som sælges i Slagterbod, det æder, uden at spørge for Samvittighedens Skyld;","Alt hvad som sælges i Slagterbod, det æder, uden at spørge for Samvittighedens Skyld;"],[10,26,"thi Jorden er Herrens og dens Fylde.","thi Jorden er Herrens og dens Fylde."],[10,27,"Og dersom nogen af de Vantroe indbyder Eder, og I ville gaae derhen, da æder alt det, som sættes for Eder, uden at spørge for Samvittighedens Skyld.","Og dersom nogen af de Vantroe indbyder Eder, og I ville gaae derhen, da æder alt det, som sættes for Eder, uden at spørge for Samvittighedens Skyld."],[10,28,"Men dersom Nogen siger til Eder: det er Afguds-Offer, da æder det ikke, for hans Skyld, som gav det tilkjende, og for Samvittighedens Skyld.","Men dersom Nogen siger til Eder: det er Afguds-Offer, da æder det ikke, for hans Skyld, som gav det tilkjende, og for Samvittighedens Skyld."],[10,29,"Samvittigheden, siger jeg, ikke Ens egen, men den Andens, thi hvorfor skulde min Frihed dømmes af en Andens Samvittighed?","Samvittigheden, siger jeg, ikke Ens egen, men den Andens, thi hvorfor skulde min Frihed dømmes af en Andens Samvittighed?"],[10,30,"Dersom jeg nyder det med Taksigelse, hvi hører jeg da ilde for det, som jeg takker for?","Dersom jeg nyder det med Taksigelse, hvi hører jeg da ilde for det, som jeg takker for?"],[10,31,"Hvad heller I derfor æde eller drikke, eller hvad I gjøre, da gjører Alt til Guds Ære!","Hvad heller I derfor æde eller drikke, eller hvad I gjøre, da gjører Alt til Guds Ære!"],[10,32,"Værer uden Forargelse baade for Jøder og Græker og for Guds Menighed;","Værer uden Forargelse baade for Jøder og Græker og for Guds Menighed;"],[10,33,"ligesom jeg og i Alt stræber at tækkes Alle, idet jeg ikke søger det, som er mig selv, men det, som er Mange nyttigt, at de kunne frelses.","ligesom jeg og i Alt stræber at tækkes Alle, idet jeg ikke søger det, som er mig selv, men det, som er Mange nyttigt, at de kunne frelses."],[11,2,"Men jeg roser Eder, Brødre! at I i Alt komme mig ihu og bevare Anordningerne, saasom jeg haver overantvordet Eder.","Men jeg roser Eder, Brødre! at I i Alt komme mig ihu og bevare Anordningerne, saasom jeg haver overantvordet Eder."],[11,3,"Men jeg vil, at I skulle betænke, at Christus er enhver Mands Hoved; men Manden er Kvindens Hoved; men Gud er Christi Hoved.","Men jeg vil, at I skulle betænke, at Christus er enhver Mands Hoved; men Manden er Kvindens Hoved; men Gud er Christi Hoved."],[11,4,"Hver Mand, som beder eller propheterer, og haver Noget paa Hovedet, beskæmmer sit Hoved.","Hver Mand, som beder eller propheterer, og haver Noget paa Hovedet, beskæmmer sit Hoved."],[11,5,"Men hver Kvinde, som beder eller propheterer, med ubedækket Hoved, beskæmmer sit Hoved; thi det er det Samme, som var hun raget.","Men hver Kvinde, som beder eller propheterer, med ubedækket Hoved, beskæmmer sit Hoved; thi det er det Samme, som var hun raget."],[11,6,"Thi dersom en Kvinde ikke bedækker sig, kan hun og lade Haaret afklippe; men er det Kvinden usømmeligt at klippes eller rages, da bedække hun sig.","Thi dersom en Kvinde ikke bedækker sig, kan hun og lade Haaret afklippe; men er det Kvinden usømmeligt at klippes eller rages, da bedække hun sig."],[11,7,"Thi en Mand bør ikke bedække Hovedet, efterdi han er Guds Billede og Ære; men Kvinden er Mandens Ære.","Thi en Mand bør ikke bedække Hovedet, efterdi han er Guds Billede og Ære; men Kvinden er Mandens Ære."],[11,8,"Thi Manden er ikke af Kvinden, men Kvinden af Manden;","Thi Manden er ikke af Kvinden, men Kvinden af Manden;"],[11,9,"ei heller er Manden skabt for Kvindens Skyld, men Kvinden for Mandens Skyld.","ei heller er Manden skabt for Kvindens Skyld, men Kvinden for Mandens Skyld."],[11,10,"Derfor bør Kvinden have Ærbødighedstegn paa Hovedet for Englenes Skyld.","Derfor bør Kvinden have Ærbødighedstegn paa Hovedet for Englenes Skyld."],[11,11,"Dog er hverken Manden uden Kvinden, ei heller Kvinden uden Manden i Herren.","Dog er hverken Manden uden Kvinden, ei heller Kvinden uden Manden i Herren."],[11,12,"Thi ligesom Kvinden er af Manden, saa er og Manden ved Kvinden; men alle Ting af Gud.","Thi ligesom Kvinden er af Manden, saa er og Manden ved Kvinden; men alle Ting af Gud."],[11,13,"Dømmer selv: lader det vel for en Kvinde, at bede med blottet Hoved til Gud?","Dømmer selv: lader det vel for en Kvinde, at bede med blottet Hoved til Gud?"],[11,14,"Eller lærer ikke Naturen selv Eder, at dersom en Mand lader Haaret voxe langt, er det ham en Vanære?","Eller lærer ikke Naturen selv Eder, at dersom en Mand lader Haaret voxe langt, er det ham en Vanære?"],[11,15,"Men dersom en Kvinde lader Haaret voxe langt, er det hende en Ære; thi Haaret er givet hende til et Skjul.","Men dersom en Kvinde lader Haaret voxe langt, er det hende en Ære; thi Haaret er givet hende til et Skjul."],[11,16,"Men er der Nogen, som haver Lyst til at trættes herom, da have vi ikke saadan Skik, og Guds Menigheder ei heller.","Men er der Nogen, som haver Lyst til at trættes herom, da have vi ikke saadan Skik, og Guds Menigheder ei heller."],[11,17,"Men idet jeg formaner herom, roser jeg ikke, at I komme sammen ei til det Bedre, men til det Værre.","Men idet jeg formaner herom, roser jeg ikke, at I komme sammen ei til det Bedre, men til det Værre."],[11,18,"For det Første hører jeg, at naar I komme sammen i Menigheden, er der Splidagtighed iblandt Eder; og for en Deel troer jeg det.","For det Første hører jeg, at naar I komme sammen i Menigheden, er der Splidagtighed iblandt Eder; og for en Deel troer jeg det."],[11,19,"Thi der maa og være Partier iblandt Eder, at de Retskafne iblandt Eder kunne blive aabenbare.","Thi der maa og være Partier iblandt Eder, at de Retskafne iblandt Eder kunne blive aabenbare."],[11,20,"Naar I da komme sammen, da er dette ikke at æde Herrens Nadvere.","Naar I da komme sammen, da er dette ikke at æde Herrens Nadvere."],[11,21,"Thi under Maaltidet tager Enhver sin egen Nadvere forud, og den Ene hungrer, den Anden overvælder sig.","Thi under Maaltidet tager Enhver sin egen Nadvere forud, og den Ene hungrer, den Anden overvælder sig."],[11,22,"Have I ikke Huse til at æde og drikke udi? eller foragte I Guds Menighed og beskæmme dem, som Intet have? Hvad skal jeg siger Eder? skal jeg rose Eder? I dette roser jeg Eder ikke.","Have I ikke Huse til at æde og drikke udi? eller foragte I Guds Menighed og beskæmme dem, som Intet have? Hvad skal jeg siger Eder? skal jeg rose Eder? I dette roser jeg Eder ikke."],[11,23,"Thi jeg annammede det fra Herren, som jeg og haver overantvordet Eder: at den Herre Jesus i den Nat, der han blev forraadet, tog Brødet,","Thi jeg annammede det fra Herren, som jeg og haver overantvordet Eder: at den Herre Jesus i den Nat, der han blev forraadet, tog Brødet,"],[11,24,"takkede og brød det, og sagde: tager, æder; dette er mit Legeme, som brydes for Eder; dette gjører til min Ihukommelse!","takkede og brød det, og sagde: tager, æder; dette er mit Legeme, som brydes for Eder; dette gjører til min Ihukommelse!"],[11,25,"Desligeste og Kalken, efterat han havde holdet Nadvere, og sagde: denne Kalk er det nye Testament i mit Blod; dette gjører, saa ofte som I det drikke, til min Ihukommelse!","Desligeste og Kalken, efterat han havde holdet Nadvere, og sagde: denne Kalk er det nye Testament i mit Blod; dette gjører, saa ofte som I det drikke, til min Ihukommelse!"],[11,26,"Thi saa ofte som I æde dette Brød og drikke denne Kalk, forkynder Herrens Død, indtil han kommer.","Thi saa ofte som I æde dette Brød og drikke denne Kalk, forkynder Herrens Død, indtil han kommer."],[11,27,"Derfor, hvo som æder dette Brød eller drikker Herrens Kalk uværdeligen, skal være skyldig i Herrens Legeme og Blod.","Derfor, hvo som æder dette Brød eller drikker Herrens Kalk uværdeligen, skal være skyldig i Herrens Legeme og Blod."],[11,28,"Men hvert Menneske prøve sig selv, og saaledes æde han af Brødet og drikke af Kalken.","Men hvert Menneske prøve sig selv, og saaledes æde han af Brødet og drikke af Kalken."],[11,29,"Thi hvo som æder og drikker uværdeligen, æder og drikker sig selv til Dom, idet han ikke gjør Forskjel paa Herrens Legeme.","Thi hvo som æder og drikker uværdeligen, æder og drikker sig selv til Dom, idet han ikke gjør Forskjel paa Herrens Legeme."],[11,30,"Derfor ere mange skrøbelige og svage iblandt Eder, og en Deel ere hensovede.","Derfor ere mange skrøbelige og svage iblandt Eder, og en Deel ere hensovede."],[11,31,"Thi dersom vi dømte os selv, dømtes vi ikke.","Thi dersom vi dømte os selv, dømtes vi ikke."],[11,32,"Men naar vi dømmes af Herren, revses vi, at vi ikke med Verden skulle fordømmes.","Men naar vi dømmes af Herren, revses vi, at vi ikke med Verden skulle fordømmes."],[11,33,"Derfor, mine Brødre! naar I komme sammen til Maaltidet, da deler med hverandre.","Derfor, mine Brødre! naar I komme sammen til Maaltidet, da deler med hverandre."],[11,34,"Men dersom Nogen hungrer, han æde hjemme, at I ikke skulle komme sammen til Dom. Det Øvrige skal jeg anordne, naar jeg kommer.","Men dersom Nogen hungrer, han æde hjemme, at I ikke skulle komme sammen til Dom. Det Øvrige skal jeg anordne, naar jeg kommer."],[12,1,"Betræffende de aandelige Gaver, Brødre! vil jeg ikke, at I skulle være uvidende.","Betræffende de aandelige Gaver, Brødre! vil jeg ikke, at I skulle være uvidende."],[12,2,"I vide, at I vare Hedninger og hendroges til de stumme Afguder, som man drog Eder.","I vide, at I vare Hedninger og hendroges til de stumme Afguder, som man drog Eder."],[12,3,"Derfor kundgjør Jesus Eder, at Ingen som taler ved Guds Aand, udsiger Forbandelse over Jesus, og Ingen kan kalde Jesus Herre uden ved den Hellig Aand.","Derfor kundgjør Jesus Eder, at Ingen som taler ved Guds Aand, udsiger Forbandelse over Jesus, og Ingen kan kalde Jesus Herre uden ved den Hellig Aand."],[12,4,"Der er Forskjel paa Naadegaver, men Aanden er den samme;","Der er Forskjel paa Naadegaver, men Aanden er den samme;"],[12,5,"og der er Forskjel paa Tjenester, men Herren er den samme;","og der er Forskjel paa Tjenester, men Herren er den samme;"],[12,6,"og der er Forskjel paa kraftige Gjerninger, men Gud er den samme, som krafteligen virker Alt i Alle.","og der er Forskjel paa kraftige Gjerninger, men Gud er den samme, som krafteligen virker Alt i Alle."],[12,7,"Men Aandens Aabenbarelse gives hver til det, som er nyttigt.","Men Aandens Aabenbarelse gives hver til det, som er nyttigt."],[12,8,"Thi En gives Viisdoms-Tale formedelst Aanden; en Anden Kundskabs-Tale ved den samme Aand;","Thi En gives Viisdoms-Tale formedelst Aanden; en Anden Kundskabs-Tale ved den samme Aand;"],[12,9,"en anden Tro ved den samme Aand; en anden Gaver til at helbrede ved den samme Aand;","en anden Tro ved den samme Aand; en anden Gaver til at helbrede ved den samme Aand;"],[12,10,"en Anden Kraft til Undergjerninger; en Anden prophetisk Gave; en Anden at bedømme Aander; en Anden adskillige Tungemaal; en Anden at udlægge Tungemaal.","en Anden Kraft til Undergjerninger; en Anden prophetisk Gave; en Anden at bedømme Aander; en Anden adskillige Tungemaal; en Anden at udlægge Tungemaal."],[12,11,"Men alt dette virker krafteligen den ene og samme Aand, som uddeler til Enhver i Besynderlighed, eftersom han vil.","Men alt dette virker krafteligen den ene og samme Aand, som uddeler til Enhver i Besynderlighed, eftersom han vil."],[12,12,"Thi ligesom Legemet er eet, og haver mange Lemmer, men alle Lemmer paa det ene Legeme, enddog de ere mange, ere eet Legeme, saaledes ogsaa Christus.","Thi ligesom Legemet er eet, og haver mange Lemmer, men alle Lemmer paa det ene Legeme, enddog de ere mange, ere eet Legeme, saaledes ogsaa Christus."],[12,13,"Vi ere jo alle døbte i een Aand til at være eet Legeme, hvad heller vi ere Jøder eller Græker, eller Trælle eller Frie; og vi have alle drukket af Kalken til at være den samme Aand.","Vi ere jo alle døbte i een Aand til at være eet Legeme, hvad heller vi ere Jøder eller Græker, eller Trælle eller Frie; og vi have alle drukket af Kalken til at være den samme Aand."],[12,14,"Ogsaa Legemet er ikke et Lem, men mange.","Ogsaa Legemet er ikke et Lem, men mange."],[12,15,"Dersom Foden vilde sige: fordi jeg ikke er Haand, derfor hører jeg ikke til Legemet, mon den derfor ikke høre til Legemet?","Dersom Foden vilde sige: fordi jeg ikke er Haand, derfor hører jeg ikke til Legemet, mon den derfor ikke høre til Legemet?"],[12,16,"Og dersom Øret vilde sige: fordi jeg ikke er Øie, derfor hører jeg ikke til Legemet, mon det derfor ikke høre til Legemet?","Og dersom Øret vilde sige: fordi jeg ikke er Øie, derfor hører jeg ikke til Legemet, mon det derfor ikke høre til Legemet?"],[12,17,"Dersom det ganske Legeme var Øie, hvor blev da Hørelsen? Dersom det ganske Legeme var Hørelse, hvor blev da Lugten?","Dersom det ganske Legeme var Øie, hvor blev da Hørelsen? Dersom det ganske Legeme var Hørelse, hvor blev da Lugten?"],[12,18,"Men nu haver Gud sat Lemmerne, ethvert af dem, i Legemet, eftersom han vilde.","Men nu haver Gud sat Lemmerne, ethvert af dem, i Legemet, eftersom han vilde."],[12,19,"Dersom de alle vare eet Lem, hvor blev da Legemet?","Dersom de alle vare eet Lem, hvor blev da Legemet?"],[12,20,"Men nu ere der vel mange Lemmer, dog kun eet Legeme.","Men nu ere der vel mange Lemmer, dog kun eet Legeme."],[12,21,"Øiet kan ikke sige til Haanden: jeg haver dig ikke behov, eller atter Hovedet til Fødderne: jeg haver Eder ikke behov.","Øiet kan ikke sige til Haanden: jeg haver dig ikke behov, eller atter Hovedet til Fødderne: jeg haver Eder ikke behov."],[12,22,"Meget mere ere de Lemmer paa Legemet fornødne, som synes at være de skrøbeligste;","Meget mere ere de Lemmer paa Legemet fornødne, som synes at være de skrøbeligste;"],[12,23,"og de, som synes os at være de uanseeligste, dem tillægge vi des mere Ziir; og de, som lade os ilde, dem pryde vi des mere;","og de, som synes os at være de uanseeligste, dem tillægge vi des mere Ziir; og de, som lade os ilde, dem pryde vi des mere;"],[12,24,"de derimod, som lade os vel, have det ikke behov. Men Gud haver saaledes sammenføiet Legemet, at han tillagde de ringere Dele mere Ære;","de derimod, som lade os vel, have det ikke behov. Men Gud haver saaledes sammenføiet Legemet, at han tillagde de ringere Dele mere Ære;"],[12,25,"paa det der ikke skal være Splid i Legemet, men at Lemmerne skulle have lige Omhyggelighed for hverandre;","paa det der ikke skal være Splid i Legemet, men at Lemmerne skulle have lige Omhyggelighed for hverandre;"],[12,26,"saa at, enten eet Lem lider, lide alle Lemmerne med, eller eet Lem bliver holdet i Ære, glæde alle Lemmerne sig med.","saa at, enten eet Lem lider, lide alle Lemmerne med, eller eet Lem bliver holdet i Ære, glæde alle Lemmerne sig med."],[12,27,"Men I ere Christi Legeme og Lemmer enhver især.","Men I ere Christi Legeme og Lemmer enhver især."],[12,28,"Gud haver sat i Menigheden først Apostler, for det Andet Propheter, for at det Tredie Lærere, dernæst dem, som gjøre kraftige Gjerninger, derefter dem, som have Gaver til at helbrede, til at hjælpe, til at styre, til at tale adskillige Tungemaal.","Gud haver sat i Menigheden først Apostler, for det Andet Propheter, for at det Tredie Lærere, dernæst dem, som gjøre kraftige Gjerninger, derefter dem, som have Gaver til at helbrede, til at hjælpe, til at styre, til at tale adskillige Tungemaal."],[12,29,"Monne Alle være Apostler? monne Alle være Propheter? monne Alle være Lærere? monne Alle gjøre kraftige Gjerninger?","Monne Alle være Apostler? monne Alle være Propheter? monne Alle være Lærere? monne Alle gjøre kraftige Gjerninger?"],[12,30,"monne Alle have Gaver til at helbrede? monne Alle tale med adskillige Tungemaal? monne Alle udlægge?","monne Alle have Gaver til at helbrede? monne Alle tale med adskillige Tungemaal? monne Alle udlægge?"],[12,31,"Tragter efter de bedste Naadegaver! Og ydermere viser jeg Eder den ypperligste Vei.","Tragter efter de bedste Naadegaver! Og ydermere viser jeg Eder den ypperligste Vei."],[13,1,"Talede jeg med Menneskers og Engles Tungemaal, men havde ikke Kjærlighed, da var jeg et lydende Malm eller en klingende Bjelde.","Talede jeg med Menneskers og Engles Tungemaal, men havde ikke Kjærlighed, da var jeg et lydende Malm eller en klingende Bjelde."],[13,2,"Og havde jeg prophetisk Gave, og vidste alle Hemmeligheder og al Kundskab, og havde jeg al Tro, saa at jeg kunde flytte Bjerge, men havde ikke Kjærlighed, da var jeg Intet.","Og havde jeg prophetisk Gave, og vidste alle Hemmeligheder og al Kundskab, og havde jeg al Tro, saa at jeg kunde flytte Bjerge, men havde ikke Kjærlighed, da var jeg Intet."],[13,3,"Og uddeelte jeg alt mig Gods til de Fattige, og gav jeg mit Legeme hen for at brændes, men havde ikke Kjærlighed, da gavnede det mig Intet.","Og uddeelte jeg alt mig Gods til de Fattige, og gav jeg mit Legeme hen for at brændes, men havde ikke Kjærlighed, da gavnede det mig Intet."],[13,4,"Kjærligheden er langmodig, er velvillig; Kjærligheden bærer ikke Nid; Kjærligheden bruger ikke Fremfusenhed, opblæses ikke;","Kjærligheden er langmodig, er velvillig; Kjærligheden bærer ikke Nid; Kjærligheden bruger ikke Fremfusenhed, opblæses ikke;"],[13,5,"den gjør intet Usømmeligt; søger ikke sit Eget, forbittres ikke, bærer ikke Nag;","den gjør intet Usømmeligt; søger ikke sit Eget, forbittres ikke, bærer ikke Nag;"],[13,6,"glæder sig ikke over Uretfærdighed, men glæder sig ved Sandhed;","glæder sig ikke over Uretfærdighed, men glæder sig ved Sandhed;"],[13,7,"fordrager Alt, troer Alt, haaber Alt, taaler Alt.","fordrager Alt, troer Alt, haaber Alt, taaler Alt."],[13,8,"Kjærligheden affalder aldrig; men enten det er prophetiske Gaver, de skulle afskaffes, eller Tungemaal, de skulle ophøre, eller Kundskab, den skal afskaffes;","Kjærligheden affalder aldrig; men enten det er prophetiske Gaver, de skulle afskaffes, eller Tungemaal, de skulle ophøre, eller Kundskab, den skal afskaffes;"],[13,9,"thi vi forstaae i stykkeviis, og prophetere i stykkeviis;","thi vi forstaae i stykkeviis, og prophetere i stykkeviis;"],[13,10,"men naar det Fuldkomne kommer, da skal det, som er i stykkeviis, afskaffes.","men naar det Fuldkomne kommer, da skal det, som er i stykkeviis, afskaffes."],[13,11,"Da jeg var et Barn, talede jeg som et Barn, tænkte jeg som et Barn, dømte jeg som et Barn; men da jeg blev Mand, aflagde jeg det Barnagtige.","Da jeg var et Barn, talede jeg som et Barn, tænkte jeg som et Barn, dømte jeg som et Barn; men da jeg blev Mand, aflagde jeg det Barnagtige."],[13,12,"Thi nu see vi ved et Speil, i en mørk Tale, men da skulle vi see Ansigt til Ansigt; nu kjender jeg i stykkeviis, men da skal jeg erkjende, ligesom jeg og er kjendt.","Thi nu see vi ved et Speil, i en mørk Tale, men da skulle vi see Ansigt til Ansigt; nu kjender jeg i stykkeviis, men da skal jeg erkjende, ligesom jeg og er kjendt."],[13,13,"Saa bliver da Tro, Haab, Kjærlighed, disse tre; men størst iblandt disse er Kjærligheden.","Saa bliver da Tro, Haab, Kjærlighed, disse tre; men størst iblandt disse er Kjærligheden."],[14,1,"Higer efter Kjærligheden, tragter efter de aandelige Gaver, men meest, at I maatte prophetere .","Higer efter Kjærligheden, tragter efter de aandelige Gaver, men meest, at I maatte prophetere ."],[14,2,"Thi den, som taler med et fremmed Tungemaal, taler ikke for Mennesker, men for Gud; thi Ingen forstaaer det, men han taler Hemmeligheder i Aanden.","Thi den, som taler med et fremmed Tungemaal, taler ikke for Mennesker, men for Gud; thi Ingen forstaaer det, men han taler Hemmeligheder i Aanden."],[14,3,"Men hvo som propheterer, taler Mennesker til Opbyggelse og Formaning og Trøst.","Men hvo som propheterer, taler Mennesker til Opbyggelse og Formaning og Trøst."],[14,4,"Hvo som taler med et fremmed Tungemaal, opbygger sig selv; men hvo som propheterer, opbygger Menigheden.","Hvo som taler med et fremmed Tungemaal, opbygger sig selv; men hvo som propheterer, opbygger Menigheden."],[14,5,"Jeg vilde, at I alle kunde tale med fremmede Tungemaal, men mere, at I kunde prophetere; thi den, som propheterer, er større end den, som taler med fremmede Tungemaal, uden saa er, at han det udlægger, saa at Menigheden haver Opbyggelse deraf.","Jeg vilde, at I alle kunde tale med fremmede Tungemaal, men mere, at I kunde prophetere; thi den, som propheterer, er større end den, som taler med fremmede Tungemaal, uden saa er, at han det udlægger, saa at Menigheden haver Opbyggelse deraf."],[14,6,"Men nu, Brødre! dersom jeg kom til Eder og talede med fremmede Tungemaal, hvad gavnede jeg Eder, dersom jeg ikke talede med Eder enten ved Aabenbarelse eller ved Kundskab eller ved Propheti eller ved Lærdom?","Men nu, Brødre! dersom jeg kom til Eder og talede med fremmede Tungemaal, hvad gavnede jeg Eder, dersom jeg ikke talede med Eder enten ved Aabenbarelse eller ved Kundskab eller ved Propheti eller ved Lærdom?"],[14,7,"Endog de livløse Ting, som have Lyd, enten det er en Fløite eller Harpe, dersom de ikke give tydelige Toner, hvorledes kan man da vide, hvad der er spillet paa Fløiten eller Harpen?","Endog de livløse Ting, som have Lyd, enten det er en Fløite eller Harpe, dersom de ikke give tydelige Toner, hvorledes kan man da vide, hvad der er spillet paa Fløiten eller Harpen?"],[14,8,"Og om Basunen giver en utydelig Lyd, hvo vil berede sig til Krig?","Og om Basunen giver en utydelig Lyd, hvo vil berede sig til Krig?"],[14,9,"Saaledes og, dersom I ikke ved Tungen fremføre tydelig Tale, hvorledes kan man forstaae det, som tales? Da ville I jo tale han i Veiret.","Saaledes og, dersom I ikke ved Tungen fremføre tydelig Tale, hvorledes kan man forstaae det, som tales? Da ville I jo tale han i Veiret."],[14,10,"Der er i Verden, lad os sige, saa og saa mangeslags Sprog, og der er intet af dem, som jo haver sin Betydning.","Der er i Verden, lad os sige, saa og saa mangeslags Sprog, og der er intet af dem, som jo haver sin Betydning."],[14,11,"Dersom jeg da ikke veed Sprogets Betydning, bliver jeg for den, som taler, en Barbar, og den, som taler, bliver for mig en Barbar.","Dersom jeg da ikke veed Sprogets Betydning, bliver jeg for den, som taler, en Barbar, og den, som taler, bliver for mig en Barbar."],[14,12,"Altsaa, efterdi I hige efter aandelige Gaver, da søger ogsaa I at have overflødigen til Menighedens Opbyggelse.","Altsaa, efterdi I hige efter aandelige Gaver, da søger ogsaa I at have overflødigen til Menighedens Opbyggelse."],[14,13,"Derfor, hvo som taler med fremmed Tungemaal, bede, at han maa kunne udlægge det.","Derfor, hvo som taler med fremmed Tungemaal, bede, at han maa kunne udlægge det."],[14,14,"Thi dersom jeg gjør Bøn i fremmed Tungemaal, da beder vel min Aand, men mine Ords Forstand er uden Frugt.","Thi dersom jeg gjør Bøn i fremmed Tungemaal, da beder vel min Aand, men mine Ords Forstand er uden Frugt."],[14,15,"Hvad bør da skee? Jeg vil bede med Aanden, men jeg vil og bede med Forstand ; jeg vil synge med Aanden, men jeg vil og synge med Forstand.","Hvad bør da skee? Jeg vil bede med Aanden, men jeg vil og bede med Forstand ; jeg vil synge med Aanden, men jeg vil og synge med Forstand."],[14,16,"Thi dersom du priser Gud i Aanden , hvorledes kan den, som staaer paa Lægmands Plads, sige Amen til din Taksigelse, efterdi han ikke veed, hvad du siger?","Thi dersom du priser Gud i Aanden , hvorledes kan den, som staaer paa Lægmands Plads, sige Amen til din Taksigelse, efterdi han ikke veed, hvad du siger?"],[14,17,"Thi vel er din Taksigelse smuk, men den Anden opbygges ikke.","Thi vel er din Taksigelse smuk, men den Anden opbygges ikke."],[14,18,"Jeg takker min Gud, at jeg mere end I alle taler i fremmede Tungemaal.","Jeg takker min Gud, at jeg mere end I alle taler i fremmede Tungemaal."],[14,19,"Men i Menigheden vil jeg hellere tale fem Ord forstaaeligen, paa det jeg og kan undervise Andre, end ti tusinde Ord i fremmed Tungemaal.","Men i Menigheden vil jeg hellere tale fem Ord forstaaeligen, paa det jeg og kan undervise Andre, end ti tusinde Ord i fremmed Tungemaal."],[14,20,"Brødre! vorder ikke Børn i Forstand, men værer Børn i Ondskab, i Forstand derimod værer fuldvoxne.","Brødre! vorder ikke Børn i Forstand, men værer Børn i Ondskab, i Forstand derimod værer fuldvoxne."],[14,21,"Der er skrevet i Loven: ved dem, som have andre Tungemaal, og ved andre Læber vil jeg tale til dette Folk, og de skulle end ikke saaledes høre mig, siger Herren.","Der er skrevet i Loven: ved dem, som have andre Tungemaal, og ved andre Læber vil jeg tale til dette Folk, og de skulle end ikke saaledes høre mig, siger Herren."],[14,22,"Derfor ere disse Tungemaal til et Tegn, ikke for dem, som troe, men for de Vantroe; men den prophetiske Gave er det ikke for de Vantroe, men for dem, som troe.","Derfor ere disse Tungemaal til et Tegn, ikke for dem, som troe, men for de Vantroe; men den prophetiske Gave er det ikke for de Vantroe, men for dem, som troe."],[14,23,"Naar altsaa den ganske Menighed kom tilsammen, og Alle talede med fremmede Tungemaal, men der kom Lægfolk eller Vantroe ind, vilde de ikke sige, at I vare galne?","Naar altsaa den ganske Menighed kom tilsammen, og Alle talede med fremmede Tungemaal, men der kom Lægfolk eller Vantroe ind, vilde de ikke sige, at I vare galne?"],[14,24,"Men dersom Alle prophetere, og der kommer nogen Vantroe eller Lægmand ind, da overbevises han af Alle, han vises tilrette af Alle,","Men dersom Alle prophetere, og der kommer nogen Vantroe eller Lægmand ind, da overbevises han af Alle, han vises tilrette af Alle,"],[14,25,"hans Hjertes skjulte Tanker aabenbares, og saa vil han falde paa sit Ansigt og tilbede Gud og forkynde, at Gud er sandeligen i Eder.","hans Hjertes skjulte Tanker aabenbares, og saa vil han falde paa sit Ansigt og tilbede Gud og forkynde, at Gud er sandeligen i Eder."],[14,26,"Hvad bør da skee, Brødre? Naar I komme sammen, da haver hver af Eder en Psalme, han haver en Lærdom, han haver et fremmed Tungemaal, han haver en Aabenbarelse, han haver en Udlæggelse; Alt skee til Opbyggelse!","Hvad bør da skee, Brødre? Naar I komme sammen, da haver hver af Eder en Psalme, han haver en Lærdom, han haver et fremmed Tungemaal, han haver en Aabenbarelse, han haver en Udlæggelse; Alt skee til Opbyggelse!"],[14,27,"Dersom Nogen taler i fremmed Tungemaal, da være det To, eller i det høieste Tre, og den Ene efter den Anden, og Een udlægge det.","Dersom Nogen taler i fremmed Tungemaal, da være det To, eller i det høieste Tre, og den Ene efter den Anden, og Een udlægge det."],[14,28,"Men dersom der ingen Udlægger er tilstede, da tie hiin i Menigheden, men han tale for sig selv og for Gud.","Men dersom der ingen Udlægger er tilstede, da tie hiin i Menigheden, men han tale for sig selv og for Gud."],[14,29,"Af Propheter tale to eller tre, og de andre prøve det.","Af Propheter tale to eller tre, og de andre prøve det."],[14,30,"Men dersom en Anden, som sidder der, faaer en Aabenbarelse, da tie den Første.","Men dersom en Anden, som sidder der, faaer en Aabenbarelse, da tie den Første."],[14,31,"Thi I kunne alle prophetere, den Ene efter den Anden, at Alle kunne lære, og Alle blive formanede.","Thi I kunne alle prophetere, den Ene efter den Anden, at Alle kunne lære, og Alle blive formanede."],[14,32,"Ogsaa Propheters Aander ere Propheter underdanige.","Ogsaa Propheters Aander ere Propheter underdanige."],[14,33,"Thi Gud er ikke Forvirringens, men Fredens Gud. Ligesom i alle de Helliges Menigheder,","Thi Gud er ikke Forvirringens, men Fredens Gud. Ligesom i alle de Helliges Menigheder,"],[14,34,"tie Eders Kvinder i Forsamlingerne; thi det er dem ikke tilstedt at tale, men at være underdanige, ligesom Loven og siger.","tie Eders Kvinder i Forsamlingerne; thi det er dem ikke tilstedt at tale, men at være underdanige, ligesom Loven og siger."],[14,35,"Men ville de lære Noget, da adspørge de deres egne Mænd hjemme; thi det lader Kvinder ilde at tale i en Menighed.","Men ville de lære Noget, da adspørge de deres egne Mænd hjemme; thi det lader Kvinder ilde at tale i en Menighed."],[14,36,"Eller er Guds Ord udgaaet fra Eder? eller er det kommet til Eder alene?","Eller er Guds Ord udgaaet fra Eder? eller er det kommet til Eder alene?"],[14,37,"Dersom Nogen lader sig tykke, at han er en Prophet eller Aandelig, han betænke det, som jeg skriver til Eder, at det er Herrens Bud.","Dersom Nogen lader sig tykke, at han er en Prophet eller Aandelig, han betænke det, som jeg skriver til Eder, at det er Herrens Bud."],[14,38,"Men erkjender Nogen det ikke, da lade han være!","Men erkjender Nogen det ikke, da lade han være!"],[14,39,"Derfor, Brødre! tragter efter de prophetiske Gaver, og formener ikke at tale med fremmede Tungemaal.","Derfor, Brødre! tragter efter de prophetiske Gaver, og formener ikke at tale med fremmede Tungemaal."],[14,40,"Alt skee sømmeligen og med Orden!","Alt skee sømmeligen og med Orden!"],[15,1,"Fremdeles minder jeg Eder, Brødre! om det Evangelium, som jeg forkyndte Eder, hvilket I og annammede, i hvilket I og ere vedblevne,","Fremdeles minder jeg Eder, Brødre! om det Evangelium, som jeg forkyndte Eder, hvilket I og annammede, i hvilket I og ere vedblevne,"],[15,2,"ved hvilket I og blive salige, dersom I det beholde efter den Tale, hvormed jeg forkyndte Eder det, men mindre I have troet letsindigen.","ved hvilket I og blive salige, dersom I det beholde efter den Tale, hvormed jeg forkyndte Eder det, men mindre I have troet letsindigen."],[15,3,"Thi overantvorde Eder iblandt det Første, hvad og jeg annammede: at Christus døde for vore Synder, efter Skrifterne;","Thi overantvorde Eder iblandt det Første, hvad og jeg annammede: at Christus døde for vore Synder, efter Skrifterne;"],[15,4,"og at han blev begraven;","og at han blev begraven;"],[15,5,"og at han opstod den tredie Dag, efter Skrifterne;","og at han opstod den tredie Dag, efter Skrifterne;"],[15,6,"og at han blev seet af Kephas, derefter af de Tolv.","og at han blev seet af Kephas, derefter af de Tolv."],[15,7,"Derpaa blev han seet af mere end fem hundrede Brødre paa eengang, af hvilke de fleste endnu ere i Live, men nogle ere og hensovede.","Derpaa blev han seet af mere end fem hundrede Brødre paa eengang, af hvilke de fleste endnu ere i Live, men nogle ere og hensovede."],[15,8,"Derefter blev han seet af Jakobus, dernæst af alle Apostlerne.","Derefter blev han seet af Jakobus, dernæst af alle Apostlerne."],[15,9,"Men sidst af Alle blev han seet af mig, som det utidige Foster; thi jeg er den ringeste af Apostlerne, som er ikke værd at kaldes Apostel, fordi jeg haver forfulgt Guds Menighed.","Men sidst af Alle blev han seet af mig, som det utidige Foster; thi jeg er den ringeste af Apostlerne, som er ikke værd at kaldes Apostel, fordi jeg haver forfulgt Guds Menighed."],[15,10,"Men af Guds Naade er jeg det, jeg er, og hans Naade mod mig haver ikke været forgjeves; men jeg haver arbeidet mere end de alle, dog ikke jeg, men Guds Naade, som er med mig.","Men af Guds Naade er jeg det, jeg er, og hans Naade mod mig haver ikke været forgjeves; men jeg haver arbeidet mere end de alle, dog ikke jeg, men Guds Naade, som er med mig."],[15,11,"Hvad heller det da er mig eller de Andre, saaledes prædike vi, og saaledes troede I.","Hvad heller det da er mig eller de Andre, saaledes prædike vi, og saaledes troede I."],[15,12,"Men naar da Christus prædikes at være opstanden fra de Døde, hvorledes sige da Nogle iblandt Eder, at der ikke er Dødes Opstandelse?","Men naar da Christus prædikes at være opstanden fra de Døde, hvorledes sige da Nogle iblandt Eder, at der ikke er Dødes Opstandelse?"],[15,13,"Men dersom der ikke er Dødes Opstandelse, da er ikke heller Christus opstanden.","Men dersom der ikke er Dødes Opstandelse, da er ikke heller Christus opstanden."],[15,14,"Men er Christus ikke opstanden, da er vor Prædiken jo forgjeves, og saa er og Eders Tro forgjeves.","Men er Christus ikke opstanden, da er vor Prædiken jo forgjeves, og saa er og Eders Tro forgjeves."],[15,15,"Vi blive da og fundne som falske Vidner om Gud, idet vi have vidnet om Gud, at han opreiste Christus, hvilken han ikke haver opreist, dersom nemlig de Døde ikke opreises.","Vi blive da og fundne som falske Vidner om Gud, idet vi have vidnet om Gud, at han opreiste Christus, hvilken han ikke haver opreist, dersom nemlig de Døde ikke opreises."],[15,16,"Thi dersom de Døde ikke opstaae, da er Christus ikke heller opstanden.","Thi dersom de Døde ikke opstaae, da er Christus ikke heller opstanden."],[15,17,"Men dersom Christus ikke er opstanden, da er Eders Tro forfængelig; saa ere I endnu i Eders Synder;","Men dersom Christus ikke er opstanden, da er Eders Tro forfængelig; saa ere I endnu i Eders Synder;"],[15,18,"saa ere og de fortabte, som ere hensovne i Christus.","saa ere og de fortabte, som ere hensovne i Christus."],[15,19,"Haabe vi alene paa Christus i dette Liv, da ere vi de elendigste af alle Mennesker.","Haabe vi alene paa Christus i dette Liv, da ere vi de elendigste af alle Mennesker."],[15,20,"Men nu er Christus opstanden fra de Døde, og er bleven den Førstegrøde af de hensovede.","Men nu er Christus opstanden fra de Døde, og er bleven den Førstegrøde af de hensovede."],[15,21,"Thi efterdi Døden kom ved et Menneske, er og de Dødes Opstandelse kommen ved et Menneske.","Thi efterdi Døden kom ved et Menneske, er og de Dødes Opstandelse kommen ved et Menneske."],[15,22,"Thi ligesom Alle døde i Adam, saa skulle og Alle levendegjøres i Christus.","Thi ligesom Alle døde i Adam, saa skulle og Alle levendegjøres i Christus."],[15,23,"Dog hver i sin Orden: den første Grøde er Christus, dernæst de, som ere Christi, udi hans Tilkommelse.","Dog hver i sin Orden: den første Grøde er Christus, dernæst de, som ere Christi, udi hans Tilkommelse."],[15,24,"Derpaa kommer Enden, naar han har overantvordet Gud og Faderen Riget, naar han har tilintetgjort alt Fyrstendømme og al Vælde og Magt.","Derpaa kommer Enden, naar han har overantvordet Gud og Faderen Riget, naar han har tilintetgjort alt Fyrstendømme og al Vælde og Magt."],[15,25,"Thi ham bør det at regjere, indtil han faaer langt alle Fjender under sine Fødder.","Thi ham bør det at regjere, indtil han faaer langt alle Fjender under sine Fødder."],[15,26,"Den sidste Fjende, som tilintetgjøres, er Døden.","Den sidste Fjende, som tilintetgjøres, er Døden."],[15,27,"Han haver jo lagt alle Ting under hans Fødder. Men naar han siger, at alle Ting ere ham underlagte, da er det aabenbart, at det er ham undtagen, som haver underlagt ham alle Ting.","Han haver jo lagt alle Ting under hans Fødder. Men naar han siger, at alle Ting ere ham underlagte, da er det aabenbart, at det er ham undtagen, som haver underlagt ham alle Ting."],[15,28,"Men naar alle Ting ere blevne ham underlagte, da skal og Sønnen selv underlægge sig ham, som haver underlagt ham alle Ting, at Gud skal være Alt i Alle.","Men naar alle Ting ere blevne ham underlagte, da skal og Sønnen selv underlægge sig ham, som haver underlagt ham alle Ting, at Gud skal være Alt i Alle."],[15,29,"Hvad monne de ellers gjøre, som dødes for de Døde, dersom de Døde aldeles ikke opreises? hvi døbes de da for de Døde?","Hvad monne de ellers gjøre, som dødes for de Døde, dersom de Døde aldeles ikke opreises? hvi døbes de da for de Døde?"],[15,30,"Hvi staae ogsaa vi hver Time i Fare?","Hvi staae ogsaa vi hver Time i Fare?"],[15,31,"Jeg døer dagligen, det vidner jeg ved vor Roes, den, som jeg haver i Christus Jesus vor Herre.","Jeg døer dagligen, det vidner jeg ved vor Roes, den, som jeg haver i Christus Jesus vor Herre."],[15,32,"Stred jeg, efter menneskelig Maade at tale, med vilde Dyr i Ephesus, hvad hjælper det mig, dersom de Døde ikke opstaae? Da lader os æde og drikke, thi i Morgen døe vi.","Stred jeg, efter menneskelig Maade at tale, med vilde Dyr i Ephesus, hvad hjælper det mig, dersom de Døde ikke opstaae? Da lader os æde og drikke, thi i Morgen døe vi."],[15,33,"Forføres ikke; slet Omgang fordærver gode Sæder.","Forføres ikke; slet Omgang fordærver gode Sæder."],[15,34,"Vaagner op, som det sømmer sig, og synder ikke; thi Nogle vide Intet af Gud, det siger jeg Eder til Blusel.","Vaagner op, som det sømmer sig, og synder ikke; thi Nogle vide Intet af Gud, det siger jeg Eder til Blusel."],[15,35,"Men der maatte Nogen sige: hvorledes opstaae de Døde? og med hvordant et Legeme komme de frem? Du Daare! det, som du saaer, bliver ikke levendegjort, dersom det ikke døer.","Men der maatte Nogen sige: hvorledes opstaae de Døde? og med hvordant et Legeme komme de frem? Du Daare! det, som du saaer, bliver ikke levendegjort, dersom det ikke døer."],[15,36,"Du Daare! det, som du saaer, bliver ikke levendegjort, dersom det ikke døer.","Du Daare! det, som du saaer, bliver ikke levendegjort, dersom det ikke døer."],[15,37,"Og hvad du saaer, da saaer du ikke det Legeme, der skal vorde, men et blot Korn, være sig af Hvede eller anden Art.","Og hvad du saaer, da saaer du ikke det Legeme, der skal vorde, men et blot Korn, være sig af Hvede eller anden Art."],[15,38,"Men Gud giver det et Legeme, ligesom han vil, og hver Sæd sit eget Legeme.","Men Gud giver det et Legeme, ligesom han vil, og hver Sæd sit eget Legeme."],[15,39,"Alt Kjød er ikke det samme Kjød, men eet er Menneskets Kjød, et andet Kvæget, et andet Fiskenes, et andet Fuglenes.","Alt Kjød er ikke det samme Kjød, men eet er Menneskets Kjød, et andet Kvæget, et andet Fiskenes, et andet Fuglenes."],[15,40,"Og der er himmelske Legemer og jordiske Legemer; men een er de himmelskes Herlighed, en anden de jordiskes.","Og der er himmelske Legemer og jordiske Legemer; men een er de himmelskes Herlighed, en anden de jordiskes."],[15,41,"Een er Solens Glands, en anden Maanens Glands, en anden Stjernernes Glands; thi en Stjerne overgaaer den anden i Klarhed.","Een er Solens Glands, en anden Maanens Glands, en anden Stjernernes Glands; thi en Stjerne overgaaer den anden i Klarhed."],[15,42,"Saaledes er og de Dødes Opstandelse: det saaes i Forkrænkelighed, det opstaaer i Uforkrænkelighed;","Saaledes er og de Dødes Opstandelse: det saaes i Forkrænkelighed, det opstaaer i Uforkrænkelighed;"],[15,43,"det saaes i Vanære, det opstaaer i Herlighed; det saaes i Skrøbelighed, det opstaaer i Kraft;","det saaes i Vanære, det opstaaer i Herlighed; det saaes i Skrøbelighed, det opstaaer i Kraft;"],[15,44,"der saaes et sandseligt Legeme, der opstaaer et aandeligt Legeme. Der er et sandseligt Legeme, der er ogsaa et aandeligt Legeme.","der saaes et sandseligt Legeme, der opstaaer et aandeligt Legeme. Der er et sandseligt Legeme, der er ogsaa et aandeligt Legeme."],[15,45,"Saaledes er der ogsaa skrevet: det første Menneske, Adam, er bleven til en levende Sjæl, den sidste Adam til en levendegjørende Aand.","Saaledes er der ogsaa skrevet: det første Menneske, Adam, er bleven til en levende Sjæl, den sidste Adam til en levendegjørende Aand."],[15,46,"Det Aandelige er ikke det første, men det Sandselige; derefter det Aandelige.","Det Aandelige er ikke det første, men det Sandselige; derefter det Aandelige."],[15,47,"Det første Menneske var af Jord, jordisk; det andet Menneske, Herren, er af Himmelen.","Det første Menneske var af Jord, jordisk; det andet Menneske, Herren, er af Himmelen."],[15,48,"Saadan som den Jordiske var, saadanne ere og de Jordiske; og saadan som den Himmelske er, saadanne ere og de Himmelske.","Saadan som den Jordiske var, saadanne ere og de Jordiske; og saadan som den Himmelske er, saadanne ere og de Himmelske."],[15,49,"Og ligesom vi have baaret den Jordiske Billede, saa skulle vi og bære den Himmelskes Billede.","Og ligesom vi have baaret den Jordiske Billede, saa skulle vi og bære den Himmelskes Billede."],[15,50,"Men dette siger jeg, Brødre! at Kjød og Blod kan ikke arve Guds Rige, ei heller skal Forkrænkelighed arve Uforkrænkelighed.","Men dette siger jeg, Brødre! at Kjød og Blod kan ikke arve Guds Rige, ei heller skal Forkrænkelighed arve Uforkrænkelighed."],[15,51,"See, jeg siger Eder en Hemmelighed: vi skulle vel ikke alle hensove, men vi skulle alle forandres,","See, jeg siger Eder en Hemmelighed: vi skulle vel ikke alle hensove, men vi skulle alle forandres,"],[15,52,"i en Hast, i et Øieblik, ved den sidste Basune; thi Basunen skal lyde, og de Døde skulle opstaae uforkrænkelige, og vi skulle forandres.","i en Hast, i et Øieblik, ved den sidste Basune; thi Basunen skal lyde, og de Døde skulle opstaae uforkrænkelige, og vi skulle forandres."],[15,53,"Thi det bør dette Forkrænkelige at iføres Uforkrænkelighed, og dette Dødelige at iføres Udødelighed.","Thi det bør dette Forkrænkelige at iføres Uforkrænkelighed, og dette Dødelige at iføres Udødelighed."],[15,54,"Men naar dette Forkrænkelige er iført Uforkrænkelighed, og dette Dødelige er iført Udødelighed, da opfyldes det Ord, som skrevet er: Døden er opslugt formedelst Seier.","Men naar dette Forkrænkelige er iført Uforkrænkelighed, og dette Dødelige er iført Udødelighed, da opfyldes det Ord, som skrevet er: Døden er opslugt formedelst Seier."],[15,55,"Død, hvor er din Braad? Helvede, hvor er din Seier?","Død, hvor er din Braad? Helvede, hvor er din Seier?"],[15,56,"Men Dødens Braad er Synden, og Syndens Kraft er Loven.","Men Dødens Braad er Synden, og Syndens Kraft er Loven."],[15,57,"Men Gud være Tak, som giver os Seier formedelst vor Herre Jesus Christus.","Men Gud være Tak, som giver os Seier formedelst vor Herre Jesus Christus."],[15,58,"Derfor, mine kjære Brødre! bliver faste, ubevægelige, frugtbare altid i Herrens Gjerning, vidende, at Eders Arbeide er ikke forfængeligt i Herren.","Derfor, mine kjære Brødre! bliver faste, ubevægelige, frugtbare altid i Herrens Gjerning, vidende, at Eders Arbeide er ikke forfængeligt i Herren."],[16,1,"Anlangende den Hjælp, som samles til de Hellige, da, ligesom jeg forordnede for Menighederne i Galatia, saaledes gjører og I.","Anlangende den Hjælp, som samles til de Hellige, da, ligesom jeg forordnede for Menighederne i Galatia, saaledes gjører og I."],[16,2,"Paa den første Dag i Ugen lægge Enhver for sig selv Noget tilside og samle, som han har havt Velsignelse til, at Hjælpen ikke skal blive samlet først, naar jeg kommer.","Paa den første Dag i Ugen lægge Enhver for sig selv Noget tilside og samle, som han har havt Velsignelse til, at Hjælpen ikke skal blive samlet først, naar jeg kommer."],[16,3,"Men naar jeg kommer, vil jeg sende dem, hvilke I betroe dertil, med Breve, at føre Eders Gave til Jerusalem.","Men naar jeg kommer, vil jeg sende dem, hvilke I betroe dertil, med Breve, at føre Eders Gave til Jerusalem."],[16,4,"Men dersom det er værd, at ogsaa jeg skal reise derhen, da kunne de reise med mig.","Men dersom det er værd, at ogsaa jeg skal reise derhen, da kunne de reise med mig."],[16,5,"Jeg vil komme til Eder, naar jeg er dragen igjennem Macedonien, (thi jeg drager igjennem Macedonien);","Jeg vil komme til Eder, naar jeg er dragen igjennem Macedonien, (thi jeg drager igjennem Macedonien);"],[16,6,"men hos Eder vil jeg maaskee blive eller endog overvintre, paa det I kunne ledsage mig, hvor jeg saa reiser hen.","men hos Eder vil jeg maaskee blive eller endog overvintre, paa det I kunne ledsage mig, hvor jeg saa reiser hen."],[16,7,"Thi nu vil jeg ikke see Eder som Gjennemreisende, men jeg haaber at forblive nogen Tid hos Eder, om Herren vil tilstede.","Thi nu vil jeg ikke see Eder som Gjennemreisende, men jeg haaber at forblive nogen Tid hos Eder, om Herren vil tilstede."],[16,8,"I Ephesus vil jeg forblive indtil Pintsedag;","I Ephesus vil jeg forblive indtil Pintsedag;"],[16,9,"thi mig er en stor og kraftig Adgang opladen, og der er mange Modstandere.","thi mig er en stor og kraftig Adgang opladen, og der er mange Modstandere."],[16,10,"Men dersom Timotheus kommer, da seer til, at han kan blive hos Eder uden Frygt; thi han gjør Herrens Gjerning, ligesom og jeg.","Men dersom Timotheus kommer, da seer til, at han kan blive hos Eder uden Frygt; thi han gjør Herrens Gjerning, ligesom og jeg."],[16,11,"Derfor skal Ingen foragte ham; men ledsager ham i Fred, at han kan komme til mig; thi jeg forventer ham med Brødrene.","Derfor skal Ingen foragte ham; men ledsager ham i Fred, at han kan komme til mig; thi jeg forventer ham med Brødrene."],[16,12,"Anlangende Apollos, den Broder, da har jeg meget formanet ham, at han skulde komme til Eder med Brødrene; men det var aldeles ikke hans Villie nu at komme, dog vil han komme, naar han faaer beleilig Tid.","Anlangende Apollos, den Broder, da har jeg meget formanet ham, at han skulde komme til Eder med Brødrene; men det var aldeles ikke hans Villie nu at komme, dog vil han komme, naar han faaer beleilig Tid."],[16,13,"Vaager, staaer faste i Troen, værer mandige, værer stærke!","Vaager, staaer faste i Troen, værer mandige, værer stærke!"],[16,14,"Alt skee hos Eder i Kjærlighed!","Alt skee hos Eder i Kjærlighed!"],[16,15,"Men jeg beder Eder, Brødre! I kjende Stephanas’ Huus, at det er Achaias Førstegrøde, og de have hengivet sig selv til at tjene de Hellige:","Men jeg beder Eder, Brødre! I kjende Stephanas’ Huus, at det er Achaias Førstegrøde, og de have hengivet sig selv til at tjene de Hellige:"],[16,16,"saa viser ogsaa I Ærbødighed mod Saadanne og mod Enhver, som hjælper med og arbeider.","saa viser ogsaa I Ærbødighed mod Saadanne og mod Enhver, som hjælper med og arbeider."],[16,17,"Men jeg glæder mig ved Stephanas’ og Fortunatus’ og Achaicus’ Nærværelse; thi Eders Savn have de erstattet.","Men jeg glæder mig ved Stephanas’ og Fortunatus’ og Achaicus’ Nærværelse; thi Eders Savn have de erstattet."],[16,18,"De have vederkvæget min Aand og Eders, skjønner derfor paa Saadanne.","De have vederkvæget min Aand og Eders, skjønner derfor paa Saadanne."],[16,19,"Menighederne i Asia hilse Eder. Aqvilas og Priscilla hilse Eder meget i Herren, med Menigheden i deres Huus.","Menighederne i Asia hilse Eder. Aqvilas og Priscilla hilse Eder meget i Herren, med Menigheden i deres Huus."],[16,20,"Alle Brødrene hilse Eder, Hilser hverandre med et helligt Kys.","Alle Brødrene hilse Eder, Hilser hverandre med et helligt Kys."],[16,21,"Hilsen med min, Paulus’, Haand,","Hilsen med min, Paulus’, Haand,"],[16,22,"Dersom Nogen ikke elsker den Herre Jesus Christus, han være en Forbandelse! Maran Atha.","Dersom Nogen ikke elsker den Herre Jesus Christus, han være en Forbandelse! Maran Atha."],[16,23,"Den Herre Jesu Christi Naade være med Eder!","Den Herre Jesu Christi Naade være med Eder!"],[16,24,"Min Kjærlighed med Eder Alle i Christus Jesus! Amen.","Min Kjærlighed med Eder Alle i Christus Jesus! Amen."]],"epo-londona":[[1,1,"Paŭlo, vokita por esti apostolo de Jesuo Kristo per la volo de Dio, kaj Sostenes, nia frato,","Paŭlo, vokita por esti apostolo de Jesuo Kristo per la volo de Dio, kaj Sostenes, nia frato,"],[1,2,"al tiu eklezio de Dio, kiu estas en Korinto, al tiuj, kiuj estas sanktigitaj en Kristo Jesuo, vokitaj por esti sanktuloj, kune kun ĉiuj, kiuj en ĉiu loko vokas la nomon de nia Sinjoro Jesuo Kristo, ilia Sinjoro kaj nia:","al tiu eklezio de Dio, kiu estas en Korinto, al tiuj, kiuj estas sanktigitaj en Kristo Jesuo, vokitaj por esti sanktuloj, kune kun ĉiuj, kiuj en ĉiu loko vokas la nomon de nia Sinjoro Jesuo Kristo, ilia Sinjoro kaj nia:"],[1,3,"Graco estu al vi kaj paco de Dio, nia Patro, kaj de la Sinjoro Jesuo Kristo.","Graco estu al vi kaj paco de Dio, nia Patro, kaj de la Sinjoro Jesuo Kristo."],[1,4,"Mi ĉiam dankas mian Dion pri vi, pro la graco de Dio al vi donita en Kristo Jesuo;","Mi ĉiam dankas mian Dion pri vi, pro la graco de Dio al vi donita en Kristo Jesuo;"],[1,5,"ke en ĉio vi riĉiĝis en li, en ĉia parolo kaj ĉia scio;","ke en ĉio vi riĉiĝis en li, en ĉia parolo kaj ĉia scio;"],[1,6,"kiel ankaŭ la atesto de Kristo konfirmiĝis en vi;","kiel ankaŭ la atesto de Kristo konfirmiĝis en vi;"],[1,7,"tiel, ke vi malatingas nenian donacon; atendante la malkaŝon de nia Sinjoro Jesuo Kristo,","tiel, ke vi malatingas nenian donacon; atendante la malkaŝon de nia Sinjoro Jesuo Kristo,"],[1,8,"kiu ankaŭ konfirmos vin ĝis la fino, por ke vi estu neriproĉeblaj en la tago de nia Sinjoro Jesuo Kristo.","kiu ankaŭ konfirmos vin ĝis la fino, por ke vi estu neriproĉeblaj en la tago de nia Sinjoro Jesuo Kristo."],[1,9,"Fidela estas Dio, per kiu vi estas alvokitaj en la kunulecon de Lia Filo Jesuo Kristo, nia Sinjoro.","Fidela estas Dio, per kiu vi estas alvokitaj en la kunulecon de Lia Filo Jesuo Kristo, nia Sinjoro."],[1,10,"Mi petegas vin, fratoj, per la nomo de nia Sinjoro Jesuo Kristo, ke vi ĉiuj parolu tion saman, kaj ke estu neniaj skismoj inter vi; sed ke vi estu perfekte kunigitaj en la sama spirito kaj en la sama juĝo.","Mi petegas vin, fratoj, per la nomo de nia Sinjoro Jesuo Kristo, ke vi ĉiuj parolu tion saman, kaj ke estu neniaj skismoj inter vi; sed ke vi estu perfekte kunigitaj en la sama spirito kaj en la sama juĝo."],[1,11,"Ĉar pri vi, miaj fratoj, estas sciigite al mi de la domanoj de Ĥloe, ke ekzistas inter vi malpacoj.","Ĉar pri vi, miaj fratoj, estas sciigite al mi de la domanoj de Ĥloe, ke ekzistas inter vi malpacoj."],[1,12,"Kaj la jenon mi volas diri, ke ĉiu el vi diras: Mi estas de Paŭlo; kaj mi de Apolos; kaj mi de Kefas; kaj mi de Kristo.","Kaj la jenon mi volas diri, ke ĉiu el vi diras: Mi estas de Paŭlo; kaj mi de Apolos; kaj mi de Kefas; kaj mi de Kristo."],[1,13,"Ĉu Kristo estas dividita? ĉu Paŭlo krucumiĝis por vi? aŭ ĉu vi baptiĝis en la nomon de Paŭlo?","Ĉu Kristo estas dividita? ĉu Paŭlo krucumiĝis por vi? aŭ ĉu vi baptiĝis en la nomon de Paŭlo?"],[1,14,"Mi dankas Dion, ke mi baptis neniun el vi krom Krispo kaj Gajo;","Mi dankas Dion, ke mi baptis neniun el vi krom Krispo kaj Gajo;"],[1,15,"por ke neniu diru, ke vi baptiĝis en mian nomon.","por ke neniu diru, ke vi baptiĝis en mian nomon."],[1,16,"Kaj mi baptis ankaŭ la familion de Stefanas; krom tio mi ne scias, ĉu mi baptis iun alian.","Kaj mi baptis ankaŭ la familion de Stefanas; krom tio mi ne scias, ĉu mi baptis iun alian."],[1,17,"Ĉar Kristo sendis min, ne por bapti, sed por prediki la evangelion; ne en saĝeco de vortoj, por ke la kruco de Kristo ne vantiĝu.","Ĉar Kristo sendis min, ne por bapti, sed por prediki la evangelion; ne en saĝeco de vortoj, por ke la kruco de Kristo ne vantiĝu."],[1,18,"Ĉar la priparolo de la kruco estas por la pereantoj malsaĝeco; sed por ni, la savatoj, ĝi estas la potenco de Dio.","Ĉar la priparolo de la kruco estas por la pereantoj malsaĝeco; sed por ni, la savatoj, ĝi estas la potenco de Dio."],[1,19,"Ĉar estas skribite: Mi pereigos la saĝecon de la saĝuloj, Kaj la kompetentecon de la kompetentuloj Mi malaperigos.","Ĉar estas skribite: Mi pereigos la saĝecon de la saĝuloj, Kaj la kompetentecon de la kompetentuloj Mi malaperigos."],[1,20,"Kie estas la saĝulo? kie estas la skribisto? kie estas la diskutisto de ĉi tiu tempaĝo? ĉu Dio ne malsaĝigis la saĝecon de la mondo?","Kie estas la saĝulo? kie estas la skribisto? kie estas la diskutisto de ĉi tiu tempaĝo? ĉu Dio ne malsaĝigis la saĝecon de la mondo?"],[1,21,"Ĉar pro tio, ke en la saĝeco de Dio la mondo per sia saĝeco ne konis Dion, bonvolis Dio per la malsaĝeco de la prediko savi la kredantojn.","Ĉar pro tio, ke en la saĝeco de Dio la mondo per sia saĝeco ne konis Dion, bonvolis Dio per la malsaĝeco de la prediko savi la kredantojn."],[1,22,"Ĉar Judoj postulas signojn, kaj Grekoj serĉas saĝecon;","Ĉar Judoj postulas signojn, kaj Grekoj serĉas saĝecon;"],[1,23,"sed ni predikas Kriston krucumitan, por Judoj falilon, kaj por Grekoj malsaĝon;","sed ni predikas Kriston krucumitan, por Judoj falilon, kaj por Grekoj malsaĝon;"],[1,24,"sed por la vokitoj mem, ĉu Judoj aŭ Grekoj, Kriston la potencon de Dio, kaj la saĝecon de Dio.","sed por la vokitoj mem, ĉu Judoj aŭ Grekoj, Kriston la potencon de Dio, kaj la saĝecon de Dio."],[1,25,"Ĉar la malsaĝeco de Dio estas pli saĝa ol homoj; kaj la malforteco de Dio estas pli forta ol homoj.","Ĉar la malsaĝeco de Dio estas pli saĝa ol homoj; kaj la malforteco de Dio estas pli forta ol homoj."],[1,26,"Ĉar rigardu vian vokon, fratoj, ke ne multaj saĝuloj laŭ la karno, ne multaj potenculoj, ne multaj nobeloj, estas vokataj;","Ĉar rigardu vian vokon, fratoj, ke ne multaj saĝuloj laŭ la karno, ne multaj potenculoj, ne multaj nobeloj, estas vokataj;"],[1,27,"sed Dio elektis la malsaĝajn objektojn de la mondo, por hontigi la saĝulojn; kaj Dio elektis la malfortajn objektojn de la mondo, por hontigi la fortajn;","sed Dio elektis la malsaĝajn objektojn de la mondo, por hontigi la saĝulojn; kaj Dio elektis la malfortajn objektojn de la mondo, por hontigi la fortajn;"],[1,28,"kaj la malnoblajn objektojn de la mondo, kaj la malestimatajn Dio elektis, kaj eĉ la nerealajn, por neniigi la realajn;","kaj la malnoblajn objektojn de la mondo, kaj la malestimatajn Dio elektis, kaj eĉ la nerealajn, por neniigi la realajn;"],[1,29,"por ke neniu karno fieru antaŭ Dio.","por ke neniu karno fieru antaŭ Dio."],[1,30,"Sed el Li vi estas en Kristo Jesuo, kiu fariĝis al ni saĝeco el Dio, kaj justeco kaj sanktigo, kaj elaĉeto;","Sed el Li vi estas en Kristo Jesuo, kiu fariĝis al ni saĝeco el Dio, kaj justeco kaj sanktigo, kaj elaĉeto;"],[1,31,"por ke, kiel estas skribite: Kiu fieras, tiu fieru en la Eternulo.","por ke, kiel estas skribite: Kiu fieras, tiu fieru en la Eternulo."],[2,1,"Kaj mi, fratoj, venante al vi, venis ne kun supereco de parolo aŭ de saĝeco, proklamante al vi la misteron de Dio.","Kaj mi, fratoj, venante al vi, venis ne kun supereco de parolo aŭ de saĝeco, proklamante al vi la misteron de Dio."],[2,2,"Ĉar mi decidis scii ĉe vi nenion, krom Jesuo Kristo kaj tiu krucumita.","Ĉar mi decidis scii ĉe vi nenion, krom Jesuo Kristo kaj tiu krucumita."],[2,3,"Kaj mi estis ĉe vi en malforteco kaj en timo kaj en multa tremado.","Kaj mi estis ĉe vi en malforteco kaj en timo kaj en multa tremado."],[2,4,"Kaj mia parolo kaj mia prediko estis ne en allogaj paroloj de saĝeco, sed en elmontro de la Spirito kaj potenco,","Kaj mia parolo kaj mia prediko estis ne en allogaj paroloj de saĝeco, sed en elmontro de la Spirito kaj potenco,"],[2,5,"por ke via fido estu ne laŭ la saĝeco de homoj, sed laŭ la potenco de Dio.","por ke via fido estu ne laŭ la saĝeco de homoj, sed laŭ la potenco de Dio."],[2,6,"Tamen ni parolas saĝecon inter plenaĝuloj, sed saĝecon ne de ĉi tiu mondo, nek de la regantoj de ĉi tiu mondo, kiuj neniiĝas;","Tamen ni parolas saĝecon inter plenaĝuloj, sed saĝecon ne de ĉi tiu mondo, nek de la regantoj de ĉi tiu mondo, kiuj neniiĝas;"],[2,7,"sed ni parolas la saĝecon de Dio en mistero, la saĝecon kaŝitan, kiun Dio antaŭdestinis antaŭ la mondaĝoj por nia glorado;","sed ni parolas la saĝecon de Dio en mistero, la saĝecon kaŝitan, kiun Dio antaŭdestinis antaŭ la mondaĝoj por nia glorado;"],[2,8,"kaj kiun scias neniu el la regantoj de ĉi tiu mondo; ĉar se ili ĝin scius, ili ne krucumus la Sinjoron de gloro;","kaj kiun scias neniu el la regantoj de ĉi tiu mondo; ĉar se ili ĝin scius, ili ne krucumus la Sinjoron de gloro;"],[2,9,"sed kiel estas skribite: Tion, kion okulo ne vidis kaj orelo ne aŭdis, Kaj kio en la koron de homo ne eniris, Dio preparis por tiuj, kiuj Lin amas.","sed kiel estas skribite: Tion, kion okulo ne vidis kaj orelo ne aŭdis, Kaj kio en la koron de homo ne eniris, Dio preparis por tiuj, kiuj Lin amas."],[2,10,"Sed al ni Dio malkaŝis ilin per la Spirito; ĉar la Spirito esploras ĉion, eĉ la profundaĵojn de Dio.","Sed al ni Dio malkaŝis ilin per la Spirito; ĉar la Spirito esploras ĉion, eĉ la profundaĵojn de Dio."],[2,11,"Ĉar kiu inter homoj scias la aferojn de iu homo, krom la spirito de la homo, kiu estas en li? tiel same la aferojn de Dio scias neniu, krom la Spirito de Dio.","Ĉar kiu inter homoj scias la aferojn de iu homo, krom la spirito de la homo, kiu estas en li? tiel same la aferojn de Dio scias neniu, krom la Spirito de Dio."],[2,12,"Sed ni ricevis ne la spiriton de la mondo, sed la spiriton, kiu estas de Dio; por ke ni sciu tion, al ni donacitan de Dio.","Sed ni ricevis ne la spiriton de la mondo, sed la spiriton, kiu estas de Dio; por ke ni sciu tion, al ni donacitan de Dio."],[2,13,"Pri kio ankaŭ ni parolas per vortoj, ne kiujn instruas homa saĝeco, sed kiujn instruas la Spirito; komparante spiritajn kun spiritaj.","Pri kio ankaŭ ni parolas per vortoj, ne kiujn instruas homa saĝeco, sed kiujn instruas la Spirito; komparante spiritajn kun spiritaj."],[2,14,"Sed la natura homo ne akceptas la aferojn de la Spirito de Dio; ĉar ili estas por li malsaĝeco; kaj li ne povas ilin scii, pro tio, ke ili estas juĝataj spirite.","Sed la natura homo ne akceptas la aferojn de la Spirito de Dio; ĉar ili estas por li malsaĝeco; kaj li ne povas ilin scii, pro tio, ke ili estas juĝataj spirite."],[2,15,"Sed la spirita homo juĝas ĉion, kaj li mem estas juĝata de neniu.","Sed la spirita homo juĝas ĉion, kaj li mem estas juĝata de neniu."],[2,16,"Ĉar kiu sciis la menson de la Eternulo, ke li instruu Lin? Sed ni havas la menson de Kristo.","Ĉar kiu sciis la menson de la Eternulo, ke li instruu Lin? Sed ni havas la menson de Kristo."],[3,1,"Kaj mi, fratoj, ne povis paroli al vi kiel al spirituloj, sed kiel al karnuloj, kiel al infanetoj en Kristo.","Kaj mi, fratoj, ne povis paroli al vi kiel al spirituloj, sed kiel al karnuloj, kiel al infanetoj en Kristo."],[3,2,"Mi nutris vin per lakto, ne per manĝaĵoj; ĉar vi ankoraŭ tion ne kapablis; kaj eĉ nun vi ne kapablas;","Mi nutris vin per lakto, ne per manĝaĵoj; ĉar vi ankoraŭ tion ne kapablis; kaj eĉ nun vi ne kapablas;"],[3,3,"ĉar vi estas ankoraŭ karnaj; ĉar dum ekzistas inter vi ĵaluzo kaj malpaco, ĉu vi ne estas karnaj kaj iradas laŭ la maniero de homoj?","ĉar vi estas ankoraŭ karnaj; ĉar dum ekzistas inter vi ĵaluzo kaj malpaco, ĉu vi ne estas karnaj kaj iradas laŭ la maniero de homoj?"],[3,4,"Ĉar kiam unu diras: Mi estas de Paŭlo; kaj alia: Mi estas de Apolos; ĉu vi ne estas homoj?","Ĉar kiam unu diras: Mi estas de Paŭlo; kaj alia: Mi estas de Apolos; ĉu vi ne estas homoj?"],[3,5,"Kio do estas Apolos? kaj kio estas Paŭlo? Servantoj, per kiuj vi ekkredis; kaj ĉiu, kiel la Sinjoro al li donis.","Kio do estas Apolos? kaj kio estas Paŭlo? Servantoj, per kiuj vi ekkredis; kaj ĉiu, kiel la Sinjoro al li donis."],[3,6,"Mi plantis, Apolos akvumis; sed Dio kreskigis.","Mi plantis, Apolos akvumis; sed Dio kreskigis."],[3,7,"Tial nek la plantanto estas io, nek la akvumanto; sed Dio, la kreskiganto.","Tial nek la plantanto estas io, nek la akvumanto; sed Dio, la kreskiganto."],[3,8,"Sed la plantanto kaj la akvumanto estas unu; sed ĉiu ricevos sian propran rekompencon laŭ sia laboro.","Sed la plantanto kaj la akvumanto estas unu; sed ĉiu ricevos sian propran rekompencon laŭ sia laboro."],[3,9,"Ĉar ni estas kunlaborantoj kun Dio: vi estas la kultivotaĵo de Dio, la konstruotaĵo de Dio.","Ĉar ni estas kunlaborantoj kun Dio: vi estas la kultivotaĵo de Dio, la konstruotaĵo de Dio."],[3,10,"Laŭ la graco de Dio al mi donita, kiel saĝa majstromasonisto mi metis fundamenton; kaj aliaj surkonstruas. Sed ĉiu zorgu, kiel li surkonstruas.","Laŭ la graco de Dio al mi donita, kiel saĝa majstromasonisto mi metis fundamenton; kaj aliaj surkonstruas. Sed ĉiu zorgu, kiel li surkonstruas."],[3,11,"Ĉar neniu povas meti alian fundamenton krom tiu, kiu estas metita, tio estas Jesuo Kristo.","Ĉar neniu povas meti alian fundamenton krom tiu, kiu estas metita, tio estas Jesuo Kristo."],[3,12,"Sed se iu konstruas sur la fundamento oron, arĝenton, multekostajn ŝtonojn, lignon, fojnon, pajlon,","Sed se iu konstruas sur la fundamento oron, arĝenton, multekostajn ŝtonojn, lignon, fojnon, pajlon,"],[3,13,"ĉies laboraĵo evidentiĝos; ĉar la tago ĝin montros, pro tio, ke ĝi estas malkaŝita en fajro; kaj la fajro mem provos ĉies laboraĵon, kia ĝi estas.","ĉies laboraĵo evidentiĝos; ĉar la tago ĝin montros, pro tio, ke ĝi estas malkaŝita en fajro; kaj la fajro mem provos ĉies laboraĵon, kia ĝi estas."],[3,14,"Se restos ies laboraĵo, kiun li surkonstruis, li ricevos rekompencon.","Se restos ies laboraĵo, kiun li surkonstruis, li ricevos rekompencon."],[3,15,"Se ies laboraĵo forbrulos, li suferos perdon; sed li mem saviĝos; tamen kiel tra fajro.","Se ies laboraĵo forbrulos, li suferos perdon; sed li mem saviĝos; tamen kiel tra fajro."],[3,16,"Ĉu vi ne scias, ke vi estas templo de Dio kaj ke en vi loĝas la Spirito de Dio?","Ĉu vi ne scias, ke vi estas templo de Dio kaj ke en vi loĝas la Spirito de Dio?"],[3,17,"Se iu detruas la templon de Dio, tiun detruos Dio; ĉar la templo de Dio estas sankta, kaj vi estas tio.","Se iu detruas la templon de Dio, tiun detruos Dio; ĉar la templo de Dio estas sankta, kaj vi estas tio."],[3,18,"Neniu sin trompu. Se iu el vi opinias sin saĝa en ĉi tiu mondo, li fariĝu malsaĝulo, por ke li saĝiĝu.","Neniu sin trompu. Se iu el vi opinias sin saĝa en ĉi tiu mondo, li fariĝu malsaĝulo, por ke li saĝiĝu."],[3,19,"Ĉar la saĝeco de ĉi tiu mondo estas malsaĝeco ĉe Dio. Ĉar estas skribite: Li kaptas la saĝulojn per ilia ruzaĵo;","Ĉar la saĝeco de ĉi tiu mondo estas malsaĝeco ĉe Dio. Ĉar estas skribite: Li kaptas la saĝulojn per ilia ruzaĵo;"],[3,20,"kaj ankaŭ: La Eternulo scias la pensojn de saĝuloj, ke ili estas vantaj.","kaj ankaŭ: La Eternulo scias la pensojn de saĝuloj, ke ili estas vantaj."],[3,21,"Tial neniu fanfaronu pri homoj. Ĉar ĉio apartenas al vi,","Tial neniu fanfaronu pri homoj. Ĉar ĉio apartenas al vi,"],[3,22,"ĉu Paŭlo, aŭ Apolos, aŭ Kefas, aŭ la mondo, aŭ la vivo, aŭ la morto, aŭ estantaĵoj aŭ estontaĵoj: ĉio apartenas al vi,","ĉu Paŭlo, aŭ Apolos, aŭ Kefas, aŭ la mondo, aŭ la vivo, aŭ la morto, aŭ estantaĵoj aŭ estontaĵoj: ĉio apartenas al vi,"],[3,23,"kaj vi al Kristo, kaj Kristo al Dio.","kaj vi al Kristo, kaj Kristo al Dio."],[4,1,"Tiel oni rigardu nin, kiel servantojn de Kristo kaj administrantojn de la misteroj de Dio.","Tiel oni rigardu nin, kiel servantojn de Kristo kaj administrantojn de la misteroj de Dio."],[4,2,"Cetere, ĉi tie estas postulate ĉe administrantoj, ke oni troviĝu fidela.","Cetere, ĉi tie estas postulate ĉe administrantoj, ke oni troviĝu fidela."],[4,3,"Sed ĉe mi estas tre malgrava afero esti juĝata de vi, aŭ per homa juĝo: mi ja ne juĝas min mem.","Sed ĉe mi estas tre malgrava afero esti juĝata de vi, aŭ per homa juĝo: mi ja ne juĝas min mem."],[4,4,"Ĉar mi scias nenion kontraŭ mi; tamen mi ne estas pro tio pravigita; sed tiu, kiu juĝas min, estas la Sinjoro.","Ĉar mi scias nenion kontraŭ mi; tamen mi ne estas pro tio pravigita; sed tiu, kiu juĝas min, estas la Sinjoro."],[4,5,"Tial juĝu nenion antaŭ la tempo, ĝis venos la Sinjoro, kiu enlumigos la kaŝitaĵojn de la mallumo kaj klarigos la intencojn de la koroj; kaj tiam ĉiu ricevos de Dio sian propran laŭdon.","Tial juĝu nenion antaŭ la tempo, ĝis venos la Sinjoro, kiu enlumigos la kaŝitaĵojn de la mallumo kaj klarigos la intencojn de la koroj; kaj tiam ĉiu ricevos de Dio sian propran laŭdon."],[4,6,"Tion do, fratoj, mi alifigure rilatigis al mi kaj Apolos pro vi; por ke vi en ni lernu ne preterpasi la skribitaĵojn; por ke neniu el vi bloveŝvelu por unu kontraŭ la alia.","Tion do, fratoj, mi alifigure rilatigis al mi kaj Apolos pro vi; por ke vi en ni lernu ne preterpasi la skribitaĵojn; por ke neniu el vi bloveŝvelu por unu kontraŭ la alia."],[4,7,"Ĉar kiu vin diferencigas? kaj kion vi havas, kion vi ne ricevis? sed se vi ĝin ricevis, kial vi fanfaronas, kvazaŭ vi ĝin ne ricevus?","Ĉar kiu vin diferencigas? kaj kion vi havas, kion vi ne ricevis? sed se vi ĝin ricevis, kial vi fanfaronas, kvazaŭ vi ĝin ne ricevus?"],[4,8,"Jam vi estas plenigitaj, jam vi riĉiĝis, vi reĝis sen ni; kaj mi ja volus, ke vi efektive reĝu, por ke ni ankaŭ reĝu kun vi.","Jam vi estas plenigitaj, jam vi riĉiĝis, vi reĝis sen ni; kaj mi ja volus, ke vi efektive reĝu, por ke ni ankaŭ reĝu kun vi."],[4,9,"Ĉar ŝajnas al mi, ke Dio elmetis nin, la apostolojn, la plej lastajn, kiel mortkondamnitajn; ĉar ni fariĝis spektaklo al la mondo kaj al anĝeloj kaj al homoj.","Ĉar ŝajnas al mi, ke Dio elmetis nin, la apostolojn, la plej lastajn, kiel mortkondamnitajn; ĉar ni fariĝis spektaklo al la mondo kaj al anĝeloj kaj al homoj."],[4,10,"Ni estas malsaĝuloj pro Kristo, sed vi estas saĝaj en Kristo; ni estas malfortaj, sed vi estas fortaj; vi estas gloraj, sed ni estas senhonoraj.","Ni estas malsaĝuloj pro Kristo, sed vi estas saĝaj en Kristo; ni estas malfortaj, sed vi estas fortaj; vi estas gloraj, sed ni estas senhonoraj."],[4,11,"Eĉ ĝis la nuna horo ni malsatas kaj soifas, kaj ni estas nudaj, kaj ni estas batataj kaj senhejmaj;","Eĉ ĝis la nuna horo ni malsatas kaj soifas, kaj ni estas nudaj, kaj ni estas batataj kaj senhejmaj;"],[4,12,"kaj ni penadas, laborante per niaj propraj manoj; insultate, ni benas; persekutate, ni eltenas;","kaj ni penadas, laborante per niaj propraj manoj; insultate, ni benas; persekutate, ni eltenas;"],[4,13,"kalumniate, ni petegas; ni fariĝas kiel la balaaĵo de la mondo, la forĵetaĵo de ĉio, eĉ ĝis nun.","kalumniate, ni petegas; ni fariĝas kiel la balaaĵo de la mondo, la forĵetaĵo de ĉio, eĉ ĝis nun."],[4,14,"Ne por hontigi vin mi tion skribas, sed, kiel miajn amatajn filojn, por admoni vin.","Ne por hontigi vin mi tion skribas, sed, kiel miajn amatajn filojn, por admoni vin."],[4,15,"Ĉar kvankam vi eĉ havus dek mil pedagogojn en Kristo, tamen vi havas ne multajn patrojn; ĉar en Kristo Jesuo mi naskigis vin per la evangelio.","Ĉar kvankam vi eĉ havus dek mil pedagogojn en Kristo, tamen vi havas ne multajn patrojn; ĉar en Kristo Jesuo mi naskigis vin per la evangelio."],[4,16,"Mi do petegas vin, estu imitantoj de mi.","Mi do petegas vin, estu imitantoj de mi."],[4,17,"Pro tio mi sendis al vi Timoteon, kiu estas mia amata kaj fidela filo en la Sinjoro, kaj kiu vin memorigos pri miaj vojoj en Kristo, ĝuste kiel mi instruas ĉie en ĉiu eklezio.","Pro tio mi sendis al vi Timoteon, kiu estas mia amata kaj fidela filo en la Sinjoro, kaj kiu vin memorigos pri miaj vojoj en Kristo, ĝuste kiel mi instruas ĉie en ĉiu eklezio."],[4,18,"Kelkaj bloveŝvelas, kvazaŭ mi ne venus al vi.","Kelkaj bloveŝvelas, kvazaŭ mi ne venus al vi."],[4,19,"Sed mi venos al vi baldaŭ, se la Sinjoro tion volos; kaj mi ekscios, ne la parolon de la bloveŝvelintoj, sed la potencon.","Sed mi venos al vi baldaŭ, se la Sinjoro tion volos; kaj mi ekscios, ne la parolon de la bloveŝvelintoj, sed la potencon."],[4,20,"Ĉar la regno de Dio estas ne en parolo, sed en potenco.","Ĉar la regno de Dio estas ne en parolo, sed en potenco."],[4,21,"Kion vi volas? ĉu kun vergo mi venu al vi, aŭ en amo kaj en spirito de humileco?","Kion vi volas? ĉu kun vergo mi venu al vi, aŭ en amo kaj en spirito de humileco?"],[5,1,"Efektive oni raportas, ke estas ĉe vi malĉasteco, kaj tia malĉasteco, kia ne ekzistas eĉ inter la nacianoj, ke iu havas la edzinon de sia patro.","Efektive oni raportas, ke estas ĉe vi malĉasteco, kaj tia malĉasteco, kia ne ekzistas eĉ inter la nacianoj, ke iu havas la edzinon de sia patro."],[5,2,"Kaj vi bloveŝvelis, kaj ne prefere ploregis, por ke tiu, kiu faris tion, foriĝu el inter vi.","Kaj vi bloveŝvelis, kaj ne prefere ploregis, por ke tiu, kiu faris tion, foriĝu el inter vi."],[5,3,"Ĉar mi vere, korpe forestante, sed spirite ĉeestante, jam juĝis, kvazaŭ ĉeestante, tiun, kiu tiel faris tion,","Ĉar mi vere, korpe forestante, sed spirite ĉeestante, jam juĝis, kvazaŭ ĉeestante, tiun, kiu tiel faris tion,"],[5,4,"en la nomo de nia Sinjoro Jesuo Kristo, en kunveno de vi kaj de mia spirito kun la potenco de nia Sinjoro Jesuo,","en la nomo de nia Sinjoro Jesuo Kristo, en kunveno de vi kaj de mia spirito kun la potenco de nia Sinjoro Jesuo,"],[5,5,"transdoni tian homon al Satano por la detruo de la karno, por ke la spirito saviĝu en la tago de la Sinjoro Jesuo.","transdoni tian homon al Satano por la detruo de la karno, por ke la spirito saviĝu en la tago de la Sinjoro Jesuo."],[5,6,"Ne bona estas via fanfaronado. Ĉu vi ne scias, ke malmulto da fermentaĵo fermentigas la tutan mason?","Ne bona estas via fanfaronado. Ĉu vi ne scias, ke malmulto da fermentaĵo fermentigas la tutan mason?"],[5,7,"Forpurigu la malnovan fermentaĵon, por ke vi estu nova maso, kiel vi estas nefermentintaj. Ĉar por ni ankaŭ Pasko estas oferita, nome Kristo;","Forpurigu la malnovan fermentaĵon, por ke vi estu nova maso, kiel vi estas nefermentintaj. Ĉar por ni ankaŭ Pasko estas oferita, nome Kristo;"],[5,8,"tial ni festu, ne per malnova fermentaĵo, nek per fermentaĵo de malico kaj malboneco, sed per la senfermenta pano de sincereco kaj vereco.","tial ni festu, ne per malnova fermentaĵo, nek per fermentaĵo de malico kaj malboneco, sed per la senfermenta pano de sincereco kaj vereco."],[5,9,"En mia epistolo mi skribis al vi, ke vi ne intermiksu vin kun malĉastuloj;","En mia epistolo mi skribis al vi, ke vi ne intermiksu vin kun malĉastuloj;"],[5,10,"ne tute kun la malĉastuloj de ĉi tiu mondo, aŭ kun la aviduloj kaj rabemuloj, aŭ kun idolanoj; ĉar tiuokaze estus necese, ke vi eliru el la mondo;","ne tute kun la malĉastuloj de ĉi tiu mondo, aŭ kun la aviduloj kaj rabemuloj, aŭ kun idolanoj; ĉar tiuokaze estus necese, ke vi eliru el la mondo;"],[5,11,"sed nun mi skribas al vi, ke vi ne intermiksu vin, se iu, nomata frato, eble estas malĉastulo, aŭ avidulo, aŭ idolano, aŭ insultanto, aŭ drinkulo, aŭ rabemulo; kun tia homo eĉ ne kunmanĝu.","sed nun mi skribas al vi, ke vi ne intermiksu vin, se iu, nomata frato, eble estas malĉastulo, aŭ avidulo, aŭ idolano, aŭ insultanto, aŭ drinkulo, aŭ rabemulo; kun tia homo eĉ ne kunmanĝu."],[5,12,"Ĉar kiel koncernas min juĝi la eksterulojn? Ĉu vi ne juĝas la internulojn,","Ĉar kiel koncernas min juĝi la eksterulojn? Ĉu vi ne juĝas la internulojn,"],[5,13,"dum la eksterulojn juĝas Dio? Forigu el inter vi la malvirtulon.","dum la eksterulojn juĝas Dio? Forigu el inter vi la malvirtulon."],[6,1,"Ĉu iu el vi, havante aferon kontraŭ sia proksimulo, kuraĝas procesi antaŭ la malpiuloj, kaj ne antaŭ la sanktuloj?","Ĉu iu el vi, havante aferon kontraŭ sia proksimulo, kuraĝas procesi antaŭ la malpiuloj, kaj ne antaŭ la sanktuloj?"],[6,2,"Aŭ ĉu vi ne scias, ke la sanktuloj juĝos la mondon? kaj se la mondon vi juĝos, ĉu vi ne estas indaj juĝi la plej malgrandajn aferojn?","Aŭ ĉu vi ne scias, ke la sanktuloj juĝos la mondon? kaj se la mondon vi juĝos, ĉu vi ne estas indaj juĝi la plej malgrandajn aferojn?"],[6,3,"Ĉu vi ne scias, ke ni juĝos anĝelojn? kiom pli do aferojn de la nuna vivo?","Ĉu vi ne scias, ke ni juĝos anĝelojn? kiom pli do aferojn de la nuna vivo?"],[6,4,"Se do vi devas starigi tribunalon pri la aferoj de la nuna vivo, ĉu vi faras juĝantoj tiujn, kiuj estas negravaj en la eklezio?","Se do vi devas starigi tribunalon pri la aferoj de la nuna vivo, ĉu vi faras juĝantoj tiujn, kiuj estas negravaj en la eklezio?"],[6,5,"Mi diras tion, por vin hontigi. Ĉu efektive ne ekzistas ĉe vi eĉ unu saĝulo, kiu povus decidi inter siaj fratoj,","Mi diras tion, por vin hontigi. Ĉu efektive ne ekzistas ĉe vi eĉ unu saĝulo, kiu povus decidi inter siaj fratoj,"],[6,6,"sed frato procesas kontraŭ frato, kaj eĉ antaŭ nekredantoj?","sed frato procesas kontraŭ frato, kaj eĉ antaŭ nekredantoj?"],[6,7,"Certe jam estas ĉe vi granda domaĝo, ke vi faras procesojn unu kontraŭ alia. Kial vi ne prefere suferas maljustecon? kial vi ne prefere suferas rabadon?","Certe jam estas ĉe vi granda domaĝo, ke vi faras procesojn unu kontraŭ alia. Kial vi ne prefere suferas maljustecon? kial vi ne prefere suferas rabadon?"],[6,8,"Tamen eĉ vi mem faras maljustecon kaj rabadon, kaj eĉ kontraŭ la fratoj.","Tamen eĉ vi mem faras maljustecon kaj rabadon, kaj eĉ kontraŭ la fratoj."],[6,9,"Aŭ ĉu vi ne scias, ke la maljustuloj ne heredos la regnon de Dio? Ne trompiĝu: nek malĉastuloj, nek idolanoj, nek adultuloj, nek molmoruloj, nek viruzaĉantoj,","Aŭ ĉu vi ne scias, ke la maljustuloj ne heredos la regnon de Dio? Ne trompiĝu: nek malĉastuloj, nek idolanoj, nek adultuloj, nek molmoruloj, nek viruzaĉantoj,"],[6,10,"nek ŝtelistoj, nek aviduloj, nek drinkuloj, nek insultantoj, nek rabemuloj, heredos la regnon de Dio.","nek ŝtelistoj, nek aviduloj, nek drinkuloj, nek insultantoj, nek rabemuloj, heredos la regnon de Dio."],[6,11,"Kaj tiaj estis kelkaj el vi; sed vi laviĝis, sed vi sanktiĝis, sed vi justiĝis en la nomo de la Sinjoro Jesuo Kristo kaj en la Spirito de nia Dio.","Kaj tiaj estis kelkaj el vi; sed vi laviĝis, sed vi sanktiĝis, sed vi justiĝis en la nomo de la Sinjoro Jesuo Kristo kaj en la Spirito de nia Dio."],[6,12,"Ĉio estas por mi permesata, sed ne ĉio estas oportuna. Ĉio estas por mi permesata; sed mi ne volas sub io submetiĝi.","Ĉio estas por mi permesata, sed ne ĉio estas oportuna. Ĉio estas por mi permesata; sed mi ne volas sub io submetiĝi."],[6,13,"Manĝaĵoj por la ventro, kaj la ventro por manĝaĵoj; sed Dio neniigos kune ĝin kaj ilin. Sed la korpo estas ne por malĉasteco, sed por la Sinjoro; kaj la Sinjoro por la korpo;","Manĝaĵoj por la ventro, kaj la ventro por manĝaĵoj; sed Dio neniigos kune ĝin kaj ilin. Sed la korpo estas ne por malĉasteco, sed por la Sinjoro; kaj la Sinjoro por la korpo;"],[6,14,"kaj Dio levis la Sinjoron, kaj levos ankaŭ nin per Sia potenco.","kaj Dio levis la Sinjoron, kaj levos ankaŭ nin per Sia potenco."],[6,15,"Ĉu vi ne scias, ke viaj korpoj estas membroj de Kristo? ĉu mi do prenos la membrojn de Kristo, kaj faros ilin membroj de malĉastistino? Nepre ne!","Ĉu vi ne scias, ke viaj korpoj estas membroj de Kristo? ĉu mi do prenos la membrojn de Kristo, kaj faros ilin membroj de malĉastistino? Nepre ne!"],[6,16,"Aŭ ĉu vi ne scias, ke tiu, kiu kuniĝas kun malĉastistino, estas kun ŝi unu korpo? ĉar: Ili, Li diris, estos unu karno.","Aŭ ĉu vi ne scias, ke tiu, kiu kuniĝas kun malĉastistino, estas kun ŝi unu korpo? ĉar: Ili, Li diris, estos unu karno."],[6,17,"Sed tiu, kiu kuniĝas kun la Sinjoro, estas kun li unu spirito.","Sed tiu, kiu kuniĝas kun la Sinjoro, estas kun li unu spirito."],[6,18,"Forkuru de malĉasteco. Ĉiu peko, kiun homo faras, estas ekster la korpo; sed tiu, kiu malĉastas, pekas kontraŭ sia propra korpo.","Forkuru de malĉasteco. Ĉiu peko, kiun homo faras, estas ekster la korpo; sed tiu, kiu malĉastas, pekas kontraŭ sia propra korpo."],[6,19,"Aŭ ĉu vi ne scias, ke via korpo estas templo de la Sankta Spirito, kiu estas en vi kaj kiun vi havas de Dio? kaj vi ne apartenas al vi mem,","Aŭ ĉu vi ne scias, ke via korpo estas templo de la Sankta Spirito, kiu estas en vi kaj kiun vi havas de Dio? kaj vi ne apartenas al vi mem,"],[6,20,"ĉar vi estas aĉetitaj per prezo; gloru do Dion en via korpo.","ĉar vi estas aĉetitaj per prezo; gloru do Dion en via korpo."],[7,1,"Nun rilate al la aferoj, pri kiuj vi skribis: Estas bone por viro, ne tuŝi virinon.","Nun rilate al la aferoj, pri kiuj vi skribis: Estas bone por viro, ne tuŝi virinon."],[7,2,"Sed pro malĉastaĵoj ĉiu viro havu propran edzinon, kaj ĉiu virino havu propran edzon.","Sed pro malĉastaĵoj ĉiu viro havu propran edzinon, kaj ĉiu virino havu propran edzon."],[7,3,"La edzo donu al la edzino ŝian rajtaĵon; tiel same ankaŭ la edzino al la edzo.","La edzo donu al la edzino ŝian rajtaĵon; tiel same ankaŭ la edzino al la edzo."],[7,4,"Ne la edzino, sed la edzo rajtas pri ŝia korpo; tiel same ankaŭ ne la edzo, sed la edzino rajtas pri lia korpo.","Ne la edzino, sed la edzo rajtas pri ŝia korpo; tiel same ankaŭ ne la edzo, sed la edzino rajtas pri lia korpo."],[7,5,"Ne senigu unu la alian, krom eble kun konsento por kelka tempo, por ke vi dediĉu vin al preĝado, kaj kuniĝu denove, por ke Satano vin ne tentu pro manko de sinregado.","Ne senigu unu la alian, krom eble kun konsento por kelka tempo, por ke vi dediĉu vin al preĝado, kaj kuniĝu denove, por ke Satano vin ne tentu pro manko de sinregado."],[7,6,"Sed tion mi diras kiel permeson, ne kiel ordonon.","Sed tion mi diras kiel permeson, ne kiel ordonon."],[7,7,"Sed mi volus, ke ĉiuj homoj estu kiel mi mem. Tamen ĉiu havas sian propran donacon de Dio, unu tiel, alia alie.","Sed mi volus, ke ĉiuj homoj estu kiel mi mem. Tamen ĉiu havas sian propran donacon de Dio, unu tiel, alia alie."],[7,8,"Sed mi diras al senedzinuloj kaj al vidvinoj: Estas bone por ili resti kiel mi.","Sed mi diras al senedzinuloj kaj al vidvinoj: Estas bone por ili resti kiel mi."],[7,9,"Sed se ili ne povas sin deteni, ili edziĝu; ĉar estas pli bone edziĝi, ol bruladi.","Sed se ili ne povas sin deteni, ili edziĝu; ĉar estas pli bone edziĝi, ol bruladi."],[7,10,"Sed al geedzoj mi ordonas (tamen ne mi, sed la Sinjoro): Ke edzino ne foriĝu de sia edzo","Sed al geedzoj mi ordonas (tamen ne mi, sed la Sinjoro): Ke edzino ne foriĝu de sia edzo"],[7,11,"(tamen, se ŝi foriĝas, ŝi restu senedza, aŭ denove konsentiĝu kun sia edzo); kaj ke la edzo ne forsendu sian edzinon.","(tamen, se ŝi foriĝas, ŝi restu senedza, aŭ denove konsentiĝu kun sia edzo); kaj ke la edzo ne forsendu sian edzinon."],[7,12,"Sed al la ceteraj diras mi, ne la Sinjoro: Se iu frato havas nekredantan edzinon, kaj ŝi konsentas loĝadi kun li, li ne forigu ŝin.","Sed al la ceteraj diras mi, ne la Sinjoro: Se iu frato havas nekredantan edzinon, kaj ŝi konsentas loĝadi kun li, li ne forigu ŝin."],[7,13,"Kaj se virino havas nekredantan edzon, kaj li konsentas loĝadi kun ŝi, ŝi ne forlasu sian edzon.","Kaj se virino havas nekredantan edzon, kaj li konsentas loĝadi kun ŝi, ŝi ne forlasu sian edzon."],[7,14,"Ĉar la nekredanta edzo estas sanktigita per la edzino, kaj la nekredanta edzino estas sanktigita per la frato; alie viaj infanoj estus profanaj, sed nun ili estas sanktaj.","Ĉar la nekredanta edzo estas sanktigita per la edzino, kaj la nekredanta edzino estas sanktigita per la frato; alie viaj infanoj estus profanaj, sed nun ili estas sanktaj."],[7,15,"Tamen se la nekredanto volas foriri, li foriru: la frato aŭ la fratino en tiaj okazoj ne estas sklavigita; sed Dio vokis nin en paco.","Tamen se la nekredanto volas foriri, li foriru: la frato aŭ la fratino en tiaj okazoj ne estas sklavigita; sed Dio vokis nin en paco."],[7,16,"Ĉar kiel vi scias, ho edzino, ĉu vi savos vian edzon? aŭ kiel vi scias, ho edzo, ĉu vi savos vian edzinon?","Ĉar kiel vi scias, ho edzino, ĉu vi savos vian edzon? aŭ kiel vi scias, ho edzo, ĉu vi savos vian edzinon?"],[7,17,"Sed kiel la Sinjoro disdonis al ĉiu, kiel Dio ĉiun vokis, tiel li iru. Kaj tiel mi ordonas en ĉiuj eklezioj.","Sed kiel la Sinjoro disdonis al ĉiu, kiel Dio ĉiun vokis, tiel li iru. Kaj tiel mi ordonas en ĉiuj eklezioj."],[7,18,"Ĉu iu estas vokita, cirkumcidite? li ne fariĝu necirkumcidita. Ĉu iu estas vokita, necirkumcidite? li ne cirkumcidiĝu.","Ĉu iu estas vokita, cirkumcidite? li ne fariĝu necirkumcidita. Ĉu iu estas vokita, necirkumcidite? li ne cirkumcidiĝu."],[7,19,"Cirkumcido estas nenio, kaj necirkumcido estas nenio; sed la plenumado de la ordonoj de Dio.","Cirkumcido estas nenio, kaj necirkumcido estas nenio; sed la plenumado de la ordonoj de Dio."],[7,20,"Ĉiu restadu en tiu voksorto, en kiu li estas vokita.","Ĉiu restadu en tiu voksorto, en kiu li estas vokita."],[7,21,"Ĉu vi estas vokita, estante sklavo? ne ĉagreniĝu pro tio; sed se vi povas liberiĝi, tion uzu prefere.","Ĉu vi estas vokita, estante sklavo? ne ĉagreniĝu pro tio; sed se vi povas liberiĝi, tion uzu prefere."],[7,22,"Ĉar kiu estas vokita en la Sinjoro, estante sklavo, tiu estas liberulo de la Sinjoro; tiel same tiu, kiu estas vokita, estante libera, estas sklavo de Kristo.","Ĉar kiu estas vokita en la Sinjoro, estante sklavo, tiu estas liberulo de la Sinjoro; tiel same tiu, kiu estas vokita, estante libera, estas sklavo de Kristo."],[7,23,"Vi estas aĉetitaj per prezo; ne fariĝu sklavoj de homoj.","Vi estas aĉetitaj per prezo; ne fariĝu sklavoj de homoj."],[7,24,"Fratoj, ĉiu, kie li estas vokita, tie restadu kun Dio.","Fratoj, ĉiu, kie li estas vokita, tie restadu kun Dio."],[7,25,"Sed rilate al virgulinoj, mi ne havas ordonon de la Sinjoro; sed mi donas mian opinion, kiel ricevinta de la Sinjoro indulgon, por esti fidela.","Sed rilate al virgulinoj, mi ne havas ordonon de la Sinjoro; sed mi donas mian opinion, kiel ricevinta de la Sinjoro indulgon, por esti fidela."],[7,26,"Mi opinias do, ke la jeno estas bona pro la nuna neceseco, nome, ke estas bone por viro samstate resti.","Mi opinias do, ke la jeno estas bona pro la nuna neceseco, nome, ke estas bone por viro samstate resti."],[7,27,"Ĉu vi estas ligita kun edzino? ne serĉu malligon. Ĉu vi estas malligita je edzino? ne serĉu edzinon.","Ĉu vi estas ligita kun edzino? ne serĉu malligon. Ĉu vi estas malligita je edzino? ne serĉu edzinon."],[7,28,"Sed se vi edziĝas, vi ne pekas; kaj se virgulino edziniĝas, ŝi ne pekas. Sed tiaj personoj havos maltrankvilon en la karno; kaj mi volas indulgi vin.","Sed se vi edziĝas, vi ne pekas; kaj se virgulino edziniĝas, ŝi ne pekas. Sed tiaj personoj havos maltrankvilon en la karno; kaj mi volas indulgi vin."],[7,29,"Sed la jenon mi diras, fratoj: La tempo estas mallongigita, por ke de nun tiuj, kiuj havas edzinojn, estu kvazaŭ ili ne havus;","Sed la jenon mi diras, fratoj: La tempo estas mallongigita, por ke de nun tiuj, kiuj havas edzinojn, estu kvazaŭ ili ne havus;"],[7,30,"kaj la plorantoj, kvazaŭ ne plorantaj; kaj la ĝojantoj, kvazaŭ ne ĝojantaj; kaj la aĉetantoj, kvazaŭ ne posedantaj;","kaj la plorantoj, kvazaŭ ne plorantaj; kaj la ĝojantoj, kvazaŭ ne ĝojantaj; kaj la aĉetantoj, kvazaŭ ne posedantaj;"],[7,31,"kaj tiuj, kiuj uzas la mondon, kvazaŭ ne trouzantaj ĝin; ĉar la formo de ĉi tiu mondo forpasas.","kaj tiuj, kiuj uzas la mondon, kvazaŭ ne trouzantaj ĝin; ĉar la formo de ĉi tiu mondo forpasas."],[7,32,"Sed mi volas, ke vi estu sen zorgoj. La needziĝinto prizorgas la aferojn de la Sinjoro, kiamaniere li povos plaĉi al la Sinjoro;","Sed mi volas, ke vi estu sen zorgoj. La needziĝinto prizorgas la aferojn de la Sinjoro, kiamaniere li povos plaĉi al la Sinjoro;"],[7,33,"sed la edziĝinto prizorgas la aferojn de la mondo, kiamaniere li povos plaĉi al sia edzino.","sed la edziĝinto prizorgas la aferojn de la mondo, kiamaniere li povos plaĉi al sia edzino."],[7,34,"Kaj estas diferenco ankaŭ inter edzino kaj virgulino. La needziniĝinto prizorgas la aferojn de la Sinjoro, por ke ŝi estu sankta korpe kaj spirite; sed la edziniĝinto prizorgas la aferojn de la mondo, kiamaniere ŝi povos plaĉi al sia edzo.","Kaj estas diferenco ankaŭ inter edzino kaj virgulino. La needziniĝinto prizorgas la aferojn de la Sinjoro, por ke ŝi estu sankta korpe kaj spirite; sed la edziniĝinto prizorgas la aferojn de la mondo, kiamaniere ŝi povos plaĉi al sia edzo."],[7,35,"Kaj tion mi diras por via propra utilo; ne por ĵeti kaptilon sur vin, sed pro konveneco, kaj por ke vi atentu la Sinjoron nedistrite.","Kaj tion mi diras por via propra utilo; ne por ĵeti kaptilon sur vin, sed pro konveneco, kaj por ke vi atentu la Sinjoron nedistrite."],[7,36,"Sed se iu opinias, ke li kondutas nedece kontraŭ sia virgulino, se ŝi preteriras sian aĝfloradon, kaj se tio estas necesa, li faru tion, kion li volas; li ne pekas; ili geedziĝu.","Sed se iu opinias, ke li kondutas nedece kontraŭ sia virgulino, se ŝi preteriras sian aĝfloradon, kaj se tio estas necesa, li faru tion, kion li volas; li ne pekas; ili geedziĝu."],[7,37,"Sed tiu, kiu staras firma en sia koro, havante nenian neceson, sed regas sian propran volon, kaj decidis en sia koro gardi sian virgulinon, faras bone.","Sed tiu, kiu staras firma en sia koro, havante nenian neceson, sed regas sian propran volon, kaj decidis en sia koro gardi sian virgulinon, faras bone."],[7,38,"Tiel tiu, kiu lasas sian virgulinon edziniĝi, faras bone; kaj tiu, kiu ne lasas ŝin edziniĝi, faros pli bone.","Tiel tiu, kiu lasas sian virgulinon edziniĝi, faras bone; kaj tiu, kiu ne lasas ŝin edziniĝi, faros pli bone."],[7,39,"Edzino estas ligita tiel longe, kiel vivas ŝia edzo; sed se la edzo mortis, ŝi estas libera edziniĝi kun iu, kun kiu ŝi volas; nur en la Sinjoro.","Edzino estas ligita tiel longe, kiel vivas ŝia edzo; sed se la edzo mortis, ŝi estas libera edziniĝi kun iu, kun kiu ŝi volas; nur en la Sinjoro."],[7,40,"Sed laŭ mia opinio ŝi estas pli feliĉa, se ŝi restas samstate; kaj mi opinias, ke mi ankaŭ havas la Spiriton de Dio.","Sed laŭ mia opinio ŝi estas pli feliĉa, se ŝi restas samstate; kaj mi opinias, ke mi ankaŭ havas la Spiriton de Dio."],[8,1,"Nun rilate al oferitaĵoj al idoloj: Ni scias, ke ni ĉiuj havas scion. La scio bloveŝveligas, sed la amo edifas.","Nun rilate al oferitaĵoj al idoloj: Ni scias, ke ni ĉiuj havas scion. La scio bloveŝveligas, sed la amo edifas."],[8,2,"Se iu opinias, ke li scias ion, tiu ankoraŭ ne tiel scias, kiel li devus scii;","Se iu opinias, ke li scias ion, tiu ankoraŭ ne tiel scias, kiel li devus scii;"],[8,3,"sed se iu amas Dion, tiu estas konata de Li.","sed se iu amas Dion, tiu estas konata de Li."],[8,4,"Rilate do la manĝadon de la idoloferitaĵoj, ni scias, ke idolo estas neniaĵo en la mondo, kaj ke ne ekzistas Dio krom unu.","Rilate do la manĝadon de la idoloferitaĵoj, ni scias, ke idolo estas neniaĵo en la mondo, kaj ke ne ekzistas Dio krom unu."],[8,5,"Ĉar kvankam estas tiel nomataj dioj, ĉu en la ĉielo aŭ sur la tero, kiel estas dioj multenombraj, kaj sinjoroj multenombraj,","Ĉar kvankam estas tiel nomataj dioj, ĉu en la ĉielo aŭ sur la tero, kiel estas dioj multenombraj, kaj sinjoroj multenombraj,"],[8,6,"tamen por ni estas unu Dio, la Patro, el kiu estas ĉio, kaj ni por Li; kaj unu Sinjoro, Jesuo Kristo, per kiu estas ĉio, kaj ni per li.","tamen por ni estas unu Dio, la Patro, el kiu estas ĉio, kaj ni por Li; kaj unu Sinjoro, Jesuo Kristo, per kiu estas ĉio, kaj ni per li."],[8,7,"Tamen ne ĉe ĉiuj estas tiu scio; sed iuj, pro sia ĝisnuna kutimiĝo al la idolo, manĝas la manĝaĵon kiel oferitaĵon al idolo; kaj ilia konscienco, estante malforta, malpuriĝas.","Tamen ne ĉe ĉiuj estas tiu scio; sed iuj, pro sia ĝisnuna kutimiĝo al la idolo, manĝas la manĝaĵon kiel oferitaĵon al idolo; kaj ilia konscienco, estante malforta, malpuriĝas."],[8,8,"Sed manĝaĵo ne rekomendos nin al Dio; ĉar ni havas nek mankon, se ni ne manĝas, nek profiton, se ni manĝas.","Sed manĝaĵo ne rekomendos nin al Dio; ĉar ni havas nek mankon, se ni ne manĝas, nek profiton, se ni manĝas."],[8,9,"Sed gardu vin, por ke ĉi tiu via libereco ne fariĝu faligilo por la malfortuloj.","Sed gardu vin, por ke ĉi tiu via libereco ne fariĝu faligilo por la malfortuloj."],[8,10,"Ĉar se iu vidas vin, kiu havas scion, sidantan ĉe manĝo en idolejo, ĉu lia konscienco, se li estas malforta, ne kuraĝiĝos manĝi idoloferitaĵojn?","Ĉar se iu vidas vin, kiu havas scion, sidantan ĉe manĝo en idolejo, ĉu lia konscienco, se li estas malforta, ne kuraĝiĝos manĝi idoloferitaĵojn?"],[8,11,"Pro via scio do pereas la malfortulo, la frato, pro kiu Kristo mortis.","Pro via scio do pereas la malfortulo, la frato, pro kiu Kristo mortis."],[8,12,"Kaj tiamaniere, pekante kontraŭ la frataro, kaj vundante ilian konsciencon malfortan, vi pekas kontraŭ Kristo.","Kaj tiamaniere, pekante kontraŭ la frataro, kaj vundante ilian konsciencon malfortan, vi pekas kontraŭ Kristo."],[8,13,"Tial se manĝaĵo maledifas mian fraton, mi neniam plu manĝos karnon, por ke mi ne maledifu mian fraton.","Tial se manĝaĵo maledifas mian fraton, mi neniam plu manĝos karnon, por ke mi ne maledifu mian fraton."],[9,1,"Ĉu mi ne estas libera? ĉu mi ne estas apostolo? ĉu mi ne vidis nian Sinjoron Jesuo? ĉu vi ne estas mia laboraĵo en la Sinjoro?","Ĉu mi ne estas libera? ĉu mi ne estas apostolo? ĉu mi ne vidis nian Sinjoron Jesuo? ĉu vi ne estas mia laboraĵo en la Sinjoro?"],[9,2,"Se ĉe aliaj mi ne estas apostolo, tamen almenaŭ mi estas ĉe vi; ĉar la sigelo de mia apostoleco vi estas en la Sinjoro.","Se ĉe aliaj mi ne estas apostolo, tamen almenaŭ mi estas ĉe vi; ĉar la sigelo de mia apostoleco vi estas en la Sinjoro."],[9,3,"Mia respondo al tiuj, kiuj min ekzamenas, estas jena:","Mia respondo al tiuj, kiuj min ekzamenas, estas jena:"],[9,4,"Ĉu ni ne rajtas manĝi kaj trinki?","Ĉu ni ne rajtas manĝi kaj trinki?"],[9,5,"Ĉu ni ne rajtas ĉirkaŭkonduki edzinon, kiu estas kredantino, kiel ankaŭ la ceteraj apostoloj kaj la fratoj de la Sinjoro kaj Kefas?","Ĉu ni ne rajtas ĉirkaŭkonduki edzinon, kiu estas kredantino, kiel ankaŭ la ceteraj apostoloj kaj la fratoj de la Sinjoro kaj Kefas?"],[9,6,"Aŭ mi sola kaj Barnabas, ĉu ni ne rajtas ĉesi labori?","Aŭ mi sola kaj Barnabas, ĉu ni ne rajtas ĉesi labori?"],[9,7,"Kiu soldato iam deĵoras je sia propra elspezo? kiu plantas vinberĝardenon, kaj ne manĝas ĝian frukton? aŭ kiu paŝtas ŝafaron, kaj ne manĝas el la lakto de la ŝafaro?","Kiu soldato iam deĵoras je sia propra elspezo? kiu plantas vinberĝardenon, kaj ne manĝas ĝian frukton? aŭ kiu paŝtas ŝafaron, kaj ne manĝas el la lakto de la ŝafaro?"],[9,8,"Ĉu mi parolas tion kiel homo? ĉu ne diras la leĝo tion saman?","Ĉu mi parolas tion kiel homo? ĉu ne diras la leĝo tion saman?"],[9,9,"Ĉar estas skribite en la leĝo de Moseo: Ne fermu la buŝon al bovo draŝanta. Ĉu pri la bovoj Dio zorgas?","Ĉar estas skribite en la leĝo de Moseo: Ne fermu la buŝon al bovo draŝanta. Ĉu pri la bovoj Dio zorgas?"],[9,10,"aŭ ĉu Li diras tion tute pro ni? Jes, pro ni ĝi estas skribita; ĉar pluganto devas plugi kun espero, kaj draŝanto devas draŝi kun espero al partopreno.","aŭ ĉu Li diras tion tute pro ni? Jes, pro ni ĝi estas skribita; ĉar pluganto devas plugi kun espero, kaj draŝanto devas draŝi kun espero al partopreno."],[9,11,"Se ni semis al vi spiritajn aferojn, ĉu estas io grava, se ni rikoltos viajn karnajn aferojn?","Se ni semis al vi spiritajn aferojn, ĉu estas io grava, se ni rikoltos viajn karnajn aferojn?"],[9,12,"Se aliaj partoprenas ĉi tiun rajton super vi, ĉu ne ni ankoraŭ pli multe? Tamen ni ne uzis ĉi tiun rajton; sed ni eltenas ĉion, por ke ni neniel malhelpu la evangelion de Kristo.","Se aliaj partoprenas ĉi tiun rajton super vi, ĉu ne ni ankoraŭ pli multe? Tamen ni ne uzis ĉi tiun rajton; sed ni eltenas ĉion, por ke ni neniel malhelpu la evangelion de Kristo."],[9,13,"Ĉu vi ne scias, ke tiuj, kiuj sin okupas pri sanktaj aferoj, manĝas el la templaj manĝaĵoj, kaj tiuj, kiuj deĵoras ĉe la altaro, partoprenas kune kun la altaro?","Ĉu vi ne scias, ke tiuj, kiuj sin okupas pri sanktaj aferoj, manĝas el la templaj manĝaĵoj, kaj tiuj, kiuj deĵoras ĉe la altaro, partoprenas kune kun la altaro?"],[9,14,"Tial same la Sinjoro ordonis, ke la proklamantoj de la evangelio vivadu per la evangelio.","Tial same la Sinjoro ordonis, ke la proklamantoj de la evangelio vivadu per la evangelio."],[9,15,"Sed mi uzis nenion el tiuj rajtoj; kaj mi skribas ĉi tion, ne por ke tio estu farita ĉe mi; ĉar estus pli bone por mi morti, ol se iu vantigus mian fieraĵon.","Sed mi uzis nenion el tiuj rajtoj; kaj mi skribas ĉi tion, ne por ke tio estu farita ĉe mi; ĉar estus pli bone por mi morti, ol se iu vantigus mian fieraĵon."],[9,16,"Ĉar se mi predikas la evangelion, mi havas nenion, pri kio fieri; ĉar neceseco kuŝas sur mi; ĉar ve al mi, se mi ne predikus la evangelion!","Ĉar se mi predikas la evangelion, mi havas nenion, pri kio fieri; ĉar neceseco kuŝas sur mi; ĉar ve al mi, se mi ne predikus la evangelion!"],[9,17,"Ĉar se mi tion faras propravole, mi havas rekompencon; sed se ne propravole, kiel administranto mi estas komisiita.","Ĉar se mi tion faras propravole, mi havas rekompencon; sed se ne propravole, kiel administranto mi estas komisiita."],[9,18,"Kio do estas mia rekompenco? Ke kiam mi predikas la evangelion, mi faru la evangelion senpaga, por ke mi ne plene uzu mian rajton en la evangelio.","Kio do estas mia rekompenco? Ke kiam mi predikas la evangelion, mi faru la evangelion senpaga, por ke mi ne plene uzu mian rajton en la evangelio."],[9,19,"Ĉar estante libera de ĉiuj, mi min sklavigis sub ĉiujn, por ke mi gajnu des pli multajn.","Ĉar estante libera de ĉiuj, mi min sklavigis sub ĉiujn, por ke mi gajnu des pli multajn."],[9,20,"Kaj al la Judoj mi fariĝis kiel Judo, por ke mi gajnu Judojn; al tiuj, kiuj estas sub la leĝo, kiel sub la leĝo, ne estante mem sub la leĝo, por ke mi gajnu tiujn, kiuj estas sub la leĝo;","Kaj al la Judoj mi fariĝis kiel Judo, por ke mi gajnu Judojn; al tiuj, kiuj estas sub la leĝo, kiel sub la leĝo, ne estante mem sub la leĝo, por ke mi gajnu tiujn, kiuj estas sub la leĝo;"],[9,21,"al tiuj, kiuj estas sen leĝo, kiel sen leĝo, ne estante sen leĝo rilate Dion, sed sub leĝo rilate Kriston, por ke mi gajnu tiujn, kiuj estas sen leĝo.","al tiuj, kiuj estas sen leĝo, kiel sen leĝo, ne estante sen leĝo rilate Dion, sed sub leĝo rilate Kriston, por ke mi gajnu tiujn, kiuj estas sen leĝo."],[9,22,"Al la malfortuloj mi fariĝis malforta, por ke mi gajnu la malfortulojn; mi fariĝis ĉio al ĉiuj, por ke mi nepre savu kelkajn.","Al la malfortuloj mi fariĝis malforta, por ke mi gajnu la malfortulojn; mi fariĝis ĉio al ĉiuj, por ke mi nepre savu kelkajn."],[9,23,"Kaj mi faras ĉion pro la evangelio, por ke mi ĝin partoprenu.","Kaj mi faras ĉion pro la evangelio, por ke mi ĝin partoprenu."],[9,24,"Ĉu vi ne scias, ke ĉiuj kurantoj en la areno kuras, sed nur unu ricevas la premion? Tiel same kuru, por ke vi atingu.","Ĉu vi ne scias, ke ĉiuj kurantoj en la areno kuras, sed nur unu ricevas la premion? Tiel same kuru, por ke vi atingu."],[9,25,"Kaj ĉiu konkuranto sin regas en ĉio. Ili faras tion, por ricevi pereontan kronon; sed ni, nepereontan.","Kaj ĉiu konkuranto sin regas en ĉio. Ili faras tion, por ricevi pereontan kronon; sed ni, nepereontan."],[9,26,"Mi do tiel kuras, kiel ne sendecide; tiel mi boksas, kiel ne batante la aeron;","Mi do tiel kuras, kiel ne sendecide; tiel mi boksas, kiel ne batante la aeron;"],[9,27,"sed mi kontuzas mian korpon, kaj ĝin subpremas; por ke mi, predikinte al aliaj, nepre ne estu mem forrifuzata.","sed mi kontuzas mian korpon, kaj ĝin subpremas; por ke mi, predikinte al aliaj, nepre ne estu mem forrifuzata."],[10,1,"Ĉar mi ne volas, fratoj, ke vi ne sciu, ke niaj prapatroj estis ĉiuj sub la nubo, kaj ĉiuj trairis la maron;","Ĉar mi ne volas, fratoj, ke vi ne sciu, ke niaj prapatroj estis ĉiuj sub la nubo, kaj ĉiuj trairis la maron;"],[10,2,"kaj ĉiuj baptiĝis en Moseon en la nubo kaj en la maro;","kaj ĉiuj baptiĝis en Moseon en la nubo kaj en la maro;"],[10,3,"kaj ĉiuj manĝis la saman spiritan manĝaĵon;","kaj ĉiuj manĝis la saman spiritan manĝaĵon;"],[10,4,"kaj ĉiuj trinkis la saman spiritan trinkaĵon; ĉar ili trinkis el spirita roko, kiu ilin sekvis; kaj la roko estis Kristo.","kaj ĉiuj trinkis la saman spiritan trinkaĵon; ĉar ili trinkis el spirita roko, kiu ilin sekvis; kaj la roko estis Kristo."],[10,5,"Tamen la plejmulto el ili ne plaĉis al Dio; ili ja disĵetiĝis en la dezerto.","Tamen la plejmulto el ili ne plaĉis al Dio; ili ja disĵetiĝis en la dezerto."],[10,6,"Sed tio okazis kiel ekzemploj por ni, por ke ni ne deziregu malbonaĵojn, kiel ili ankaŭ deziregis.","Sed tio okazis kiel ekzemploj por ni, por ke ni ne deziregu malbonaĵojn, kiel ili ankaŭ deziregis."],[10,7,"Kaj vi ne estu idolanoj, kiel estis kelkaj el ili; kiel estas skribite: La popolo sidiĝis, por manĝi kaj trinki, kaj ili leviĝis, por ludi.","Kaj vi ne estu idolanoj, kiel estis kelkaj el ili; kiel estas skribite: La popolo sidiĝis, por manĝi kaj trinki, kaj ili leviĝis, por ludi."],[10,8,"Kaj ni ne malĉastadu, kiel kelkaj el ili faris, kaj falis en unu tago dudek tri mil.","Kaj ni ne malĉastadu, kiel kelkaj el ili faris, kaj falis en unu tago dudek tri mil."],[10,9,"Kaj ni ne incitu la Eternulon, kiel kelkaj el ili incitis, kaj pereis per serpentoj.","Kaj ni ne incitu la Eternulon, kiel kelkaj el ili incitis, kaj pereis per serpentoj."],[10,10,"Kaj vi ne murmuru, kiel kelkaj el ili murmuris, kaj pereis per la ekstermanto.","Kaj vi ne murmuru, kiel kelkaj el ili murmuris, kaj pereis per la ekstermanto."],[10,11,"Tio okazis al ili kiel ekzemploj, kaj ĝi estas skribita kiel admono por ni, sur kiujn venis la finoj de la mondaĝoj.","Tio okazis al ili kiel ekzemploj, kaj ĝi estas skribita kiel admono por ni, sur kiujn venis la finoj de la mondaĝoj."],[10,12,"Tiu do, kiu opinias, ke li staras, sin gardu, por ke li ne falu.","Tiu do, kiu opinias, ke li staras, sin gardu, por ke li ne falu."],[10,13,"Nenia tento vin prenis, krom laŭ homa forto; sed fidela estas Dio, kiu ne lasos vin esti tentataj super via forto; sed kune kun la tento ankaŭ faros la forkurejon, por ke vi povu ĝin elporti.","Nenia tento vin prenis, krom laŭ homa forto; sed fidela estas Dio, kiu ne lasos vin esti tentataj super via forto; sed kune kun la tento ankaŭ faros la forkurejon, por ke vi povu ĝin elporti."],[10,14,"Tial, miaj amataj, forsavu vin de idolservado.","Tial, miaj amataj, forsavu vin de idolservado."],[10,15,"Mi parolas kiel al saĝuloj; vi juĝu tion, kion mi diras.","Mi parolas kiel al saĝuloj; vi juĝu tion, kion mi diras."],[10,16,"Ĉu ne estas la kaliko de beno, kiun ni benas, partopreno en la sango de Kristo? Ĉu ne estas la pano, kiun ni dispecigas, partopreno en la korpo de Kristo?","Ĉu ne estas la kaliko de beno, kiun ni benas, partopreno en la sango de Kristo? Ĉu ne estas la pano, kiun ni dispecigas, partopreno en la korpo de Kristo?"],[10,17,"pro tio, ke ni, kiuj estas multaj, estas unu pano, unu korpo; ĉar ni ĉiuj prenas parton el la unu pano.","pro tio, ke ni, kiuj estas multaj, estas unu pano, unu korpo; ĉar ni ĉiuj prenas parton el la unu pano."],[10,18,"Rigardu Izraelon laŭ la karno: ĉu ne estas tiuj, kiuj manĝas la oferojn, partoprenantoj en la altaro?","Rigardu Izraelon laŭ la karno: ĉu ne estas tiuj, kiuj manĝas la oferojn, partoprenantoj en la altaro?"],[10,19,"Kion do mi diras? ke idoloferitaĵo estas io, aŭ ke idolo estas io?","Kion do mi diras? ke idoloferitaĵo estas io, aŭ ke idolo estas io?"],[10,20,"Sed mi diras, ke tion, kion oferas la nacianoj, ili oferas al demonoj, kaj ne al Dio; kaj mi ne volas, ke vi partoprenu kun demonoj.","Sed mi diras, ke tion, kion oferas la nacianoj, ili oferas al demonoj, kaj ne al Dio; kaj mi ne volas, ke vi partoprenu kun demonoj."],[10,21,"Vi ne povas trinki la kalikon de la Sinjoro kaj la kalikon de demonoj; vi ne povas partopreni ĉe la tablo de la Sinjoro kaj ĉe la tablo de demonoj.","Vi ne povas trinki la kalikon de la Sinjoro kaj la kalikon de demonoj; vi ne povas partopreni ĉe la tablo de la Sinjoro kaj ĉe la tablo de demonoj."],[10,22,"Aŭ ĉu ni ĵaluzigas la Sinjoron? ĉu ni estas pli fortaj ol li?","Aŭ ĉu ni ĵaluzigas la Sinjoron? ĉu ni estas pli fortaj ol li?"],[10,23,"Ĉio estas permesata; sed ne ĉio estas oportuna. Ĉio estas permesata; sed ne ĉio edifas.","Ĉio estas permesata; sed ne ĉio estas oportuna. Ĉio estas permesata; sed ne ĉio edifas."],[10,24,"Neniu celu sian bonon, sed ĉiu la bonon de sia proksimulo.","Neniu celu sian bonon, sed ĉiu la bonon de sia proksimulo."],[10,25,"Kion oni vendas en la buĉejo, ĉion manĝu, demandante nenion pro konscienco;","Kion oni vendas en la buĉejo, ĉion manĝu, demandante nenion pro konscienco;"],[10,26,"ĉar al la Eternulo apartenas la tero, kaj ĉio, kio ĝin plenigas.","ĉar al la Eternulo apartenas la tero, kaj ĉio, kio ĝin plenigas."],[10,27,"Se iu el la nekredantoj invitas vin al festeno, kaj vi volas iri, kion oni metas antaŭ vi, ĉion manĝu, demandante nenion pro konscienco.","Se iu el la nekredantoj invitas vin al festeno, kaj vi volas iri, kion oni metas antaŭ vi, ĉion manĝu, demandante nenion pro konscienco."],[10,28,"Sed se iu diras al vi: Ĉi tio estas oferitaĵo — ne manĝu, pro la montrinto, kaj pro konscienco:","Sed se iu diras al vi: Ĉi tio estas oferitaĵo — ne manĝu, pro la montrinto, kaj pro konscienco:"],[10,29,"konscienco, mi diras, ne via propra, sed de la alia; ĉar kial mia libereco estus juĝata per alia konscienco?","konscienco, mi diras, ne via propra, sed de la alia; ĉar kial mia libereco estus juĝata per alia konscienco?"],[10,30,"Se mi danke partoprenas, kial mi estus mallaŭdata pri tio, pro kio mi donas dankon?","Se mi danke partoprenas, kial mi estus mallaŭdata pri tio, pro kio mi donas dankon?"],[10,31,"Ĉu do vi manĝas, aŭ trinkas, aŭ kion ajn vi faras, faru ĉion por la gloro de Dio.","Ĉu do vi manĝas, aŭ trinkas, aŭ kion ajn vi faras, faru ĉion por la gloro de Dio."],[10,32,"Ne metu faligilon, ĉu por Judoj, aŭ por Grekoj, aŭ por la eklezio de Dio;","Ne metu faligilon, ĉu por Judoj, aŭ por Grekoj, aŭ por la eklezio de Dio;"],[10,33,"tiel same, kiel mi ankaŭ plaĉas al ĉiuj en ĉio, celante ne mian propran utilon, sed la utilon de la multaj, por ke ili saviĝu.","tiel same, kiel mi ankaŭ plaĉas al ĉiuj en ĉio, celante ne mian propran utilon, sed la utilon de la multaj, por ke ili saviĝu."],[11,1,"Vi estu imitantoj de mi, kiel mi ankaŭ estas imitanto de Kristo.","Vi estu imitantoj de mi, kiel mi ankaŭ estas imitanto de Kristo."],[11,2,"Mi laŭdas vin, ke vi min memoras en ĉio, kaj ke vi firme tenas la tradiciojn, ĝuste kiel mi transdonis ilin al vi.","Mi laŭdas vin, ke vi min memoras en ĉio, kaj ke vi firme tenas la tradiciojn, ĝuste kiel mi transdonis ilin al vi."],[11,3,"Sed mi volas sciigi vin, ke la kapo de ĉiu viro estas Kristo; kaj la kapo de virino estas viro; kaj la kapo de Kristo estas Dio.","Sed mi volas sciigi vin, ke la kapo de ĉiu viro estas Kristo; kaj la kapo de virino estas viro; kaj la kapo de Kristo estas Dio."],[11,4,"Ĉiu viro, preĝanta aŭ profetanta kun kapo kovrita, malhonoras sian kapon.","Ĉiu viro, preĝanta aŭ profetanta kun kapo kovrita, malhonoras sian kapon."],[11,5,"Sed ĉiu virino, preĝanta aŭ profetanta kun kapo senvuala, malhonoras sian kapon; ĉar tio estas tia sama, kvazaŭ ŝi estus razita.","Sed ĉiu virino, preĝanta aŭ profetanta kun kapo senvuala, malhonoras sian kapon; ĉar tio estas tia sama, kvazaŭ ŝi estus razita."],[11,6,"Ĉar se virino ne estas vualita, ŝi ankaŭ tondiĝu; sed se estas hontinde por virino esti kun haroj tonditaj aŭ razitaj, ŝi estu vualita.","Ĉar se virino ne estas vualita, ŝi ankaŭ tondiĝu; sed se estas hontinde por virino esti kun haroj tonditaj aŭ razitaj, ŝi estu vualita."],[11,7,"Ĉar viro devas ne havi la kapon vualita, pro tio, ke li estas la bildo kaj gloro de Dio; sed virino estas la gloro de viro.","Ĉar viro devas ne havi la kapon vualita, pro tio, ke li estas la bildo kaj gloro de Dio; sed virino estas la gloro de viro."],[11,8,"Ĉar viro ne estas el virino, sed virino el viro;","Ĉar viro ne estas el virino, sed virino el viro;"],[11,9,"ĉar ankaŭ viro ne estas kreita por virino, sed virino por viro;","ĉar ankaŭ viro ne estas kreita por virino, sed virino por viro;"],[11,10,"pro tio virino devas havi sur la kapo signon de aŭtoritato, pro la anĝeloj.","pro tio virino devas havi sur la kapo signon de aŭtoritato, pro la anĝeloj."],[11,11,"Tamen ne ekzistas virino sen viro, nek viro sen virino, en la Sinjoro.","Tamen ne ekzistas virino sen viro, nek viro sen virino, en la Sinjoro."],[11,12,"Ĉar kiel virino estas el viro, tiel same ankaŭ estas viro per virino; sed ĉio estas el Dio.","Ĉar kiel virino estas el viro, tiel same ankaŭ estas viro per virino; sed ĉio estas el Dio."],[11,13,"Juĝu en vi mem: ĉu decas, ke virino preĝu al Dio nevualite?","Juĝu en vi mem: ĉu decas, ke virino preĝu al Dio nevualite?"],[11,14,"Ĉu eĉ la naturo mem ne instruas vin, ke se viro havas longajn harojn, tio estas por li malhonoro?","Ĉu eĉ la naturo mem ne instruas vin, ke se viro havas longajn harojn, tio estas por li malhonoro?"],[11,15,"Sed se virino havas longajn harojn, tio estas por ŝi gloro; ĉar ŝiaj haroj estas donitaj al ŝi kiel kovraĵo.","Sed se virino havas longajn harojn, tio estas por ŝi gloro; ĉar ŝiaj haroj estas donitaj al ŝi kiel kovraĵo."],[11,16,"Sed se iu ŝajnas esti disputema, ni ne havas tian kutimon, nek la eklezioj de Dio.","Sed se iu ŝajnas esti disputema, ni ne havas tian kutimon, nek la eklezioj de Dio."],[11,17,"Sed ordonante al vi jene, mi ne laŭdas vin, ke vi kunvenas ne por pliboniĝo, sed por malpliboniĝo.","Sed ordonante al vi jene, mi ne laŭdas vin, ke vi kunvenas ne por pliboniĝo, sed por malpliboniĝo."],[11,18,"Ĉar unue mi aŭdas, ke kiam vi kunvenas en la eklezio, ekzistas inter vi skismoj; kaj mi parte kredas tion.","Ĉar unue mi aŭdas, ke kiam vi kunvenas en la eklezio, ekzistas inter vi skismoj; kaj mi parte kredas tion."],[11,19,"Ĉar necese estas, ke ankaŭ herezoj estu inter vi, por ke la aprobitoj evidentiĝu inter vi.","Ĉar necese estas, ke ankaŭ herezoj estu inter vi, por ke la aprobitoj evidentiĝu inter vi."],[11,20,"Kiam do vi kunvenas, estas neeble manĝi la Sinjoran vespermanĝon;","Kiam do vi kunvenas, estas neeble manĝi la Sinjoran vespermanĝon;"],[11,21,"ĉar en via manĝado ĉiu antaŭ alia prenas sian propran vespermanĝon; kaj unu malsatas, kaj alia drinkas.","ĉar en via manĝado ĉiu antaŭ alia prenas sian propran vespermanĝon; kaj unu malsatas, kaj alia drinkas."],[11,22,"Kio? ĉu vi ne havas domojn, en kiuj vi povas manĝi kaj trinki? aŭ ĉu vi malestimas la eklezion de Dio, kaj hontigas la nehavantojn? Kion mi diros? ĉu mi vin laŭdos en tio? Mi ja vin ne laŭdas.","Kio? ĉu vi ne havas domojn, en kiuj vi povas manĝi kaj trinki? aŭ ĉu vi malestimas la eklezion de Dio, kaj hontigas la nehavantojn? Kion mi diros? ĉu mi vin laŭdos en tio? Mi ja vin ne laŭdas."],[11,23,"Ĉar mi ricevis de la Sinjoro tion, kion mi ankaŭ transdonis al vi, ke la Sinjoro Jesuo en la nokto, en kiu li estis perfidata, prenis panon;","Ĉar mi ricevis de la Sinjoro tion, kion mi ankaŭ transdonis al vi, ke la Sinjoro Jesuo en la nokto, en kiu li estis perfidata, prenis panon;"],[11,24,"kaj doninte dankon, li dispecigis ĝin, kaj diris: Ĉio tio estas mia korpo, kiu estas por vi; ĉi tion faru por memorigo pri mi.","kaj doninte dankon, li dispecigis ĝin, kaj diris: Ĉio tio estas mia korpo, kiu estas por vi; ĉi tion faru por memorigo pri mi."],[11,25,"Tiel same ankaŭ la kalikon post la vespermanĝo, dirante: Ĉi tiu kaliko estas la nova interligo en mia sango; ĉi tion faru ĉiufoje, kiam vi trinkos, por memorigo pri mi.","Tiel same ankaŭ la kalikon post la vespermanĝo, dirante: Ĉi tiu kaliko estas la nova interligo en mia sango; ĉi tion faru ĉiufoje, kiam vi trinkos, por memorigo pri mi."],[11,26,"Ĉar ĉiufoje, kiam vi manĝos ĉi tiun panon kaj trinkos la kalikon, vi proklamos la morton de la Sinjoro, ĝis li venos.","Ĉar ĉiufoje, kiam vi manĝos ĉi tiun panon kaj trinkos la kalikon, vi proklamos la morton de la Sinjoro, ĝis li venos."],[11,27,"Tial ĉiu, kiu neinde manĝos la panon aŭ trinkos la kalikon de la Sinjoro, kulpiĝos pri la korpo kaj la sango de la Sinjoro.","Tial ĉiu, kiu neinde manĝos la panon aŭ trinkos la kalikon de la Sinjoro, kulpiĝos pri la korpo kaj la sango de la Sinjoro."],[11,28,"Sed oni sin provu, kaj tiele manĝu el la pano kaj trinku el la kaliko.","Sed oni sin provu, kaj tiele manĝu el la pano kaj trinku el la kaliko."],[11,29,"Ĉar la manĝanto kaj trinkanto manĝas kaj trinkas juĝon al si mem, se li ne pripensas la korpon.","Ĉar la manĝanto kaj trinkanto manĝas kaj trinkas juĝon al si mem, se li ne pripensas la korpon."],[11,30,"Pro tio multaj inter vi estas malfortaj kaj malsanaj, kaj ne malmultaj dormas.","Pro tio multaj inter vi estas malfortaj kaj malsanaj, kaj ne malmultaj dormas."],[11,31,"Sed se ni pripensus nin mem, ni ne estus juĝitaj.","Sed se ni pripensus nin mem, ni ne estus juĝitaj."],[11,32,"Sed kiam ni estas juĝataj, ni estas punataj de la Sinjoro, por ke ni ne estu kondamnitaj kune kun la mondo.","Sed kiam ni estas juĝataj, ni estas punataj de la Sinjoro, por ke ni ne estu kondamnitaj kune kun la mondo."],[11,33,"Tial, miaj fratoj, kiam vi kunvenas por manĝi, atendu unu la alian.","Tial, miaj fratoj, kiam vi kunvenas por manĝi, atendu unu la alian."],[11,34,"Se iu malsatas, li manĝu hejme, por ke via kunvenado ne enkonduku juĝon. Kaj la ceteron mi ordigos, kiam mi venos.","Se iu malsatas, li manĝu hejme, por ke via kunvenado ne enkonduku juĝon. Kaj la ceteron mi ordigos, kiam mi venos."],[12,1,"Rilate spiritajn donacojn, fratoj, mi ne volas, ke vi estu nesciantaj.","Rilate spiritajn donacojn, fratoj, mi ne volas, ke vi estu nesciantaj."],[12,2,"Vi scias, ke kiam vi estis nacianoj, vi estis forkondukataj al tiuj mutaj idoloj, kiel ajn oni vin kondukis.","Vi scias, ke kiam vi estis nacianoj, vi estis forkondukataj al tiuj mutaj idoloj, kiel ajn oni vin kondukis."],[12,3,"Tial mi sciigas vin, ke neniu parolanta en la Spirito de Dio diras: Jesuo estas anatemita; kaj neniu povas diri: Jesuo estas Sinjoro, krom per la Sankta Spirito.","Tial mi sciigas vin, ke neniu parolanta en la Spirito de Dio diras: Jesuo estas anatemita; kaj neniu povas diri: Jesuo estas Sinjoro, krom per la Sankta Spirito."],[12,4,"Ekzistas diverseco de donacoj, sed la sama Spirito.","Ekzistas diverseco de donacoj, sed la sama Spirito."],[12,5,"Kaj ekzistas diverseco de servoj, kaj la sama Sinjoro.","Kaj ekzistas diverseco de servoj, kaj la sama Sinjoro."],[12,6,"Kaj ekzistas diverseco de energioj, sed la sama Dio, kiu energias ĉion en ĉiuj.","Kaj ekzistas diverseco de energioj, sed la sama Dio, kiu energias ĉion en ĉiuj."],[12,7,"Sed al ĉiu estas donita la elmontro de la Spirito por utilo.","Sed al ĉiu estas donita la elmontro de la Spirito por utilo."],[12,8,"Ĉar al unu estas donita per la Spirito la vorto de saĝeco; kaj al alia, la vorto de scio, laŭ la sama Spirito;","Ĉar al unu estas donita per la Spirito la vorto de saĝeco; kaj al alia, la vorto de scio, laŭ la sama Spirito;"],[12,9,"al alia, fido, en la sama Spirito; al alia, donacoj de resanigoj, en la unu Spirito;","al alia, fido, en la sama Spirito; al alia, donacoj de resanigoj, en la unu Spirito;"],[12,10,"kaj al alia, energioj por mirakloj; kaj al alia, profetpovo; kaj al alia, distingoj de spiritoj; al alia, diversaj lingvoj; kaj al alia, interpreto de lingvoj;","kaj al alia, energioj por mirakloj; kaj al alia, profetpovo; kaj al alia, distingoj de spiritoj; al alia, diversaj lingvoj; kaj al alia, interpreto de lingvoj;"],[12,11,"sed ĉion tion energias la unu sama Spirito, dividante al ĉiu aparte, kiel al li plaĉas.","sed ĉion tion energias la unu sama Spirito, dividante al ĉiu aparte, kiel al li plaĉas."],[12,12,"Ĉar kiel la korpo estas unu, kaj havas multajn membrojn, kaj ĉiuj membroj de la korpo, estante multaj, estas unu korpo; tiel same ankaŭ estas Kristo.","Ĉar kiel la korpo estas unu, kaj havas multajn membrojn, kaj ĉiuj membroj de la korpo, estante multaj, estas unu korpo; tiel same ankaŭ estas Kristo."],[12,13,"Ĉar en unu Spirito ni ĉiuj baptiĝis en unu korpon, ĉu Judoj aŭ Grekoj, ĉu sklavoj aŭ liberaj; kaj ĉiuj estas trinkigitaj el unu Spirito.","Ĉar en unu Spirito ni ĉiuj baptiĝis en unu korpon, ĉu Judoj aŭ Grekoj, ĉu sklavoj aŭ liberaj; kaj ĉiuj estas trinkigitaj el unu Spirito."],[12,14,"Ĉar la korpo estas ne unu membro, sed multaj.","Ĉar la korpo estas ne unu membro, sed multaj."],[12,15,"Se la piedo diros: Pro tio, ke mi ne estas la mano, mi ne apartenas al la korpo — ne sekvas de tio, ke ĝi ne apartenas al la korpo.","Se la piedo diros: Pro tio, ke mi ne estas la mano, mi ne apartenas al la korpo — ne sekvas de tio, ke ĝi ne apartenas al la korpo."],[12,16,"Kaj se la orelo diros: Pro tio, ke mi ne estas la okulo, mi ne apartenas al la korpo — ne sekvas de tio, ke ĝi ne apartenas al la korpo.","Kaj se la orelo diros: Pro tio, ke mi ne estas la okulo, mi ne apartenas al la korpo — ne sekvas de tio, ke ĝi ne apartenas al la korpo."],[12,17,"Se la tuta korpo estus okulo, kie estus la aŭdado? Se la tuta estus aŭdado, kie estus la flarado?","Se la tuta korpo estus okulo, kie estus la aŭdado? Se la tuta estus aŭdado, kie estus la flarado?"],[12,18,"Sed Dio jam metis la membrojn al la korpo, ĉiun, kiel al Li plaĉis.","Sed Dio jam metis la membrojn al la korpo, ĉiun, kiel al Li plaĉis."],[12,19,"Kaj se ĉiuj estus unu membro, kie estus la korpo?","Kaj se ĉiuj estus unu membro, kie estus la korpo?"],[12,20,"Nun do ekzistas multaj membroj, sed unu korpo.","Nun do ekzistas multaj membroj, sed unu korpo."],[12,21,"Kaj la okulo ne povas diri al la mano: Mi vin ne bezonas; nek same la kapo al la piedoj: Mi vin ne bezonas.","Kaj la okulo ne povas diri al la mano: Mi vin ne bezonas; nek same la kapo al la piedoj: Mi vin ne bezonas."],[12,22,"Sed multe plie la ŝajne malfortaj membroj de la korpo estas necesaj;","Sed multe plie la ŝajne malfortaj membroj de la korpo estas necesaj;"],[12,23,"kaj al tiuj partoj de la korpo, kiujn ni opinias malpli honorindaj, ni donas pli abundan honoron; kaj niaj negraciaj partoj havas pli abundan gracion;","kaj al tiuj partoj de la korpo, kiujn ni opinias malpli honorindaj, ni donas pli abundan honoron; kaj niaj negraciaj partoj havas pli abundan gracion;"],[12,24,"sed niaj graciaj partoj ne havas bezonon; tamen Dio kunakordigis la korpon, doninte pli abundan honoron al la parto, kiu havas mankon,","sed niaj graciaj partoj ne havas bezonon; tamen Dio kunakordigis la korpon, doninte pli abundan honoron al la parto, kiu havas mankon,"],[12,25,"por ke ne estu skismo en la korpo; sed ke la membroj prizorgu egale unu la alian.","por ke ne estu skismo en la korpo; sed ke la membroj prizorgu egale unu la alian."],[12,26,"Kaj se unu membro suferas, ĉiuj membroj kune suferas; aŭ se unu membro honoriĝas, ĉiuj membroj kunĝojas.","Kaj se unu membro suferas, ĉiuj membroj kune suferas; aŭ se unu membro honoriĝas, ĉiuj membroj kunĝojas."],[12,27,"Vi do estas la korpo de Kristo, kaj membroj en ĝi, ĉiu laŭ sia parto.","Vi do estas la korpo de Kristo, kaj membroj en ĝi, ĉiu laŭ sia parto."],[12,28,"Kaj Dio metis iujn en la eklezio, unue apostolojn, due profetojn, trie instruantojn, poste miraklojn, poste donacojn de kuracado, helpojn, direktojn, diversajn lingvojn.","Kaj Dio metis iujn en la eklezio, unue apostolojn, due profetojn, trie instruantojn, poste miraklojn, poste donacojn de kuracado, helpojn, direktojn, diversajn lingvojn."],[12,29,"Ĉu ĉiuj estas apostoloj? ĉu ĉiuj profetoj? ĉu ĉiuj instruantoj? ĉu ĉiuj mirakluloj?","Ĉu ĉiuj estas apostoloj? ĉu ĉiuj profetoj? ĉu ĉiuj instruantoj? ĉu ĉiuj mirakluloj?"],[12,30,"ĉu ĉiuj havas kuracan povon? ĉu ĉiuj parolas per lingvoj? ĉu ĉiuj interpretas?","ĉu ĉiuj havas kuracan povon? ĉu ĉiuj parolas per lingvoj? ĉu ĉiuj interpretas?"],[12,31,"Sed vi deziru forte la pligrandajn donacojn. Kaj ankoraŭ pli preferindan vojon mi montras al vi.","Sed vi deziru forte la pligrandajn donacojn. Kaj ankoraŭ pli preferindan vojon mi montras al vi."],[13,1,"Se mi parolus la lingvojn de homoj kaj anĝeloj, sed ne havus amon, mi fariĝus sonanta kupro aŭ tintanta cimbalo.","Se mi parolus la lingvojn de homoj kaj anĝeloj, sed ne havus amon, mi fariĝus sonanta kupro aŭ tintanta cimbalo."],[13,2,"Kaj se mi posedus la profetpovon, kaj komprenus ĉiujn misterojn kaj ĉian scion; kaj se mi havus ĉian fidon, tiel ke mi povus formovi montojn, sed ne havus amon, mi estus nenio.","Kaj se mi posedus la profetpovon, kaj komprenus ĉiujn misterojn kaj ĉian scion; kaj se mi havus ĉian fidon, tiel ke mi povus formovi montojn, sed ne havus amon, mi estus nenio."],[13,3,"Kaj se mi disdonus mian tutan havon por nutri la malsatulojn, kaj se mi lasus mian korpon por forbrulo, sed ne havus amon, per tio mi neniom profitus.","Kaj se mi disdonus mian tutan havon por nutri la malsatulojn, kaj se mi lasus mian korpon por forbrulo, sed ne havus amon, per tio mi neniom profitus."],[13,4,"Amo longe suferas, kaj bonfaras; amo ne envias; amo ne fanfaronas, ne ŝveligas sin,","Amo longe suferas, kaj bonfaras; amo ne envias; amo ne fanfaronas, ne ŝveligas sin,"],[13,5,"ne kondutas nedece, ne celas por si mem, ne koleriĝas, ne pripensas malbonon,","ne kondutas nedece, ne celas por si mem, ne koleriĝas, ne pripensas malbonon,"],[13,6,"ne ĝojas pri maljusteco, sed kunĝojas kun vereco;","ne ĝojas pri maljusteco, sed kunĝojas kun vereco;"],[13,7,"ĉion toleras, ĉion kredas, ĉion esperas, ĉion eltenas.","ĉion toleras, ĉion kredas, ĉion esperas, ĉion eltenas."],[13,8,"Amo neniam pereas; sed, ĉu estas profetadoj, ili neniiĝos; ĉu lingvoj, ili ĉesiĝos; ĉu estas scio, ĝi neniiĝos.","Amo neniam pereas; sed, ĉu estas profetadoj, ili neniiĝos; ĉu lingvoj, ili ĉesiĝos; ĉu estas scio, ĝi neniiĝos."],[13,9,"Ĉar ni scias laŭparte, kaj ni profetadas laŭparte;","Ĉar ni scias laŭparte, kaj ni profetadas laŭparte;"],[13,10,"sed kiam venos perfektaĵo, tiam neniiĝos tio, kio estas laŭparta.","sed kiam venos perfektaĵo, tiam neniiĝos tio, kio estas laŭparta."],[13,11,"Kiam mi estis infano, kiel infano mi parolis, kiel infano mi sentis, kiel infano mi pensis; nun fariĝinte plenaĝulo, mi jam forigis la infanaĵojn.","Kiam mi estis infano, kiel infano mi parolis, kiel infano mi sentis, kiel infano mi pensis; nun fariĝinte plenaĝulo, mi jam forigis la infanaĵojn."],[13,12,"Ĉar nun ni vidas per spegulo, malhele; sed tiam okulon ĉe okulo; nun mi konas laŭparte; sed tiam mi konos tiel same, kiel ankaŭ mi estas konita.","Ĉar nun ni vidas per spegulo, malhele; sed tiam okulon ĉe okulo; nun mi konas laŭparte; sed tiam mi konos tiel same, kiel ankaŭ mi estas konita."],[13,13,"Restas do nun fido, espero, amo, tiuj tri; kaj la plej granda el ili estas amo.","Restas do nun fido, espero, amo, tiuj tri; kaj la plej granda el ili estas amo."],[14,1,"Sekvu amon; tamen deziregu spiritajn donacojn, sed prefere, ke vi profetadu.","Sekvu amon; tamen deziregu spiritajn donacojn, sed prefere, ke vi profetadu."],[14,2,"Ĉar tiu, kiu per lingvo parolas, ne al homoj parolas, sed al Dio; ĉar neniu komprenas, sed en la spirito li parolas misterojn.","Ĉar tiu, kiu per lingvo parolas, ne al homoj parolas, sed al Dio; ĉar neniu komprenas, sed en la spirito li parolas misterojn."],[14,3,"Sed la profetanto parolas al homoj edifon kaj konsilon kaj konsolon.","Sed la profetanto parolas al homoj edifon kaj konsilon kaj konsolon."],[14,4,"Tiu, kiu per lingvo parolas, edifas sin mem; sed la profetanto edifas la eklezion.","Tiu, kiu per lingvo parolas, edifas sin mem; sed la profetanto edifas la eklezion."],[14,5,"Mi volas, ke vi ĉiuj parolu per lingvoj, sed prefere, ke vi profetadu; kaj pli granda estas la profetanto, ol la per lingvoj parolanta, krom se li ankaŭ interpretas, por ke la eklezio ricevu edifon.","Mi volas, ke vi ĉiuj parolu per lingvoj, sed prefere, ke vi profetadu; kaj pli granda estas la profetanto, ol la per lingvoj parolanta, krom se li ankaŭ interpretas, por ke la eklezio ricevu edifon."],[14,6,"Sed nun, fratoj, se mi venus al vi, parolante per lingvoj, kiel mi vin helpus, se mi ne parolus al vi, aŭ en formo de malkaŝado, aŭ de sciado, aŭ de profetado, aŭ de instruado?","Sed nun, fratoj, se mi venus al vi, parolante per lingvoj, kiel mi vin helpus, se mi ne parolus al vi, aŭ en formo de malkaŝado, aŭ de sciado, aŭ de profetado, aŭ de instruado?"],[14,7,"Eĉ la senvivaĵoj, kiuj produktas sonon, ĉu fluto, ĉu harpo, se ili ne donas diferencon en la sonoj, kiel oni scios, kio estas flutata aŭ harpata?","Eĉ la senvivaĵoj, kiuj produktas sonon, ĉu fluto, ĉu harpo, se ili ne donas diferencon en la sonoj, kiel oni scios, kio estas flutata aŭ harpata?"],[14,8,"Ĉar se la trumpeto donos necertan voĉon, kiu pretiĝos por batalo?","Ĉar se la trumpeto donos necertan voĉon, kiu pretiĝos por batalo?"],[14,9,"Tiel ankaŭ vi, se vi per la lango ne donas parolon facile kompreneblan, kiel oni scios, kio estas parolata? ĉar en la aeron vi parolus.","Tiel ankaŭ vi, se vi per la lango ne donas parolon facile kompreneblan, kiel oni scios, kio estas parolata? ĉar en la aeron vi parolus."],[14,10,"Eble estas tiom da specoj de voĉoj en la mondo, kaj nenia estas sensignifa.","Eble estas tiom da specoj de voĉoj en la mondo, kaj nenia estas sensignifa."],[14,11,"Se do mi ne scios la signifon de la voĉo, mi estos, rilate la parolanton, barbaro, kaj la parolanto estos por mi barbaro.","Se do mi ne scios la signifon de la voĉo, mi estos, rilate la parolanton, barbaro, kaj la parolanto estos por mi barbaro."],[14,12,"Tiel same ankaŭ vi, dum vi fervore deziras spiritajn donacojn, klopodu, ke vi havu abunde por la edifo de la eklezio.","Tiel same ankaŭ vi, dum vi fervore deziras spiritajn donacojn, klopodu, ke vi havu abunde por la edifo de la eklezio."],[14,13,"Tial kiu parolas per lingvo, tiu preĝu, ke li interpretu.","Tial kiu parolas per lingvo, tiu preĝu, ke li interpretu."],[14,14,"Ĉar se mi preĝas per lingvo, mia spirito preĝas, sed mia intelekto estas senfrukta.","Ĉar se mi preĝas per lingvo, mia spirito preĝas, sed mia intelekto estas senfrukta."],[14,15,"Kio do estas? Mi preĝos spirite, kaj mi preĝos ankaŭ intelekte; mi kantos spirite, kaj mi kantos ankaŭ intelekte.","Kio do estas? Mi preĝos spirite, kaj mi preĝos ankaŭ intelekte; mi kantos spirite, kaj mi kantos ankaŭ intelekte."],[14,16,"Alie, se vi benas spirite, kiamaniere tiu, kiu okupas la lokon de la malklerulo, diros Amen ĉe via dankesprimo? ĉar li ne scias, kion vi diras.","Alie, se vi benas spirite, kiamaniere tiu, kiu okupas la lokon de la malklerulo, diros Amen ĉe via dankesprimo? ĉar li ne scias, kion vi diras."],[14,17,"Ĉar vi ja bone dankesprimas, sed la alia ne estas edifata.","Ĉar vi ja bone dankesprimas, sed la alia ne estas edifata."],[14,18,"Mi dankas Dion, mi parolas per lingvoj pli ol vi ĉiuj;","Mi dankas Dion, mi parolas per lingvoj pli ol vi ĉiuj;"],[14,19,"tamen en la eklezio mi preferus paroli kvin vortojn per mia intelekto, por ke mi instruu ankaŭ aliajn, ol dek mil vortojn per lingvo.","tamen en la eklezio mi preferus paroli kvin vortojn per mia intelekto, por ke mi instruu ankaŭ aliajn, ol dek mil vortojn per lingvo."],[14,20,"Fratoj, ne estu infanoj en viaj mensoj; tamen en malico estu infanetoj, sed en la mensoj estu plenaĝuloj.","Fratoj, ne estu infanoj en viaj mensoj; tamen en malico estu infanetoj, sed en la mensoj estu plenaĝuloj."],[14,21,"En la leĝo estas skribite: Per balbutantaj lipoj kaj per lingvo fremda Mi parolos al ĉi tiu popolo; kaj tamen tiel ili ne volos aŭskulti Min, diras la Eternulo.","En la leĝo estas skribite: Per balbutantaj lipoj kaj per lingvo fremda Mi parolos al ĉi tiu popolo; kaj tamen tiel ili ne volos aŭskulti Min, diras la Eternulo."],[14,22,"Tial la lingvoj estas kiel signo, ne al la kredantoj, sed al la nekredantoj; sed la profetpovo estas kiel signo, ne al la nekredantoj, sed al la kredantoj.","Tial la lingvoj estas kiel signo, ne al la kredantoj, sed al la nekredantoj; sed la profetpovo estas kiel signo, ne al la nekredantoj, sed al la kredantoj."],[14,23,"Se do la tuta eklezio kunvenos, kaj ĉiuj parolos per lingvoj, kaj tien envenos nekleruloj aŭ nekredantoj, ĉu ili ne diros, ke vi frenezas?","Se do la tuta eklezio kunvenos, kaj ĉiuj parolos per lingvoj, kaj tien envenos nekleruloj aŭ nekredantoj, ĉu ili ne diros, ke vi frenezas?"],[14,24,"Sed se ĉiuj profetos, kaj envenos nekredanto aŭ neklerulo, li estos konvinkata de ĉiuj, li estos juĝata de ĉiuj;","Sed se ĉiuj profetos, kaj envenos nekredanto aŭ neklerulo, li estos konvinkata de ĉiuj, li estos juĝata de ĉiuj;"],[14,25,"la sekretoj de lia koro estos elmontrataj; kaj sekve li falos sur sian vizaĝon kaj adoros Dion, deklarante, ke Dio ja estas ĉe vi.","la sekretoj de lia koro estos elmontrataj; kaj sekve li falos sur sian vizaĝon kaj adoros Dion, deklarante, ke Dio ja estas ĉe vi."],[14,26,"Kio do estas, fratoj? Kiam vi kunvenas, ĉiu havas psalmon, havas instruon, havas malkaŝaĵon, havas lingvon, havas interpretaĵon. Ĉio fariĝu por edifo.","Kio do estas, fratoj? Kiam vi kunvenas, ĉiu havas psalmon, havas instruon, havas malkaŝaĵon, havas lingvon, havas interpretaĵon. Ĉio fariĝu por edifo."],[14,27,"Se oni parolas per lingvo, tio estu duope, aŭ triope je plejmulto, kaj laŭvice; kaj unu interpretu;","Se oni parolas per lingvo, tio estu duope, aŭ triope je plejmulto, kaj laŭvice; kaj unu interpretu;"],[14,28,"sed se ne ĉeestas interpretanto, oni silentu en la eklezio; kaj li parolu al si kaj al Dio.","sed se ne ĉeestas interpretanto, oni silentu en la eklezio; kaj li parolu al si kaj al Dio."],[14,29,"Kaj la profetoj parolu duope aŭ triope, kaj la aliaj interdiferencigu.","Kaj la profetoj parolu duope aŭ triope, kaj la aliaj interdiferencigu."],[14,30,"Sed se al alia apudsidanta io malkaŝiĝos, la unua silentu.","Sed se al alia apudsidanta io malkaŝiĝos, la unua silentu."],[14,31,"Ĉar vi ĉiuj povas profeti unuope laŭvice, por ke ĉiuj lernu, kaj ĉiuj ricevu konsilon;","Ĉar vi ĉiuj povas profeti unuope laŭvice, por ke ĉiuj lernu, kaj ĉiuj ricevu konsilon;"],[14,32,"kaj la spiritoj de la profetoj estas submetataj al la profetoj;","kaj la spiritoj de la profetoj estas submetataj al la profetoj;"],[14,33,"ĉar Dio estas Dio ne de konfuzo, sed de paco; kiel en ĉiuj eklezioj de la sanktuloj.","ĉar Dio estas Dio ne de konfuzo, sed de paco; kiel en ĉiuj eklezioj de la sanktuloj."],[14,34,"La virinoj silentadu en la eklezioj; ĉar ne estas permesate al ili paroli, sed ili submetiĝu, kiel ankaŭ diras la leĝo.","La virinoj silentadu en la eklezioj; ĉar ne estas permesate al ili paroli, sed ili submetiĝu, kiel ankaŭ diras la leĝo."],[14,35,"Kaj se ili volas lerni ion, ili demandu al siaj edzoj hejme; ĉar estas honte por virino paroli en la eklezio.","Kaj se ili volas lerni ion, ili demandu al siaj edzoj hejme; ĉar estas honte por virino paroli en la eklezio."],[14,36,"Kio? ĉu el vi la vorto de Dio eliris? ĉu ĝi venis al vi solaj?","Kio? ĉu el vi la vorto de Dio eliris? ĉu ĝi venis al vi solaj?"],[14,37,"Se iu ŝajnas al si esti profeto aŭ laŭspirita, li sciiĝu pri tio, kion mi skribas al vi, ke ĝi estas la ordono de la Sinjoro.","Se iu ŝajnas al si esti profeto aŭ laŭspirita, li sciiĝu pri tio, kion mi skribas al vi, ke ĝi estas la ordono de la Sinjoro."],[14,38,"Sed se iu ne scias, li ne sciu.","Sed se iu ne scias, li ne sciu."],[14,39,"Tial, fratoj, deziregu profeti, kaj ne malpermesu paroli per lingvoj.","Tial, fratoj, deziregu profeti, kaj ne malpermesu paroli per lingvoj."],[14,40,"Sed ĉio fariĝu konvene kaj laŭorde.","Sed ĉio fariĝu konvene kaj laŭorde."],[15,1,"Kaj mi sciigas vin, fratoj, pri la evangelio, kiun mi predikis al vi, kiun ankaŭ vi ricevis, en kiu ankaŭ vi staras,","Kaj mi sciigas vin, fratoj, pri la evangelio, kiun mi predikis al vi, kiun ankaŭ vi ricevis, en kiu ankaŭ vi staras,"],[15,2,"per kiu vi saviĝis; se vi en memoro tenas, per kiuj vortoj mi ĝin predikis al vi, krom se vi kredis vane.","per kiu vi saviĝis; se vi en memoro tenas, per kiuj vortoj mi ĝin predikis al vi, krom se vi kredis vane."],[15,3,"Ĉar mi transdonis al vi komence tion, kion mi ankaŭ ricevis, ke Kristo mortis pro niaj pekoj laŭ la Skriboj;","Ĉar mi transdonis al vi komence tion, kion mi ankaŭ ricevis, ke Kristo mortis pro niaj pekoj laŭ la Skriboj;"],[15,4,"kaj ke li estis entombigita; kaj ke li releviĝis la trian tagon laŭ la Skriboj;","kaj ke li estis entombigita; kaj ke li releviĝis la trian tagon laŭ la Skriboj;"],[15,5,"kaj ke li aperis al Kefas; poste al la dek du;","kaj ke li aperis al Kefas; poste al la dek du;"],[15,6,"poste li aperis al pli ol kvincent fratoj samtempe, el kiuj la plimulto restas ĝis nun, sed kelkaj jam ekdormis;","poste li aperis al pli ol kvincent fratoj samtempe, el kiuj la plimulto restas ĝis nun, sed kelkaj jam ekdormis;"],[15,7,"poste li aperis al Jakobo; poste al ĉiuj apostoloj;","poste li aperis al Jakobo; poste al ĉiuj apostoloj;"],[15,8,"kaj fine li aperis al mi ankaŭ, kiel al infano ekstertempe naskita.","kaj fine li aperis al mi ankaŭ, kiel al infano ekstertempe naskita."],[15,9,"Ĉar mi estas la plej malgranda el la apostoloj, kaj ne meritas esti nomata apostolo pro tio, ke mi persekutis la eklezion de Dio.","Ĉar mi estas la plej malgranda el la apostoloj, kaj ne meritas esti nomata apostolo pro tio, ke mi persekutis la eklezion de Dio."],[15,10,"Sed per la graco de Dio mi estas tio, kio mi estas; kaj Lia graco donacita al mi montriĝis ne vana; sed mi laboregis pli abunde ol la ceteraj; tamen ne mi, sed la graco de Dio, kiu estis kun mi.","Sed per la graco de Dio mi estas tio, kio mi estas; kaj Lia graco donacita al mi montriĝis ne vana; sed mi laboregis pli abunde ol la ceteraj; tamen ne mi, sed la graco de Dio, kiu estis kun mi."],[15,11,"Ĉu do mi, ĉu ili, tiel ni predikas, kaj tiel vi kredis.","Ĉu do mi, ĉu ili, tiel ni predikas, kaj tiel vi kredis."],[15,12,"Nu, se Kristo estas predikata, ke li releviĝis el la mortintoj, kiel do diras kelkaj el vi, ke ne ekzistas releviĝo de mortintoj?","Nu, se Kristo estas predikata, ke li releviĝis el la mortintoj, kiel do diras kelkaj el vi, ke ne ekzistas releviĝo de mortintoj?"],[15,13,"Sed se ne ekzistas releviĝo de mortintoj, ankaŭ Kristo ne releviĝis;","Sed se ne ekzistas releviĝo de mortintoj, ankaŭ Kristo ne releviĝis;"],[15,14,"kaj se Kristo ne releviĝis, vana ja estas nia predikado, vana ankaŭ estas via fido.","kaj se Kristo ne releviĝis, vana ja estas nia predikado, vana ankaŭ estas via fido."],[15,15,"Jes, kaj ni montriĝas kiel falsaj atestantoj de Dio; tial ke ni atestis pri Dio, ke Li relevis Kriston; kiun Li ne relevis, se la mortintoj ja ne releviĝas.","Jes, kaj ni montriĝas kiel falsaj atestantoj de Dio; tial ke ni atestis pri Dio, ke Li relevis Kriston; kiun Li ne relevis, se la mortintoj ja ne releviĝas."],[15,16,"Ĉar se la mortintoj ne releviĝas, ankaŭ Kristo ne releviĝis;","Ĉar se la mortintoj ne releviĝas, ankaŭ Kristo ne releviĝis;"],[15,17,"kaj se Kristo ne releviĝis, via fido estas vana; vi estas ankoraŭ en viaj pekoj.","kaj se Kristo ne releviĝis, via fido estas vana; vi estas ankoraŭ en viaj pekoj."],[15,18,"Tiuokaze ankaŭ pereis la ekdormintoj en Kristo.","Tiuokaze ankaŭ pereis la ekdormintoj en Kristo."],[15,19,"Se nur en ĉi tiu vivo ni esperis en Kristo, ni estas el ĉiuj homoj la plej mizeraj.","Se nur en ĉi tiu vivo ni esperis en Kristo, ni estas el ĉiuj homoj la plej mizeraj."],[15,20,"Sed nun Kristo releviĝis el la mortintoj, la unuaaĵo de la dormantoj.","Sed nun Kristo releviĝis el la mortintoj, la unuaaĵo de la dormantoj."],[15,21,"Ĉar tial, ke per homo venis la morto, per homo ankaŭ venis la releviĝo de la mortintoj.","Ĉar tial, ke per homo venis la morto, per homo ankaŭ venis la releviĝo de la mortintoj."],[15,22,"Ĉar kiel en Adam ĉiuj mortas, tiel same ankaŭ en Kristo ĉiuj estos vivigitaj.","Ĉar kiel en Adam ĉiuj mortas, tiel same ankaŭ en Kristo ĉiuj estos vivigitaj."],[15,23,"Sed ĉiu en sia propra vico: Kristo la unuaaĵo, poste tiuj, kiuj apartenas al Kristo, ĉe lia alveno.","Sed ĉiu en sia propra vico: Kristo la unuaaĵo, poste tiuj, kiuj apartenas al Kristo, ĉe lia alveno."],[15,24,"Poste venos la fino, kiam li transdonos la reĝecon al Dio, al la Patro; kiam li estos neniiginta ĉian regadon kaj ĉian aŭtoritaton kaj potencon.","Poste venos la fino, kiam li transdonos la reĝecon al Dio, al la Patro; kiam li estos neniiginta ĉian regadon kaj ĉian aŭtoritaton kaj potencon."],[15,25,"Ĉar li devas reĝadi, ĝis li metos ĉiujn malamikojn sub siajn piedojn.","Ĉar li devas reĝadi, ĝis li metos ĉiujn malamikojn sub siajn piedojn."],[15,26,"La lasta neniigota malamiko estas la morto.","La lasta neniigota malamiko estas la morto."],[15,27,"Ĉar: Ĉion Li metis sub liajn piedojn. Sed kiam estas dirate: Ĉio estas submetita, estas evidente, ke esceptita estas Tiu, kiu submetis ĉion al li.","Ĉar: Ĉion Li metis sub liajn piedojn. Sed kiam estas dirate: Ĉio estas submetita, estas evidente, ke esceptita estas Tiu, kiu submetis ĉion al li."],[15,28,"Kaj kiam ĉio estos submetita al li, tiam la Filo ankaŭ mem estos submetita al Tiu, kiu submetis ĉion al li, por ke Dio estu ĉio en ĉio.","Kaj kiam ĉio estos submetita al li, tiam la Filo ankaŭ mem estos submetita al Tiu, kiu submetis ĉion al li, por ke Dio estu ĉio en ĉio."],[15,29,"Alie kion faros tiuj, kiuj baptiĝas pro la mortintoj? Se la mortintoj tute ne releviĝas, kial do ili baptiĝas pro ili?","Alie kion faros tiuj, kiuj baptiĝas pro la mortintoj? Se la mortintoj tute ne releviĝas, kial do ili baptiĝas pro ili?"],[15,30,"kial ni ankaŭ endanĝeriĝas ĉiun horon?","kial ni ankaŭ endanĝeriĝas ĉiun horon?"],[15,31,"Mi asertas per la singratulado pro vi, fratoj, kiun mi havas en Kristo Jesuo, nia Sinjoro, mi mortas ĉiutage.","Mi asertas per la singratulado pro vi, fratoj, kiun mi havas en Kristo Jesuo, nia Sinjoro, mi mortas ĉiutage."],[15,32,"Se laŭ homa maniero mi batalis kontraŭ bestoj en Efeso, kiel mi per tio profitas? Se la mortintoj ne releviĝas, ni manĝu kaj trinku, ĉar morgaŭ ni mortos.","Se laŭ homa maniero mi batalis kontraŭ bestoj en Efeso, kiel mi per tio profitas? Se la mortintoj ne releviĝas, ni manĝu kaj trinku, ĉar morgaŭ ni mortos."],[15,33,"Ne trompiĝu; Malbonaj kuniĝoj malbonigas bonajn morojn.","Ne trompiĝu; Malbonaj kuniĝoj malbonigas bonajn morojn."],[15,34,"Malebriiĝu en justeco, kaj ne peku; ĉar kelkaj havas nenian scion pri Dio; mi tion diras, por hontigi vin.","Malebriiĝu en justeco, kaj ne peku; ĉar kelkaj havas nenian scion pri Dio; mi tion diras, por hontigi vin."],[15,35,"Sed iu diros: Kiel la mortintoj releviĝas? kaj kun kia korpo ili venas?","Sed iu diros: Kiel la mortintoj releviĝas? kaj kun kia korpo ili venas?"],[15,36,"Ho malsaĝulo! tio, kion vi mem semas, ne viviĝas, se ĝi ne mortos;","Ho malsaĝulo! tio, kion vi mem semas, ne viviĝas, se ĝi ne mortos;"],[15,37,"kaj tio, kion vi semas, estas ne la estonta korpo, sed nuda grenero, eble de tritiko, aŭ de alia speco;","kaj tio, kion vi semas, estas ne la estonta korpo, sed nuda grenero, eble de tritiko, aŭ de alia speco;"],[15,38,"sed Dio donas al ĝi korpon, kiel Li volis, kaj al ĉiu semo ĝian propran korpon.","sed Dio donas al ĝi korpon, kiel Li volis, kaj al ĉiu semo ĝian propran korpon."],[15,39,"Ne ĉiu karno estas unu sama karno; sed ekzistas unu karno de homoj, kaj alia de bestoj, kaj alia karno de birdoj, kaj alia de fiŝoj.","Ne ĉiu karno estas unu sama karno; sed ekzistas unu karno de homoj, kaj alia de bestoj, kaj alia karno de birdoj, kaj alia de fiŝoj."],[15,40,"Ekzistas ankaŭ korpoj ĉielaj kaj korpoj teraj; sed la gloro de la ĉielaj estas unu, kaj la gloro de la teraj estas alia.","Ekzistas ankaŭ korpoj ĉielaj kaj korpoj teraj; sed la gloro de la ĉielaj estas unu, kaj la gloro de la teraj estas alia."],[15,41,"Ekzistas unu gloro de la suno, kaj alia gloro de la luno, kaj alia gloro de la steloj; ĉar unu stelo diferencas de alia stelo rilate al gloro.","Ekzistas unu gloro de la suno, kaj alia gloro de la luno, kaj alia gloro de la steloj; ĉar unu stelo diferencas de alia stelo rilate al gloro."],[15,42,"Tia sama ankaŭ estas la releviĝo de la mortintoj. Ĝi estas semata en putreco, ĝi releviĝas en senputreco;","Tia sama ankaŭ estas la releviĝo de la mortintoj. Ĝi estas semata en putreco, ĝi releviĝas en senputreco;"],[15,43,"ĝi estas semata en malhonoro, ĝi releviĝas en gloro; ĝi estas semata en malforteco, ĝi releviĝas en potenco;","ĝi estas semata en malhonoro, ĝi releviĝas en gloro; ĝi estas semata en malforteco, ĝi releviĝas en potenco;"],[15,44,"ĝi estas semata laŭanima korpo, ĝi releviĝas laŭspirita korpo. Se ekzistas laŭanima korpo, ekzistas ankaŭ laŭspirita korpo.","ĝi estas semata laŭanima korpo, ĝi releviĝas laŭspirita korpo. Se ekzistas laŭanima korpo, ekzistas ankaŭ laŭspirita korpo."],[15,45,"Tiele ankaŭ estas skribite: La unua homo Adam fariĝis viva animo. La lasta Adam fariĝis viviganta spirito.","Tiele ankaŭ estas skribite: La unua homo Adam fariĝis viva animo. La lasta Adam fariĝis viviganta spirito."],[15,46,"Tamen unua estas ne tio, kio estas laŭspirita, sed tio, kio estas laŭanima; poste tio, kio estas laŭspirita.","Tamen unua estas ne tio, kio estas laŭspirita, sed tio, kio estas laŭanima; poste tio, kio estas laŭspirita."],[15,47,"La unua homo estas el la tero, elpolva; la dua homo estas el la ĉielo.","La unua homo estas el la tero, elpolva; la dua homo estas el la ĉielo."],[15,48,"Kia estas la elpolvulo, tiaj estas ankaŭ la elpolvuloj; kaj kia estas la elĉielulo, tiaj estas ankaŭ la elĉieluloj.","Kia estas la elpolvulo, tiaj estas ankaŭ la elpolvuloj; kaj kia estas la elĉielulo, tiaj estas ankaŭ la elĉieluloj."],[15,49,"Kaj kiel ni portis la figuron de la elpolvulo, tiel same ni portos la figuron de la elĉielulo.","Kaj kiel ni portis la figuron de la elpolvulo, tiel same ni portos la figuron de la elĉielulo."],[15,50,"Kaj la jenon mi diras, fratoj, ke karno kaj sango ne povas heredi la regnon de Dio; kaj putreco ne heredas senputrecon.","Kaj la jenon mi diras, fratoj, ke karno kaj sango ne povas heredi la regnon de Dio; kaj putreco ne heredas senputrecon."],[15,51,"Jen mi sciigas al vi misteron: Ni ne ĉiuj dormos, sed ni ĉiuj ŝanĝiĝos,","Jen mi sciigas al vi misteron: Ni ne ĉiuj dormos, sed ni ĉiuj ŝanĝiĝos,"],[15,52,"en momento, en okula ekmovo, ĉe la lasta trumpetsono: ĉar la trumpeto sonos, kaj la mortintoj releviĝos senputraj, kaj ni ŝanĝiĝos.","en momento, en okula ekmovo, ĉe la lasta trumpetsono: ĉar la trumpeto sonos, kaj la mortintoj releviĝos senputraj, kaj ni ŝanĝiĝos."],[15,53,"Ĉar estas necese, ke ĉi tiu putrema surmetu senputrecon, kaj ke ĉi tiu mortema surmetu senmortecon.","Ĉar estas necese, ke ĉi tiu putrema surmetu senputrecon, kaj ke ĉi tiu mortema surmetu senmortecon."],[15,54,"Sed kiam ĉi tiu putrema surmetos senputrecon, kaj ĉi tiu mortema surmetos senmortecon, tiam plenumiĝos la skribita diro: La morto forglutiĝis en venko.","Sed kiam ĉi tiu putrema surmetos senputrecon, kaj ĉi tiu mortema surmetos senmortecon, tiam plenumiĝos la skribita diro: La morto forglutiĝis en venko."],[15,55,"Ho morto, kie estas via venko? Ho morto, kie estas via pikilo?","Ho morto, kie estas via venko? Ho morto, kie estas via pikilo?"],[15,56,"La pikilo de la morto estas la peko; kaj la forto de la peko estas la leĝo;","La pikilo de la morto estas la peko; kaj la forto de la peko estas la leĝo;"],[15,57,"sed danko estu al Dio, kiu donas al ni la venkon per nia Sinjoro Jesuo Kristo.","sed danko estu al Dio, kiu donas al ni la venkon per nia Sinjoro Jesuo Kristo."],[15,58,"Tial, miaj amataj fratoj, estu firmaj, nemoveblaj, ĉiam abundaj en la laboro de la Sinjoro, sciante, ke via penado ne estas vanta en la Sinjoro.","Tial, miaj amataj fratoj, estu firmaj, nemoveblaj, ĉiam abundaj en la laboro de la Sinjoro, sciante, ke via penado ne estas vanta en la Sinjoro."],[16,1,"Nun rilate al la monkolekto pro la sanktuloj, kiel mi ordonis al la eklezioj de Galatujo, tiel ankaŭ vi faru.","Nun rilate al la monkolekto pro la sanktuloj, kiel mi ordonis al la eklezioj de Galatujo, tiel ankaŭ vi faru."],[16,2,"La unuan tagon de la semajno, ĉiu el vi provizu ĉe si laŭ tio, kion li prospere akiris, por ke ne estu kolektoj tiam, kiam mi venos.","La unuan tagon de la semajno, ĉiu el vi provizu ĉe si laŭ tio, kion li prospere akiris, por ke ne estu kolektoj tiam, kiam mi venos."],[16,3,"Kaj kiam mi alvenos, kiujn vi per leteroj aprobos, tiujn mi sendos, por alporti vian donacon al Jerusalem;","Kaj kiam mi alvenos, kiujn vi per leteroj aprobos, tiujn mi sendos, por alporti vian donacon al Jerusalem;"],[16,4,"kaj se konvenos, ke mi ankaŭ tien vojaĝu, ili vojaĝos kun mi.","kaj se konvenos, ke mi ankaŭ tien vojaĝu, ili vojaĝos kun mi."],[16,5,"Sed mi venos al vi, kiam mi estos trapasinta Makedonujon; ĉar Makedonujon mi ja trapasos;","Sed mi venos al vi, kiam mi estos trapasinta Makedonujon; ĉar Makedonujon mi ja trapasos;"],[16,6,"sed ĉe vi eble mi restos, aŭ eĉ travintros, por ke vi antaŭen irigu min, kien mi veturos.","sed ĉe vi eble mi restos, aŭ eĉ travintros, por ke vi antaŭen irigu min, kien mi veturos."],[16,7,"Ĉar mi ne volas vidi vin nun dumvojaĝe; ĉar mi esperas resti kelkan tempon ĉe vi, se la Sinjoro permesos.","Ĉar mi ne volas vidi vin nun dumvojaĝe; ĉar mi esperas resti kelkan tempon ĉe vi, se la Sinjoro permesos."],[16,8,"Sed mi restos en Efeso ĝis Pentekosto;","Sed mi restos en Efeso ĝis Pentekosto;"],[16,9,"ĉar pordo granda kaj efika malfermiĝis al mi, kaj estas multaj kontraŭstarantoj.","ĉar pordo granda kaj efika malfermiĝis al mi, kaj estas multaj kontraŭstarantoj."],[16,10,"Se Timoteo venos, zorgu, ke li estu ĉe vi sentime; ĉar li faras la laboron de la Sinjoro, kiel mi ankaŭ;","Se Timoteo venos, zorgu, ke li estu ĉe vi sentime; ĉar li faras la laboron de la Sinjoro, kiel mi ankaŭ;"],[16,11,"neniu do lin malestimu. Sed antaŭen irigu lin en paco, por ke li venu al mi; ĉar mi atendas lin kun la fratoj.","neniu do lin malestimu. Sed antaŭen irigu lin en paco, por ke li venu al mi; ĉar mi atendas lin kun la fratoj."],[16,12,"Sed rilate al la frato Apolos, mi multe petegis lin veni al vi kun la fratoj; sed tute mankis volo veni nun; sed li venos, kiam li havos oportunan tempon.","Sed rilate al la frato Apolos, mi multe petegis lin veni al vi kun la fratoj; sed tute mankis volo veni nun; sed li venos, kiam li havos oportunan tempon."],[16,13,"Viglu, staru firme en la fido, viriĝu, fortiĝu.","Viglu, staru firme en la fido, viriĝu, fortiĝu."],[16,14,"Ĉio via estu farata en amo.","Ĉio via estu farata en amo."],[16,15,"Mi petegas vin, fratoj (vi konas la domon de Stefanas, ke ĝi estas la unuaaĵo de la Aĥaja lando, kaj ke ili sin dediĉis al la servo de la sanktuloj),","Mi petegas vin, fratoj (vi konas la domon de Stefanas, ke ĝi estas la unuaaĵo de la Aĥaja lando, kaj ke ili sin dediĉis al la servo de la sanktuloj),"],[16,16,"ke vi ankaŭ submetiĝu al tiaj, kaj al ĉiu kunhelpanto kaj kunlaboranto.","ke vi ankaŭ submetiĝu al tiaj, kaj al ĉiu kunhelpanto kaj kunlaboranto."],[16,17,"Kaj mi ĝojas pro la alveno de Stefanas kaj Fortunato kaj Aĥaiko, tial, ke vian mankaĵon ili plenigis.","Kaj mi ĝojas pro la alveno de Stefanas kaj Fortunato kaj Aĥaiko, tial, ke vian mankaĵon ili plenigis."],[16,18,"Ĉar ili refreŝigis mian spiriton kaj vian; rekonu do tiajn.","Ĉar ili refreŝigis mian spiriton kaj vian; rekonu do tiajn."],[16,19,"La eklezioj de Azio vin salutas. Akvila kaj Priskila vin salutas multe en la Sinjoro, kune kun la eklezio en ilia domo.","La eklezioj de Azio vin salutas. Akvila kaj Priskila vin salutas multe en la Sinjoro, kune kun la eklezio en ilia domo."],[16,20,"Ĉiuj fratoj vin salutas. Salutu unu la alian per sankta kiso.","Ĉiuj fratoj vin salutas. Salutu unu la alian per sankta kiso."],[16,21,"La saluto de mi, Paŭlo, per mia propra mano.","La saluto de mi, Paŭlo, per mia propra mano."],[16,22,"Se iu ne amas la Sinjoron Jesuo Kristo, li estu anatemita. Maran-ata.","Se iu ne amas la Sinjoron Jesuo Kristo, li estu anatemita. Maran-ata."],[16,23,"La graco de la Sinjoro Jesuo Kristo estu kun vi.","La graco de la Sinjoro Jesuo Kristo estu kun vi."],[16,24,"Mia amo estu kun vi ĉiuj en Kristo Jesuo. Amen.","Mia amo estu kun vi ĉiuj en Kristo Jesuo. Amen."]]}};